__CR('t:compiler',[{"t":"언어는 어떻게 실행되나","l":[{"t":"번역과 실행","q":[{"t":"choice","k":"구분","q":"C 언어는 주로 어떤 방식으로 실행되나요?","o":["둘 다 아니며 어느 쪽도 쓰지 않는다고 실무에서는 꽤 있는 그대로 새겨 두어야 한다","컴파일이다","압축해 두었다가 실행이다","한 줄씩 읽어 가면서 인터프리트한다고 차근차근 알아 두어야 한다"],"a":1,"ex":"C 는 컴파일해서 실행 파일을 만듭니다."},{"t":"choice","k":"구분","q":"Python 은 주로 어떤 방식인가요?","o":["기계어를 사람이 직접 손으로 작성해 두는 것이라고 앞뒤를 나란히 놓고 따져 보면 충분히 어렵지 않게 볼 수 있다","사람이 손으로 하나씩 수동으로 번역한다고 충분히 차근차근 새겨 두어야 한다","인터프리트라고 충분히 차근차근 말할 수 있다","미리 해 두는 사전 컴파일이라고 실제로 차근차근 볼 수 있다"],"a":2,"ex":"Python 은 대표적인 인터프리터 언어입니다."},{"t":"choice","k":"개념","q":"소스코드 전체를 기계어로 미리 번역하는 프로그램은?","o":["글을 적는 데 쓰는 에디터라고 늘 어렵지 않게 할 수 있다","링커만","링커","컴파일러라고 차근차근 새겨 두어야 한다"],"a":3,"ex":"컴파일러는 실행 전에 통째로 번역합니다."},{"t":"choice","k":"개념","q":"코드를 한 줄씩 해석하며 바로 실행하는 것은?","o":["인터프리터","버그를 잡는 디버거 도구라고 흔히 짚어 두어야 한다","포매터","미리 번역해 두는 컴파일러(compiler)라고 대체로 있는 그대로 짚어 두어야 한다"],"a":0,"ex":"인터프리터는 번역과 실행을 함께 합니다."}],"th":{"sum":"사람이 쓴 글자를 기계가 이해하는 말로 **옮기는 일**이 번역이다. 옮기는 시점이 언어마다 다르다.","body":[{"h":"기계는 우리 글자를 모른다","t":"CPU 는 아주 단순한 명령만 안다. 우리가 쓴 `if` 나 `for` 는 그대로는 아무 뜻이 없다. 누군가 이것을 CPU 가 아는 명령으로 바꿔 줘야 하고, 그 일을 하는 것이 컴파일러나 인터프리터다."},{"h":"미리 옮기기 (컴파일)","t":"C 나 Go 는 **실행하기 전에** 통째로 옮겨 둔다. 그래서 돌 때는 빠르고, 문법이 틀리면 실행도 못 해 보고 그 자리에서 걸린다. 잘못을 일찍 발견한다는 것이 가장 큰 장점이다."},{"h":"그때그때 옮기기 (인터프리터)","t":"파이썬은 한 줄씩 읽어 가며 실행한다. 바로 고쳐 보고 바로 돌려 볼 수 있어 편하다. 대신 실행해 보기 전에는 문법이 틀린 줄도 모르고, 같은 일을 반복해도 매번 다시 해석한다."},{"h":"요즘은 섞어 쓴다","t":"자바와 자바스크립트는 일단 돌려 보다가, 자주 도는 자리를 그때 기계어로 바꿔 둔다(JIT). 처음엔 느리다가 점점 빨라지는 이유가 이것이다. '컴파일이냐 인터프리터냐' 로 딱 나뉘지 않는다."}],"code":{"c":"소스 코드\n  → (컴파일) → 실행 파일 → 실행\n  → (인터프리터) → 한 줄씩 바로 실행","cap":"옮기는 시점이 다를 뿐이다"},"key":["기계는 우리 글자를 모른다","미리 옮기면 빠르고 일찍 걸린다","그때그때 옮기면 편하다"]}},{"t":"컴파일 단계","q":[{"t":"choice","k":"용어","q":"파싱 결과로 만들어지는 프로그램의 구조 트리를 뭐라 하나요?","o":["AST(추상 구문 트리)","B-트리(B-tree)","리스트","힙"],"a":0,"ex":"AST 는 코드의 문법 구조를 나무 형태로 표현합니다."},{"t":"choice","k":"단계","q":"토큰들을 문법 규칙에 맞춰 구조(트리)로 만드는 단계는?","o":["정렬","구문 분석(parsing)","암호화(encrypt)","해싱"],"a":1,"ex":"파서(parser)가 문법 구조를 분석합니다."},{"t":"choice","k":"용어","q":"프로그래밍 언어의 문법 규칙을 정의한 것을 뭐라 하나요?","o":["주석","표준(std)","문법(grammar)라고 흔히 이해할 수 있다","라이브러리"],"a":2,"ex":"문법(grammar)이 올바른 코드 구조를 규정합니다."},{"t":"choice","k":"단계","q":"소스코드를 의미 있는 최소 단위(토큰)로 쪼개는 단계는?","o":["실행(exec)","압축","배포","어휘 분석(lexing)이라고 차근차근 알아 두어야 한다"],"a":3,"ex":"렉서(lexer)가 코드를 토큰 열로 나눕니다."}],"th":{"sum":"번역은 한 번에 되지 않는다. **글자 → 구조 → 뜻 → 기계어** 순서로 몇 단계를 거친다.","body":[{"h":"먼저 낱말로 자른다","t":"`x = 1 + 2` 를 `x`, `=`, `1`, `+`, `2` 로 쪼갠다. 사람이 문장을 낱말로 읽는 것과 같다. 여기서 걸리는 오류는 대개 오타나 닫지 않은 따옴표다."},{"h":"다음은 구조를 만든다","t":"낱말을 문법에 맞춰 나무 모양으로 엮는다. '무엇에 무엇을 대입한다', '무엇과 무엇을 더한다' 같은 뼈대다. 괄호를 안 닫았거나 순서가 어긋나면 여기서 걸린다."},{"h":"그다음 뜻을 본다","t":"구조가 맞아도 뜻이 안 맞을 수 있다. 없는 변수를 쓰거나, 숫자에 문자열을 더하는 식이다. 문법은 멀쩡한데 오류가 나는 경우가 대부분 이 단계다."},{"h":"마지막에 기계어로","t":"뜻까지 확인되면 CPU 가 아는 명령으로 옮기고, 쓸데없는 부분을 줄인다(최적화). 그래서 컴파일러가 만든 코드는 우리가 쓴 것과 줄 순서가 다를 수 있다 — 디버거에서 줄이 튀는 이유다."}],"code":{"c":"x = 1 + 2\n  ① 낱말: x  =  1  +  2\n  ② 구조: (= x (+ 1 2))\n  ③ 뜻  : x 는 숫자다 — 괜찮다\n  ④ 기계어","cap":"단계마다 걸리는 오류가 다르다"},"key":["낱말 → 구조 → 뜻 → 기계어","오류 종류로 단계를 알 수 있다","최적화가 줄 순서를 바꾼다"]}}],"ord":0},{"t":"어휘 분석·구문 분석과 AST","l":[{"t":"어휘 분석과 토큰","q":[{"t":"choice","k":"cmp-lex-token6","q":"다음 코드 한 줄을 어휘 분석했을 때 만들어지는 토큰 개수는? (세미콜론 포함)","ex":"sum, =, a, +, 10, ; 로 총 6개의 토큰이 나온다. 토큰 사이의 공백은 토큰 경계를 알려줄 뿐 그 자체로는 토큰이 되지 않고 버려진다.","code":"sum = a + 10;","o":["7개","4개","6개","5개"],"a":2},{"t":"choice","k":"cmp-lex-token1","q":"어휘 분석기(lexer)의 입력과 출력을 올바르게 짝지은 것은?","ex":"어휘 분석은 파이프라인의 가장 앞단으로 소스 코드의 문자들을 읽어 토큰 열을 만든다. 토큰 열을 받아 트리를 만드는 것은 다음 단계인 구문 분석의 역할이다.","o":["입력: 기계어 / 출력: 사람이 읽을 수 있는 소스 코드라고 흔히 이해할 수 있다","입력: 토큰 열 / 출력: AST 라는 트리라고 늘 새겨 두어야 한다","입력: AST 라는 트리 / 출력: 중간 표현(IR) 이라는 그라고 꽤 곰곰이 정리할 수 있다","입력: 문자 / 출력: 토큰이라고 새겨 두어야 한다"],"a":3},{"t":"choice","k":"cmp-lex-token3","q":"다음 중 어휘 분석 단계에서 발견되는 오류는?","ex":"닫히지 않은 문자열이나 언어에 존재하지 않는 잘못된 문자는 토큰을 만들 수 없으므로 어휘 오류다. 선언되지 않은 변수, 타입 불일치, 인자 개수 불일치는 모두 훨씬 뒤인 의미 분석 단계에서 잡힌다.","o":["함수를 호출하면서 넘겨야 할 인자 개수를 잘못 세어서 그만 넘겨 버렸다고 분명히 새겨 두어야 한다","문자열 리터럴의 따옴표가 닫히지 않았다고 짚어 두어야 한다","선언되지 않은 변수 total 을 그대로 가져다 그냥 써 버렸다고 차근차근 볼 수 있다","정수에 문자열을 더해서 타입이 서로 맞지 않게 되었다고 늘 알아 두어야 한다"],"a":1},{"t":"input","k":"cmp-lex-token5","q":"어휘 분석기가 보통 토큰으로 만들지 않고 버리는 두 가지 요소 중, 코드에 설명을 남기기 위해 쓰는 것은 무엇인가? (한 단어, 한국어로)","ex":"공백과 주석은 프로그램의 의미에 영향을 주지 않으므로 대부분의 언어에서 어휘 분석기가 건너뛴다. 그래서 파서는 주석의 존재를 아예 알지 못한다. 다만 문서 생성 도구를 위해 주석을 별도로 보관하는 구현도 있다.","a":["주석"]},{"t":"choice","k":"cmp-lex-token4","q":"토큰의 모양을 기술하는 데 정규식과 유한 오토마타로 충분한 이유는?","ex":"식별자, 숫자, 연산자 같은 개별 토큰의 패턴에는 임의 깊이의 중첩이 없어 정규 언어로 충분하다. 반대로 중첩 괄호처럼 깊이를 세야 하는 구조는 유한 오토마타로 표현할 수 없어서 문맥자유문법이 필요하고, 그래서 구문 분석 단계가 따로 존재한다.","o":["유한 오토마타가 임의 깊이의 괄호 짝까지 모두 다 셀 수 있기 때문이라고 이 단원에서는 꽤 무리 없이 설명할 수 있다","정규식이 문맥자유문법보다 표현력이 더 강하기 때문이라고 흔히 짚어 두어야 한다","모든 프로그래밍 언어의 전체 문법이 그대로 정규 언어이기 때문이라고 충분히 정리할 수 있다","토큰 패턴에는 재귀적 중첩이 없기 때문이다"],"a":3},{"t":"choice","k":"cmp-lex-token2","q":"토큰을 보통 (종류, 렉심) 쌍으로 표현하는 이유로 가장 적절한 것은?","ex":"파서는 \"식별자가 왔다\", \"정수 리터럴이 왔다\" 같은 종류 정보만으로 문법 규칙을 적용할 수 있다. 반면 심볼 테이블 조회나 상수 값 계산에는 count, 42 같은 실제 렉심 문자열이 필요하므로 둘을 함께 들고 다닌다.","o":["파서는 문법 판단에 종류가 필요하고, 이후 단계는 실제 문자열 값이 필요하기 때문이라고 꽤 그대로 이해할 수 있다","타입 검사를 어휘 분석 단계에서 끝내기 위해서","렉심만으로는 파일에 저장할 수 없기 때문","종류와 렉심이 같은 값이라 중복해서 저장해 두는 편이 안전하기 때문이다"],"a":0}],"th":{"sum":"컴파일러의 앞단(front-end)은 소스 문자열을 토큰으로 쪼개고, 문법에 따라 트리로 조립한다. 그 결과물인 AST가 뒤따르는 모든 단계의 기반이 된다.","body":[{"h":"어휘 분석: 문자에서 토큰으로","t":"어휘 분석기(lexer/scanner)는 소스 코드의 문자 스트림을 읽어 의미 있는 최소 단위인 토큰으로 자른다. 토큰은 보통 (종류, 렉심) 쌍으로 표현되며, 예를 들어 count라는 문자열은 (IDENT, \"count\")가 된다. 공백과 주석은 대개 여기서 버려지고 파서까지 전달되지 않는다. 토큰의 모양은 정규 언어로 기술할 수 있어서 정규식과 유한 오토마타(DFA)로 구현된다."},{"h":"구문 분석: 토큰에서 트리로","t":"구문 분석기(parser)는 토큰 열이 언어의 문법에 맞는지 검사하며 트리를 만든다. 프로그래밍 언어의 문법은 정규 언어보다 강한 문맥자유문법(CFG)으로 기술하는데, 중첩된 괄호나 블록처럼 재귀적인 구조를 정규식으로는 표현할 수 없기 때문이다. 하향식 방식에는 재귀 하강 파서와 LL 파서가 있고, 상향식 방식에는 LR·LALR 파서가 있다. 연산자 우선순위와 결합성은 문법을 계층적으로 쓰거나 우선순위 등반(precedence climbing)·Pratt 파서로 처리한다."},{"h":"파스 트리와 AST의 차이","t":"파스 트리(구체 구문 트리)는 문법이 사용한 모든 기호를 그대로 담기 때문에 괄호, 세미콜론, 중간 비단말까지 전부 노드로 남는다. AST(추상 구문 트리)는 이런 문법 잡음을 걷어내고 프로그램의 구조만 남긴 형태다. 예를 들어 (1 + 2) * 3의 AST에는 괄호 노드가 없고, 대신 곱셈 노드의 왼쪽 자식이 덧셈 노드라는 구조 자체가 우선순위를 표현한다. 이후 단계는 거의 항상 파스 트리가 아니라 AST 위에서 동작한다."}],"code":{"c":"소스:  x = (1 + 2) * 3;\n\n토큰:  (IDENT,\"x\") (EQ,\"=\") (LPAREN,\"(\") (INT,\"1\")\n       (PLUS,\"+\") (INT,\"2\") (RPAREN,\")\") (STAR,\"*\")\n       (INT,\"3\") (SEMI,\";\")\n\nAST:   Assign\n        ├── Var(x)\n        └── Mul\n            ├── Add\n            │   ├── Int(1)\n            │   └── Int(2)\n            └── Int(3)","cap":"같은 소스의 토큰 목록과 AST — 괄호와 세미콜론은 AST에 남지 않는다."},"key":["토큰은 (종류, 렉심) 쌍이고 공백·주석은 보통 어휘 분석에서 버려진다","토큰은 정규 언어, 프로그램 구조는 문맥자유문법으로 기술한다","AST는 괄호·세미콜론 같은 문법 잡음을 버리고 구조만 남긴다"]}},{"t":"구문 분석과 문법","q":[{"t":"choice","k":"cmp-parse-gram2","q":"재귀 하강 파서(recursive descent)에 대한 설명으로 옳은 것은?","ex":"재귀 하강은 대표적인 하향식(LL) 기법으로, 각 비단말에 대응하는 함수를 손으로 작성해 시작 기호에서부터 아래로 내려간다. 스택에 쌓아 축약하며 올라가는 것은 LR/LALR 계열의 상향식 파싱이다.","o":["AST 대신 기계어를 직접 출력하는 대목","문법을 쓰지 않고 토큰이 나타나는 빈도만으로 구조를 추측해 내는 상향식이라고 이 단원에서는 비교적 자주 곰곰이 볼 수 있다","문법의 비단말마다 함수를 두고 시작 기호부터 내려가며 파싱하는 하향식이라고 대체로 그대로 새겨 두어야 한다","토큰을 스택에 하나씩 쌓아 두었다가 규칙으로 축약해 올라가는 상향식 방식이다 문법의 비단말마다 함수를 두는 방식과는 반대 방향으로 움직인다."],"a":2},{"t":"choice","k":"cmp-parse-gram3","q":"dangling else 문제는 무엇의 대표적인 예인가?","ex":"if a then if b then s1 else s2 에서 else가 어느 if에 붙는지 문법만으로는 결정되지 않아 파스 트리가 두 개 나온다. 이것이 모호한 문법의 고전적 예이며, 보통 \"else는 가장 가까운 if에 붙는다\"는 규칙을 문법이나 파서에 추가해 해소한다.","o":["레지스터가 부족해 값을 메모리로 밀어내야만 하는 상황","하나의 토큰 열이 둘 이상의 파스 트리를 갖는 모호한 문법이라고 어렵지 않게 이해할 수 있다","런타임에 타입이 바뀌는 동적 타입 언어의 특성","어휘 분석에서 발생하는 토큰 충돌"],"a":1},{"t":"choice","k":"cmp-parse-gram6","q":"다음 문법으로 1 + 2 * 3 을 파싱할 때 만들어지는 구조는?","ex":"term이 expr보다 아래 계층에 있어서 곱셈이 항상 더 단단히 묶이고, 결과적으로 1 + (2 * 3) 구조가 된다. 이렇게 문법을 계층으로 나누는 것만으로 우선순위를 표현할 수 있고, 이 문법은 모호하지 않다.","code":"expr   -&gt; expr '+' term | term\nterm   -&gt; term '*' factor | factor\nfactor -&gt; NUM | '(' expr ')'","o":["1 + (2 * 3) 구조","문법이 모호해서 두 구조가 모두 유효하다고 본다","우선순위 정보가 없어 파싱이 실패한다","덧셈이 먼저 묶여서 (1 + 2) * 3 이라는 형태가 된다"],"a":0},{"t":"input","k":"cmp-parse-gram5","q":"LR·LALR처럼 토큰을 스택에 쌓았다가 규칙으로 축약하며 트리를 아래에서 위로 만드는 파싱 방식을 무엇이라 하는가? (한국어 세 글자, 예: OO식)","ex":"LR·LALR 계열은 잎에서 뿌리 방향으로 트리를 만들기 때문에 상향식(bottom-up) 파싱이라 부른다. 반대로 재귀 하강과 LL은 시작 기호에서 내려가는 하향식(top-down) 방식이다. 상향식은 다룰 수 있는 문법의 범위가 더 넓다.","a":["상향식"]},{"t":"choice","k":"cmp-parse-gram4","q":"표현식에서 연산자 우선순위와 결합성을 처리하는 방법으로 옳지 않은 것은?","ex":"어휘 분석기는 소스에 나타난 순서대로 토큰을 만들 뿐이고 우선순위 개념 자체가 없다. 우선순위와 결합성은 문법 계층화, 우선순위 등반, Pratt 파서처럼 구문 분석 단계의 기법으로 처리한다.","o":["문법을 expr / term / factor처럼 계층으로 나눠 우선순위를 인코딩한다","우선순위 등반(precedence climbing) 알고리즘을 사용한다","Pratt 파서로 토큰마다 결합 세기를 부여해 처리한다","어휘 분석기가 * 토큰을 먼저 만들어 정한다"],"a":3},{"t":"choice","k":"cmp-parse-gram1","q":"프로그래밍 언어의 구조를 기술하는 데 정규식이 아니라 문맥자유문법(CFG)을 쓰는 핵심 이유는?","ex":"중첩 괄호나 중첩 블록처럼 짝을 맞추며 깊이가 무한히 커지는 구조는 정규 언어의 표현력을 넘어선다. CFG는 규칙이 자기 자신을 참조하는 재귀를 허용해 이런 구조를 자연스럽게 기술한다. 타입 검사는 문법이 아니라 의미 분석의 일이다.","o":["CFG는 실행 속도가 더 빠르기 때문","CFG 는 파싱과 함께 타입 검사까지 자동으로 수행해 주기 때문이다 정규식으로는 검사 규칙을 적을 자리가 없어 문법을 따로 두는 방식.","정규식은 대소문자를 구분하지 못해 키워드를 제대로 가려낼 수가 없기 때문이라고 충분히 무리 없이 짚어 두어야 한다","임의 깊이로 중첩되는 재귀 구조를 정규 언어로는 표현할 수 없기 때문이라고 흔히 짚어 두어야 한다"],"a":3}],"th":{"sum":"컴파일러의 앞단(front-end)은 소스 문자열을 토큰으로 쪼개고, 문법에 따라 트리로 조립한다. 그 결과물인 AST가 뒤따르는 모든 단계의 기반이 된다.","body":[{"h":"어휘 분석: 문자에서 토큰으로","t":"어휘 분석기(lexer/scanner)는 소스 코드의 문자 스트림을 읽어 의미 있는 최소 단위인 토큰으로 자른다. 토큰은 보통 (종류, 렉심) 쌍으로 표현되며, 예를 들어 count라는 문자열은 (IDENT, \"count\")가 된다. 공백과 주석은 대개 여기서 버려지고 파서까지 전달되지 않는다. 토큰의 모양은 정규 언어로 기술할 수 있어서 정규식과 유한 오토마타(DFA)로 구현된다."},{"h":"구문 분석: 토큰에서 트리로","t":"구문 분석기(parser)는 토큰 열이 언어의 문법에 맞는지 검사하며 트리를 만든다. 프로그래밍 언어의 문법은 정규 언어보다 강한 문맥자유문법(CFG)으로 기술하는데, 중첩된 괄호나 블록처럼 재귀적인 구조를 정규식으로는 표현할 수 없기 때문이다. 하향식 방식에는 재귀 하강 파서와 LL 파서가 있고, 상향식 방식에는 LR·LALR 파서가 있다. 연산자 우선순위와 결합성은 문법을 계층적으로 쓰거나 우선순위 등반(precedence climbing)·Pratt 파서로 처리한다."},{"h":"파스 트리와 AST의 차이","t":"파스 트리(구체 구문 트리)는 문법이 사용한 모든 기호를 그대로 담기 때문에 괄호, 세미콜론, 중간 비단말까지 전부 노드로 남는다. AST(추상 구문 트리)는 이런 문법 잡음을 걷어내고 프로그램의 구조만 남긴 형태다. 예를 들어 (1 + 2) * 3의 AST에는 괄호 노드가 없고, 대신 곱셈 노드의 왼쪽 자식이 덧셈 노드라는 구조 자체가 우선순위를 표현한다. 이후 단계는 거의 항상 파스 트리가 아니라 AST 위에서 동작한다."}],"code":{"c":"소스:  x = (1 + 2) * 3;\n\n토큰:  (IDENT,\"x\") (EQ,\"=\") (LPAREN,\"(\") (INT,\"1\")\n       (PLUS,\"+\") (INT,\"2\") (RPAREN,\")\") (STAR,\"*\")\n       (INT,\"3\") (SEMI,\";\")\n\nAST:   Assign\n        ├── Var(x)\n        └── Mul\n            ├── Add\n            │   ├── Int(1)\n            │   └── Int(2)\n            └── Int(3)","cap":"같은 소스의 토큰 목록과 AST — 괄호와 세미콜론은 AST에 남지 않는다."},"key":["토큰은 (종류, 렉심) 쌍이고 공백·주석은 보통 어휘 분석에서 버려진다","토큰은 정규 언어, 프로그램 구조는 문맥자유문법으로 기술한다","AST는 괄호·세미콜론 같은 문법 잡음을 버리고 구조만 남긴다"]}},{"t":"AST의 구조와 순회","q":[{"t":"choice","k":"cmp-ast-tree5","q":"다음 AST 스케치가 나타내는 원본 표현식으로 가장 알맞은 것은?","ex":"덧셈이 루트이고 곱셈이 그 오른쪽 자식이므로 곱셈이 더 단단히 묶여 있다. 이는 우선순위 규칙이 그대로 적용된 1 + 2 * 3 에 해당한다. (1 + 2) * 3 이라면 곱셈이 루트가 되어 트리 모양이 뒤집힌다.","code":"Add\n├── Int(1)\n└── Mul\n    ├── Int(2)\n    └── Int(3)","o":["(1 + 2) * 3 이라는 대목이라고 대체로 볼 수 있다","(1+2)*3","(1 * 2) + (3 * 1) 이라는 그라고 흔히 새겨 두어야 한다","1 + 2 * 3이라고 알아 두어야 한다"],"a":3},{"t":"input","k":"cmp-ast-tree4","q":"표현식 1 - 2 - 3 을 왼쪽 결합으로 파싱했을 때, AST 루트인 뺄셈 노드의 오른쪽 자식이 되는 정수 리터럴은 무엇인가? (숫자로)","ex":"왼쪽 결합이므로 (1 - 2) - 3 으로 묶이고, 바깥쪽 뺄셈이 루트가 된다. 따라서 루트의 왼쪽 자식은 Sub(1,2)이고 오른쪽 자식은 Int(3)이다. 만약 오른쪽 결합이었다면 루트의 왼쪽 자식이 Int(1)이 되어 결과값도 달라진다.","a":["3"]},{"t":"choice","k":"cmp-ast-tree3","q":"산술 표현식 AST를 후위(post-order)로 순회하며 노드를 출력하면 무엇을 얻는가?","ex":"후위 순회는 자식을 먼저 방문한 뒤 연산자를 방문하므로 2 3 + 4 * 같은 후위 표기가 나온다. 이 순서는 피연산자를 스택에 밀어 넣고 연산자에서 꺼내 계산하는 스택 VM의 명령 순서와 정확히 일치해 코드 생성에 유용하다.","o":["원본 소스와 글자까지 똑같은 문자열","스택 기반 VM에 바로 쓰기 좋은 후위 표기식이라고 이 단원에서는 늘 정리할 수 있다","중위 표기식","토큰 목록"],"a":1},{"t":"choice","k":"cmp-ast-tree6","q":"AST를 만든 직후 컴파일러가 곧바로 이어서 수행하는 단계는?","ex":"구문 분석이 끝나 AST가 만들어지면 의미 분석이 그 트리를 순회하며 심볼 테이블을 만들고 타입을 검사한다. 레지스터 할당과 링킹은 IR과 최적화를 거친 훨씬 뒤쪽 단계의 일이다.","o":["의미 분석(심볼 테이블 구축과 타입 검사)라고 분명히 새겨 두어야 한다","레지스터 할당","어휘 분석을 처음부터 다시 하는 단계","링킹"],"a":0},{"t":"choice","k":"cmp-ast-tree2","q":"표현식 (2 + 3) * 4 의 AST에 대한 설명으로 옳은 것은?","ex":"괄호는 파싱 중 묶는 순서를 지시한 뒤 역할을 다하므로 AST에는 남지 않는다. 대신 곱셈이 루트이고 왼쪽 자식이 Add(2,3), 오른쪽 자식이 Int(4)라는 트리 모양 자체가 원래 괄호가 표현하던 의미를 담는다.","o":["괄호 노드가 루트가 되고 그 아래에 덧셈과 곱셈이 나란히 놓이게 된다고 흔히 정리할 수 있다","괄호 노드는 없고 덧셈 노드의 왼쪽 자식이 곱셈 노드가 되어 버리는 그런 경우라고 실무에서는 늘 곰곰이 새겨 두어야 한다","괄호 노드는 없고 곱셈 노드의 왼쪽 자식이 덧셈 노드","AST는 표현식을 다루지 않으므로 트리 자체가 만들어지지 않는다고 이 단원에서는 꽤 곰곰이 볼 수 있다"],"a":2},{"t":"choice","k":"cmp-ast-tree1","q":"파스 트리(구체 구문 트리)와 AST(추상 구문 트리)의 차이로 옳은 것은?","ex":"파스 트리는 문법이 사용한 모든 단말·비단말을 그대로 담아 크고 장황하다. AST는 구두점과 중간 비단말을 걷어내 프로그램의 본질적 구조만 남기므로 보통 훨씬 작고, 이후 단계는 AST 위에서 동작한다.","o":["파스 트리는 타입 정보까지 함께 담고 AST 는 그 정보를 버리므로 결국 둘의 차이는 타입에 있다고 실제로 그대로 알아 두어야 한다","파스 트리는 문법의 모든 기호를 담지만 AST는 괄호·세미콜론 같은 잡음을 버리고 구조만 남긴다고 그대로 설명할 수 있다","AST가 파스 트리보다 노드 수가 많다","AST 는 어휘 분석 단계에서 만들어지고 파스 트리는 그 뒤 의미 분석 단계에서 만들어진다 그래서 파스 트리를 만들려면 의미 정보가 먼저 필요하다."],"a":1}],"th":{"sum":"컴파일러의 앞단(front-end)은 소스 문자열을 토큰으로 쪼개고, 문법에 따라 트리로 조립한다. 그 결과물인 AST가 뒤따르는 모든 단계의 기반이 된다.","body":[{"h":"어휘 분석: 문자에서 토큰으로","t":"어휘 분석기(lexer/scanner)는 소스 코드의 문자 스트림을 읽어 의미 있는 최소 단위인 토큰으로 자른다. 토큰은 보통 (종류, 렉심) 쌍으로 표현되며, 예를 들어 count라는 문자열은 (IDENT, \"count\")가 된다. 공백과 주석은 대개 여기서 버려지고 파서까지 전달되지 않는다. 토큰의 모양은 정규 언어로 기술할 수 있어서 정규식과 유한 오토마타(DFA)로 구현된다."},{"h":"구문 분석: 토큰에서 트리로","t":"구문 분석기(parser)는 토큰 열이 언어의 문법에 맞는지 검사하며 트리를 만든다. 프로그래밍 언어의 문법은 정규 언어보다 강한 문맥자유문법(CFG)으로 기술하는데, 중첩된 괄호나 블록처럼 재귀적인 구조를 정규식으로는 표현할 수 없기 때문이다. 하향식 방식에는 재귀 하강 파서와 LL 파서가 있고, 상향식 방식에는 LR·LALR 파서가 있다. 연산자 우선순위와 결합성은 문법을 계층적으로 쓰거나 우선순위 등반(precedence climbing)·Pratt 파서로 처리한다."},{"h":"파스 트리와 AST의 차이","t":"파스 트리(구체 구문 트리)는 문법이 사용한 모든 기호를 그대로 담기 때문에 괄호, 세미콜론, 중간 비단말까지 전부 노드로 남는다. AST(추상 구문 트리)는 이런 문법 잡음을 걷어내고 프로그램의 구조만 남긴 형태다. 예를 들어 (1 + 2) * 3의 AST에는 괄호 노드가 없고, 대신 곱셈 노드의 왼쪽 자식이 덧셈 노드라는 구조 자체가 우선순위를 표현한다. 이후 단계는 거의 항상 파스 트리가 아니라 AST 위에서 동작한다."}],"code":{"c":"소스:  x = (1 + 2) * 3;\n\n토큰:  (IDENT,\"x\") (EQ,\"=\") (LPAREN,\"(\") (INT,\"1\")\n       (PLUS,\"+\") (INT,\"2\") (RPAREN,\")\") (STAR,\"*\")\n       (INT,\"3\") (SEMI,\";\")\n\nAST:   Assign\n        ├── Var(x)\n        └── Mul\n            ├── Add\n            │   ├── Int(1)\n            │   └── Int(2)\n            └── Int(3)","cap":"같은 소스의 토큰 목록과 AST — 괄호와 세미콜론은 AST에 남지 않는다."},"key":["토큰은 (종류, 렉심) 쌍이고 공백·주석은 보통 어휘 분석에서 버려진다","토큰은 정규 언어, 프로그램 구조는 문맥자유문법으로 기술한다","AST는 괄호·세미콜론 같은 문법 잡음을 버리고 구조만 남긴다"]}}],"ord":1},{"t":"의미 분석과 타입 검사","l":[{"t":"심볼 테이블과 스코프","q":[{"t":"choice","k":"cmp-sem-sym3","q":"중첩 블록에서 이름을 조회할 때의 표준적인 순서는?","ex":"스코프 스택의 꼭대기(가장 안쪽)부터 검색해 처음 발견한 선언을 사용하며, 이 때문에 안쪽 선언이 바깥 선언을 가린다(shadowing). 안쪽에 같은 이름을 다시 선언하는 것 자체는 오류가 아니라 정상적인 가리기다.","o":["모든 스코프를 빠짐없이 전부 뒤져서 선언이 둘 이상이면 오류로 처리한다고 대체로 무리 없이 이해할 수 있다","전역 스코프부터 안쪽으로 내려가며 찾음","선언 위치와 무관하게 알파벳 순으로 우선순위를 정한다고 늘 차근차근 설명할 수 있다","안쪽 스코프부터 바깥으로 올라가며 찾는다"],"a":3},{"t":"choice","k":"cmp-sem-sym5","q":"다음 코드에서 컴파일러가 보고할 오류와 그 단계로 옳은 것은?","ex":"total = total + 1 은 토큰으로 잘 나뉘고 문법에도 완벽히 맞으므로 어휘·구문 분석은 통과한다. 문제는 total이라는 이름이 심볼 테이블에 없다는 것이고, 이는 이름 해석을 담당하는 의미 분석 단계에서 잡힌다.","code":"int main() {\n    total = total + 1;\n    return 0;\n}","o":["의미 분석의 미선언 오류라고 충분히 차근차근 짚어 두어야 한다","구문 분석의 문법 오류","어휘 분석 단계의 잘못된 문자 오류라고 실무에서는 흔히 짚어 두어야 한다","코드를 생성하는 단계에서 나는 레지스터 부족 오류라고 흔히 무리 없이 알아 두어야 한다"],"a":0},{"t":"input","k":"cmp-sem-sym4","q":"다음 코드에서 print(x)가 출력하는 값은 무엇인가? (정적 스코프 기준, 숫자로)","ex":"안쪽 블록의 x = 20 은 그 블록 안에서만 유효하고, 블록이 닫히면 해당 스코프가 스택에서 제거된다. print(x)는 다시 전역 스코프의 x를 보게 되므로 10이 출력된다.","code":"let x = 10;\n{\n    let x = 20;\n}\nprint(x);","a":["10"]},{"t":"choice","k":"cmp-sem-sym1","q":"심볼 테이블의 역할로 가장 정확한 것은?","ex":"심볼 테이블은 변수·함수·타입 이름을 그 선언 정보와 이어 주는 자료구조로, 의미 분석의 핵심 도구다. 이름을 조회했을 때 아무 항목도 없으면 선언되지 않은 이름 오류가 된다.","o":["기계어 명령이 실제로 실행되는 순서를 최적으로 다시 재배치해 준다 이름과 선언 정보를 잇는 일은 파서가 이미 끝내 두었다고 이해할 수 있다","소스 코드의 문자를 종류별 토큰으로 잘라 다음 단계에 넘겨주는 일을 맡아서 한다고 어느 정도는 곰곰이 설명할 수 있다","프로그램에 등장하는 이름을 선언 정보(타입, 종류, 스코프)에 연결한다","실행 중 발생한 예외를 처리한다"],"a":2},{"t":"choice","k":"cmp-sem-sym2","q":"정적(렉시컬) 스코프와 동적 스코프의 차이로 옳은 것은?","ex":"정적 스코프에서는 함수가 어디에 쓰여 있는지가 이름의 의미를 결정하므로 코드만 보고 판단할 수 있다. 동적 스코프에서는 누가 호출했는지에 따라 같은 이름이 다른 변수를 가리켜 추론이 어렵고, 그래서 현대 언어 대부분은 정적 스코프를 택한다.","o":["정적 스코프는 전역 변수만, 동적 스코프는 지역 변수만 다룬다","정적 스코프는 소스 코드의 중첩 구조로, 동적 스코프는 실행 중 호출 스택으로 이름의 의미가 결정된다고 짚어 두어야 한다","정적 스코프는 실행하는 중에만 결정되고 동적 스코프는 컴파일하는 시점에 미리 결정된다 그래서 정적 스코프 언어에서는 소스만 봐서는 이름의 의미를 알 수 없다.","둘은 이름만 다를 뿐 결과가 같다"],"a":1},{"t":"choice","k":"cmp-sem-sym6","q":"심볼 테이블을 스택 구조로 관리하는 이유로 가장 적절한 것은?","ex":"블록은 나중에 열린 것이 먼저 닫히는 중첩 구조라 스택의 push/pop과 자연스럽게 맞아떨어진다. 각 스코프 안의 이름 조회는 보통 해시 테이블로 하고, 그 해시 테이블들을 스택으로 쌓아 올리는 식으로 구현한다.","o":["변수 이름을 알파벳 순서대로 정렬해서 보관해 주기 때문이라고 본다 정렬해 두면 이름을 찾는 속도가 빨라지므로 스택으로 쌓는다.","해시 테이블보다 이름 조회가 훨씬 더 빠르고 메모리도 훨씬 더 적게 쓰기 때문이라고 어느 정도는 짚어 두어야 한다","블록이 열리고 닫히는 중첩 구조가 push/pop과 정확히 대응하기 때문","런타임에 쓰이는 메모리를 스택 구조 그대로 직접 할당해 주는 일을 하기 때문이라고 늘 설명할 수 있다"],"a":2}],"th":{"sum":"문법에 맞는 코드라고 해서 의미가 통하는 것은 아니다. 의미 분석은 심볼 테이블로 이름을 해석하고 타입을 검사해 실행 전에 잡을 수 있는 오류를 걸러낸다.","body":[{"h":"심볼 테이블과 이름 해석","t":"심볼 테이블은 프로그램에 등장하는 이름을 그 선언 정보(타입, 종류, 위치)에 연결하는 자료구조다. 블록이 열릴 때마다 새 스코프를 밀어 넣고 닫힐 때 꺼내는 스택 구조로 흔히 구현한다. 이름을 찾을 때는 가장 안쪽 스코프부터 바깥으로 올라가며 검색하고, 끝까지 못 찾으면 \"선언되지 않은 변수\" 오류가 된다. 대부분의 현대 언어는 이름의 의미가 소스 코드의 중첩 구조로 결정되는 정적(렉시컬) 스코프를 쓰며, 호출 스택을 따라 결정되는 동적 스코프와 구별된다."},{"h":"타입 검사와 타입 추론","t":"타입 검사기는 AST를 순회하며 각 표현식의 타입을 계산하고 연산이 그 타입에 허용되는지 확인한다. 정수와 문자열을 더하는 것 같은 타입 불일치, 인자 개수나 타입이 맞지 않는 함수 호출이 여기서 걸린다. 타입 추론은 개발자가 어노테이션을 쓰지 않아도 컴파일러가 타입을 스스로 알아내는 기법으로, Hindley-Milner 알고리즘이 대표적이다. 추론이 있다고 해서 동적 타입이 되는 것이 아니라, 여전히 컴파일 타임에 완전한 정적 타입이 부여된다."},{"h":"정적/동적과 강/약은 다른 축","t":"정적 타입은 컴파일 타임에 타입을 검사하고, 동적 타입은 값에 타입표를 붙여 런타임에 검사한다. 이는 강/약 타입과 완전히 다른 축이다. 강한 타입은 몰래 하는 암묵적 변환을 허용하지 않는다는 뜻이라, 파이썬처럼 동적이면서 강한 타입인 언어도 있고 C처럼 정적이면서 상대적으로 약한 언어도 있다. 어느 단계에서 오류가 잡히는지 구분하는 것도 중요하다. 잘못된 문자는 어휘, 짝이 안 맞는 괄호는 구문, 선언되지 않은 변수와 타입 불일치는 의미 분석, 0으로 나누기나 널 참조는 대개 런타임이다."}],"code":{"c":"let x: int = 1;\n{\n    let x: string = \"hi\";   // 안쪽 스코프의 새 x\n    print(x + 1);           // 타입 오류: string + int\n}\nprint(y);                   // 이름 오류: y 미선언\n\n심볼 테이블(안쪽 블록 시점)\n  scope#1 (블록)  : x -> string\n  scope#0 (전역)  : x -> int\n\n조회 x  => 안쪽부터 검색 => string\n조회 y  => 어느 스코프에도 없음 => 오류","cap":"스코프 스택을 안쪽부터 검색하는 이름 해석과, 의미 분석에서 잡히는 두 종류의 오류."},"key":["심볼 테이블은 이름을 선언 정보에 연결하고 스코프는 스택처럼 중첩된다","선언되지 않은 변수·타입 불일치·인자 개수 오류는 의미 분석에서 잡힌다","정적/동적과 강/약 타입은 서로 독립된 축이다"]}},{"t":"타입 검사와 타입 추론","q":[{"t":"choice","k":"cmp-sem-type3","q":"다음 코드에서 컴파일러가 보고하는 오류의 종류는?","ex":"add(1, 2, 3) 은 함수 호출 문법으로는 완벽히 유효해서 파서는 아무 문제도 못 느낀다. 심볼 테이블에서 add의 선언을 찾아 매개변수가 2개임을 확인하는 순간, 즉 의미 분석에서 인자 개수 불일치가 드러난다.","code":"int add(int a, int b) { return a + b; }\n\nint main() {\n    return add(1, 2, 3);\n}","o":["의미 분석의 인자 수 오류","실행 중 런타임에만 발견할 수가 있게 되는 그런 종류의 오류라고 흔히 정리할 수 있다","어휘 분석 단계에서 나는 잘못된 토큰 오류라고 흔히 알아 두어야 한다","구문을 분석하는 단계에서 나는 괄호 짝이 서로 맞지 않는다는 그런 종류의 오류라고 꽤 정리할 수 있다"],"a":0},{"t":"choice","k":"cmp-sem-type2","q":"타입 추론(Hindley-Milner 등)에 대한 설명으로 옳은 것은?","ex":"타입 추론은 타입을 없애는 것이 아니라 개발자가 적어야 할 어노테이션을 컴파일러가 대신 유도하는 기법이다. 추론이 끝나면 모든 표현식에 컴파일 타임 타입이 붙으므로 정적 타입 검사의 안전성은 그대로 유지된다.","o":["모든 변수의 타입을 자동으로 문자열로 통일한다","어노테이션이 없어도 컴파일 타임에 타입을 알아내므로 여전히 정적 타입이라고 차근차근 이해할 수 있다","타입 검사를 생략해 오류 검출을 포기하는 기법이다","타입 결정을 런타임까지 미루므로 그 언어를 동적 타입으로 만들어 버린다"],"a":1},{"t":"input","k":"cmp-sem-type5","q":"어노테이션 없이도 컴파일러가 표현식의 타입을 스스로 알아내는 기법을 무엇이라 하는가? (한국어로, 예: 타입 OO)","ex":"타입 추론은 변수의 사용 방식으로부터 제약을 모아 풀어내 타입을 결정한다. Hindley-Milner는 이 접근의 대표 알고리즘으로 ML, Haskell 계열 언어의 바탕이 되었고, 현대 언어의 지역 변수 타입 생략 기능도 같은 아이디어의 축소판이다.","a":["타입 추론"]},{"t":"choice","k":"cmp-sem-type1","q":"타입 검사기가 하는 일로 가장 정확한 것은?","ex":"타입 검사기는 AST를 오르내리며 리프의 타입에서 시작해 부모 노드의 타입을 계산하고, 각 연산자가 그 피연산자 타입을 받아들일 수 있는지 검사한다. 이는 의미 분석의 일부이며 레지스터 배정은 훨씬 뒤인 코드 생성의 일이다.","o":["변수마다 레지스터를 배정한다","함수가 실제로 실행되는 데 걸리는 시간을 측정해 느린 부분을 찾아낸다 느린 곳을 찾아 두면 그 자리의 타입을 더 좁게 잡을 수 있다고 흔히 이해할 수 있다","토큰의 철자가 사전과 견주어 올바른지 하나씩 확인하고 틀린 것을 오류로 보고한다고 실무에서는 어느 정도는 차근차근 이해할 수 있다","AST를 순회하며 각 표현식의 타입을 계산하고 연산이 허용되는지 확인한다고 충분히 어렵지 않게 짚어 두어야 한다"],"a":3},{"t":"choice","k":"cmp-sem-type4","q":"정수와 문자열을 더하는 코드에 대해 정적 타입 언어와 동적 타입 언어의 차이는?","ex":"정적 타입 검사는 실행 전에 전체 코드를 훑으므로 그 줄이 한 번도 실행되지 않아도 오류를 보고한다. 동적 타입 언어는 값에 붙은 타입표를 런타임에 확인하므로, 해당 분기가 실행되어야 비로소 오류가 드러난다.","o":["두 언어 모두 오류로 보지 않고 문자열 이어붙이기로 해석해서 그냥 조용히 넘어가 버리고 만다고 곰곰이 알아 두어야 한다","정적 타입 언어는 컴파일 타임에, 동적 타입 언어는 그 줄이 실제로 실행될 때 잡는다","정적 타입 언어는 이런 오류를 잡지 못하고 동적 타입 언어에서만 잡아낸다 동적 타입 언어만 값의 실제 타입을 볼 수 있기 때문이다.","두 언어 모두 어휘 분석 단계에서 잡는다"],"a":1},{"t":"choice","k":"cmp-sem-type6","q":"타입 검사가 구문 분석과 별개의 단계로 존재하는 이유는?","ex":"\"이 변수가 여기서 어떤 타입으로 선언되었는가\"는 멀리 떨어진 선언부에 의존하는 문맥 의존적 성질이라 CFG로는 기술할 수 없다. 그래서 파서가 만든 AST 위에서 심볼 테이블을 참조하는 별도의 의미 분석 단계가 필요하다.","o":["타입은 실행 중에만 존재하기 때문","파서가 토큰을 모두 소비하고 나면 더 이상 트리를 만들 수 없기 때문 그래서 타입 검사를 하려면 트리를 처음부터 다시 만들어야 한다고 흔히 새겨 두어야 한다","타입 정합성은 이름 해석과 선언 정보에 의존해 문맥자유문법만으로는 표현할 수 없기 때문이라고 한 번 더 할 수 있다","타입 검사가 문법 규칙보다 훨씬 구현이 간단해서 따로 떼어 두는 편이 편하기 때문이라고 한 걸음 물러나 전체를 훑어보면 어렵지 않게 할 수 있다"],"a":2}],"th":{"sum":"문법에 맞는 코드라고 해서 의미가 통하는 것은 아니다. 의미 분석은 심볼 테이블로 이름을 해석하고 타입을 검사해 실행 전에 잡을 수 있는 오류를 걸러낸다.","body":[{"h":"타입 검사와 타입 추론","t":"타입 검사기는 AST를 순회하며 각 표현식의 타입을 계산하고 연산이 그 타입에 허용되는지 확인한다. 정수와 문자열을 더하는 것 같은 타입 불일치, 인자 개수나 타입이 맞지 않는 함수 호출이 여기서 걸린다. 타입 추론은 개발자가 어노테이션을 쓰지 않아도 컴파일러가 타입을 스스로 알아내는 기법으로, Hindley-Milner 알고리즘이 대표적이다. 추론이 있다고 해서 동적 타입이 되는 것이 아니라, 여전히 컴파일 타임에 완전한 정적 타입이 부여된다."},{"h":"심볼 테이블과 이름 해석","t":"심볼 테이블은 프로그램에 등장하는 이름을 그 선언 정보(타입, 종류, 위치)에 연결하는 자료구조다. 블록이 열릴 때마다 새 스코프를 밀어 넣고 닫힐 때 꺼내는 스택 구조로 흔히 구현한다. 이름을 찾을 때는 가장 안쪽 스코프부터 바깥으로 올라가며 검색하고, 끝까지 못 찾으면 \"선언되지 않은 변수\" 오류가 된다. 대부분의 현대 언어는 이름의 의미가 소스 코드의 중첩 구조로 결정되는 정적(렉시컬) 스코프를 쓰며, 호출 스택을 따라 결정되는 동적 스코프와 구별된다."},{"h":"정적/동적과 강/약은 다른 축","t":"정적 타입은 컴파일 타임에 타입을 검사하고, 동적 타입은 값에 타입표를 붙여 런타임에 검사한다. 이는 강/약 타입과 완전히 다른 축이다. 강한 타입은 몰래 하는 암묵적 변환을 허용하지 않는다는 뜻이라, 파이썬처럼 동적이면서 강한 타입인 언어도 있고 C처럼 정적이면서 상대적으로 약한 언어도 있다. 어느 단계에서 오류가 잡히는지 구분하는 것도 중요하다. 잘못된 문자는 어휘, 짝이 안 맞는 괄호는 구문, 선언되지 않은 변수와 타입 불일치는 의미 분석, 0으로 나누기나 널 참조는 대개 런타임이다."}],"code":{"c":"let x: int = 1;\n{\n    let x: string = \"hi\";   // 안쪽 스코프의 새 x\n    print(x + 1);           // 타입 오류: string + int\n}\nprint(y);                   // 이름 오류: y 미선언\n\n심볼 테이블(안쪽 블록 시점)\n  scope#1 (블록)  : x -> string\n  scope#0 (전역)  : x -> int\n\n조회 x  => 안쪽부터 검색 => string\n조회 y  => 어느 스코프에도 없음 => 오류","cap":"스코프 스택을 안쪽부터 검색하는 이름 해석과, 의미 분석에서 잡히는 두 종류의 오류."},"key":["심볼 테이블은 이름을 선언 정보에 연결하고 스코프는 스택처럼 중첩된다","선언되지 않은 변수·타입 불일치·인자 개수 오류는 의미 분석에서 잡힌다","정적/동적과 강/약 타입은 서로 독립된 축이다"]}},{"t":"정적 vs 동적 타입, 오류가 잡히는 단계","q":[{"t":"choice","k":"cmp-sem-stat4","q":"다음 오류 중 일반적으로 컴파일 타임이 아니라 런타임에 드러나는 것은?","ex":"나누는 값이 실행 중에 계산된다면 컴파일러는 그것이 0이 될지 미리 알 수 없어 런타임 오류가 된다. 나머지 셋은 각각 의미 분석과 구문 분석에서 실행 전에 확실히 잡힌다.","o":["선언되지 않은 변수를 그대로 사용한 경우 선언을 찾지 못하는 것은 실행해 봐야 알 수 있는 일이다.","괄호 짝이 서로 맞지 않아서 나는 그런 종류의 오류에 해당하는 형태","선언과 달리 함수를 부를 때 넘기는 인자 개수가 서로 맞지 않게 되는 그런 경우라고 본다","실행 중 계산된 값이 0이 되어 발생한 0으로 나누기"],"a":3},{"t":"choice","k":"cmp-sem-stat1","q":"다음 중 정적 타입과 동적 타입의 구분에 대한 서술로 옳은 것은?","ex":"구분의 핵심은 타입 검사가 실행 전에 일어나느냐 실행 중에 일어나느냐다. 타입 추론이 있는 정적 언어는 어노테이션을 거의 안 써도 되고, 동적 언어의 값에도 분명히 타입이 있으며, 강/약 타입은 완전히 별개의 축이다.","o":["정적 타입 언어는 모든 변수에 타입을 적어야 한다고 흔히 한 번 더 설명할 수 있다","정적 타입 언어는 강한 타입이고 동적 타입 언어는 약한 타입이라고 여러 자료를 놓고 보면 어느 정도는 짚어 두어야 한다","정적은 컴파일 타임, 동적은 런타임 검사라고 실제로 알아 두어야 한다","동적 타입 언어에는 타입 개념이 없다"],"a":2},{"t":"input","k":"cmp-sem-stat5","q":"\"선언되지 않은 변수\", \"타입 불일치\", \"인자 개수 불일치\"가 공통으로 잡히는 컴파일 단계의 이름은? (한국어로, 예: OO 분석)","ex":"세 오류 모두 코드가 문법적으로는 완전히 유효하지만 의미가 통하지 않는 경우다. 판단에 심볼 테이블과 타입 정보가 필요하므로 구문 분석이 끝난 뒤의 의미 분석 단계에서 처리된다.","a":["의미 분석"]},{"t":"choice","k":"cmp-sem-stat6","q":"동적 타입 언어에서 다음 코드를 실행할 때 일어나는 일은? (n은 실행 중 입력으로 결정)","ex":"동적 타입 검사는 그 연산이 실제로 수행되는 순간에만 일어나므로 실행되지 않은 분기의 타입 오류는 잠복한다. 이것이 정적 타입 검사가 커버리지와 무관하게 오류를 미리 잡아 준다는 장점의 뒷면이다.","code":"if n &gt; 100:\n    print(\"big\" + 1)\nelse:\n    print(\"small\")","o":["n 값과 무관하게 실행 전에 오류가 보고된다","그 분기가 실행되지 않으면 오류가 안 드러난다","인터프리터가 1 을 자동으로 문자열로 바꿔 주므로 정상 동작한다고 늘 차근차근 알아 두어야 한다","문자열과 정수를 더하는 코드는 어떤 언어에서도 문법 오류다"],"a":1},{"t":"choice","k":"cmp-sem-stat3","q":"\"타입 오류는 어휘 분석 단계에서 잡힌다\"는 서술이 틀린 이유는?","ex":"어휘 분석기는 \"x는 식별자, +는 연산자\" 수준의 정보만 다루고 x가 어떤 타입으로 선언되었는지는 알지 못한다. 타입 판단에는 심볼 테이블이 필요하므로 반드시 의미 분석 단계에서 이루어진다.","o":["타입 오류는 구문 분석에서 잡히기 때문","어휘 분석은 문자를 토큰으로 자를 뿐 이름의 선언 정보나 타입을 전혀 모르기 때문이라고 늘 그대로 설명할 수 있다","타입 오류는 오류가 아니라 경고이기 때문","어휘 분석은 컴파일러가 아니라 링커가 맡아 수행하는 단계이기 때문이다"],"a":1},{"t":"choice","k":"cmp-sem-stat2","q":"강한 타입(strong typing)이 뜻하는 바로 가장 적절한 것은?","ex":"강/약은 타입 규칙을 얼마나 엄격히 지키는지, 즉 암묵적 변환을 얼마나 허용하는지의 축이다. 파이썬은 동적이지만 \"1\" + 1 을 거부하는 강한 타입이고, C는 정적이지만 포인터와 정수를 캐스팅으로 넘나들 수 있어 상대적으로 약하다.","o":["타입이 맞지 않을 때 몰래 암묵적 변환을 하지 않고 거부한다고 흔히 이해하면 된다","타입 검사를 컴파일 타임에 빠짐없이 해 둔다는 뜻으로 쓴다고 실무에서는 분명히 곰곰이 설명할 수 있다","모든 타입을 개발자가 빠짐없이 직접 손으로 적어야 한다 적어 두지 않으면 컴파일러가 타입을 추측할 방법이 없기 때문이다.","정수 타입의 크기가 항상 64비트다"],"a":0}],"th":{"sum":"문법에 맞는 코드라고 해서 의미가 통하는 것은 아니다. 의미 분석은 심볼 테이블로 이름을 해석하고 타입을 검사해 실행 전에 잡을 수 있는 오류를 걸러낸다.","body":[{"h":"심볼 테이블과 이름 해석","t":"심볼 테이블은 프로그램에 등장하는 이름을 그 선언 정보(타입, 종류, 위치)에 연결하는 자료구조다. 블록이 열릴 때마다 새 스코프를 밀어 넣고 닫힐 때 꺼내는 스택 구조로 흔히 구현한다. 이름을 찾을 때는 가장 안쪽 스코프부터 바깥으로 올라가며 검색하고, 끝까지 못 찾으면 \"선언되지 않은 변수\" 오류가 된다. 대부분의 현대 언어는 이름의 의미가 소스 코드의 중첩 구조로 결정되는 정적(렉시컬) 스코프를 쓰며, 호출 스택을 따라 결정되는 동적 스코프와 구별된다."},{"h":"타입 검사와 타입 추론","t":"타입 검사기는 AST를 순회하며 각 표현식의 타입을 계산하고 연산이 그 타입에 허용되는지 확인한다. 정수와 문자열을 더하는 것 같은 타입 불일치, 인자 개수나 타입이 맞지 않는 함수 호출이 여기서 걸린다. 타입 추론은 개발자가 어노테이션을 쓰지 않아도 컴파일러가 타입을 스스로 알아내는 기법으로, Hindley-Milner 알고리즘이 대표적이다. 추론이 있다고 해서 동적 타입이 되는 것이 아니라, 여전히 컴파일 타임에 완전한 정적 타입이 부여된다."},{"h":"정적/동적과 강/약은 다른 축","t":"정적 타입은 컴파일 타임에 타입을 검사하고, 동적 타입은 값에 타입표를 붙여 런타임에 검사한다. 이는 강/약 타입과 완전히 다른 축이다. 강한 타입은 몰래 하는 암묵적 변환을 허용하지 않는다는 뜻이라, 파이썬처럼 동적이면서 강한 타입인 언어도 있고 C처럼 정적이면서 상대적으로 약한 언어도 있다. 어느 단계에서 오류가 잡히는지 구분하는 것도 중요하다. 잘못된 문자는 어휘, 짝이 안 맞는 괄호는 구문, 선언되지 않은 변수와 타입 불일치는 의미 분석, 0으로 나누기나 널 참조는 대개 런타임이다."}],"code":{"c":"let x: int = 1;\n{\n    let x: string = \"hi\";   // 안쪽 스코프의 새 x\n    print(x + 1);           // 타입 오류: string + int\n}\nprint(y);                   // 이름 오류: y 미선언\n\n심볼 테이블(안쪽 블록 시점)\n  scope#1 (블록)  : x -> string\n  scope#0 (전역)  : x -> int\n\n조회 x  => 안쪽부터 검색 => string\n조회 y  => 어느 스코프에도 없음 => 오류","cap":"스코프 스택을 안쪽부터 검색하는 이름 해석과, 의미 분석에서 잡히는 두 종류의 오류."},"key":["심볼 테이블은 이름을 선언 정보에 연결하고 스코프는 스택처럼 중첩된다","선언되지 않은 변수·타입 불일치·인자 개수 오류는 의미 분석에서 잡힌다","정적/동적과 강/약 타입은 서로 독립된 축이다"]}}],"ord":2},{"t":"언어의 편의는 어디로 가나 — 실행 시간의 표현","g":"","l":[{"t":"실행 시간의 표현 I","q":[{"t":"choice","k":"스택이 싼 이유","cat":"internals","q":"지역 변수를 스택에 두는 것이 힙에 두는 것보다 훨씬 싼 이유는?","code":"함수에 들어갈 때\n  스택 포인터를 40바이트만큼 내린다      ← 명령 하나\n  지역 변수들은 그 안의 정해진 자리를 쓴다\n\n함수가 끝날 때\n  스택 포인터를 40바이트만큼 올린다      ← 명령 하나\n  안에 있던 것은 전부 한꺼번에 사라진다","o":["자리를 잡고 놓는 일이 포인터 하나를 옮기는 것으로 끝나기 때문이다 — 크기와 위치가 컴파일할 때 이미 정해져 있어 찾아다닐 필요가 없다","스택 변수는 개수가 적어 관리할 것이 적기 때문이다","스택이 힙보다 빠른 메모리 장치에 놓여 있기 때문이다","스택에 있는 값은 캐시에만 올라가고 메모리에는 쓰이지 않기 때문이다"],"a":0,"ex":"둘 다 같은 메모리다 — 차이는 <b>관리 방식</b>이다.\n개념: 힙은 '어디에 얼마나 빈 자리가 있는지' 를 찾아야 하고, 다 쓴 뒤 언제 놓을지도 정해야 한다. 스택은 그 두 질문에 답이 이미 나와 있다 — 맨 위에 잡고, 함수가 끝나면 놓는다.\n실무: 그래서 컴파일러는 가능한 한 스택에 두려고 한다. 무엇을 힙으로 보낼지 정하는 판단이 다음 문제의 주제다."},{"t":"choice","k":"힙으로 올라가는 값","cat":"internals","q":"아래에서 지역 변수가 스택에 머무를 수 없는 이유는?","code":"function makeCounter() {\n  let count = 0;              // 지역 변수\n  return () =&gt; ++count;       // 이 함수가 count 를 기억한다\n}\nconst c = makeCounter();      // makeCounter 는 이미 끝났다\nc(); c();                     // 그런데 count 는 살아 있다","o":["클로저 안에서 쓰이는 변수는 문법적으로 힙에만 둘 수 있기 때문이다","함수가 끝난 뒤에도 값 쓰는 곳이 남아서","makeCounter 가 값을 반환하므로 모든 지역 변수가 힙으로 옮겨지기 때문이다","증가시키는 연산이 스택에서는 지원되지 않기 때문이다"],"a":1,"ex":"판단 기준은 하나다 — <b>이 값이 함수보다 오래 사는가</b>.\n개념: 컴파일러가 이것을 알아내는 분석을 탈출 분석이라고 한다. 값의 주소가 함수 밖으로 새어 나가는지를 따라가 본다.\n실무: 마지막 보기가 틀린 이유가 중요하다 — <b>반환한다고 다 옮겨지지 않는다</b>. 값을 복사해 돌려주면 원본은 스택에 남아도 된다. 주소가 나가는 것과 값이 나가는 것은 다르다.\n왜 그 답인가: 스택은 함수와 함께 사라지므로, 컴파일러가 이런 값을 찾아내 힙으로 옮긴다"},{"t":"choice","k":"객체 하나의 실제 크기","cat":"perf","q":"숫자 하나만 담은 객체 100만 개를 만들었더니 개당 40바이트를 썼다. 담은 값은 8바이트인데 나머지는 무엇인가?","code":"{ x: 1 } 을 100만 개 만들면\n  실제로 쓴 메모리   개당 40 바이트\n  담긴 값 자체        개당  8 바이트","o":["메모리 관리자가 나중을 위해 여유 공간을 미리 넉넉하게 잡아 두고 있기 때문이라고 기본이 되는 내용이라 대체로 이해할 수 있다","숫자가 내부적으로 40바이트 형식으로 저장되기 때문이라고 실제로 차근차근 짚어 두어야 한다","객체 머리말과 자리 맞춤이 함께 들어가기 때문이라고 흔히 짚어 두어야 한다","속성 이름 'x' 를 객체마다 따로따로 문자열로 저장해 두기 때문이라고 늘 차근차근 알아 두어야 한다"],"a":2,"ex":"값 8바이트에 <b>32바이트의 부대 비용</b>이 붙었다 — 다섯 배다.\n개념: 실행 중에 '이것이 무슨 타입인지', '어떤 속성이 어디 있는지' 를 알아야 하므로 그 정보를 함께 들고 다닌다. 정적 타입 언어는 이 정보가 적어 부대 비용도 작다.\n실무: 그래서 작은 객체를 아주 많이 만들면 메모리가 예상의 몇 배가 된다. 같은 값을 배열 하나에 나란히 담으면 부대 비용이 <b>객체마다가 아니라 배열 하나에만</b> 붙는다.\n왜 그 답인가: 타입 정보, 속성 배치 정보 같은 것이 값과 별도로 필요하다"},{"t":"choice","k":"자리 맞춤","cat":"knowledge","q":"아래 두 구조체가 필드는 같은데 크기가 다르다. 왜인가?","code":"A)  1바이트 · 8바이트 · 1바이트   →  24 바이트\nB)  8바이트 · 1바이트 · 1바이트   →  16 바이트\n\n담는 값은 양쪽 다 10바이트뿐이다","o":["필드 순서에 따라 컴파일러가 다른 자료형을 고르기 때문이다","A 가 더 많은 필드를 담을 수 있도록 컴파일러가 미리 예비 공간을 잡아 두기 때문이다 필드를 더 넣을 때 크기를 다시 계산하지 않아도 되기 때문이라고 분명히 할 수 있다","1바이트 값이 실제로는 8바이트로 저장되기 때문이다","큰 값은 자기 크기의 배수 자리에서 시작해야 해서 그 앞에 빈칸이 끼어들기 때문이다 — 큰 것부터 놓으면 빈칸이 줄어든다고 꽤 설명할 수 있다"],"a":3,"ex":"A 는 1바이트 뒤에 <b>7칸을 비워야</b> 8바이트 값이 제자리에서 시작한다.\n개념: 정렬을 맞추면 CPU 가 한 번에 읽을 수 있다. 어긋나 있으면 두 번 읽어 붙여야 하거나 아예 오류가 난다. 그래서 컴파일러가 빈칸을 넣는다.\n실무: 필드가 많은 구조체를 아주 많이 만든다면 <b>큰 것부터 늘어놓는 것</b>만으로 메모리가 줄어든다. 언어에 따라 컴파일러가 알아서 재배치하기도 한다."}],"th":{"sum":"소스에는 클래스·클로저·제네릭·예외가 있지만, <b>기계어에는 그런 것이 없습니다</b>. 있는 것은 메모리 주소와 점프뿐이에요. 그 사이를 컴파일러가 메웁니다 — 편의를 없애는 것이 아니라 <b>기계가 아는 것으로 바꿔 놓는</b> 것이고, 그 바꿔 놓은 모양이 실행 시간의 성능과 제약을 정합니다.","body":[{"h":"값이 어디에 사는지가 먼저 정해진다","t":"지역 변수는 <b>스택</b>에 자리를 잡습니다 — 함수가 시작할 때 통째로 잡고 끝날 때 통째로 놓아요. 아주 싸죠. 문제는 <b>함수보다 오래 사는 값</b>입니다. 그것을 스택에 두면 함수가 끝나는 순간 사라지므로, 컴파일러가 알아채고 <b>힙으로 옮깁니다</b>."},{"h":"클로저는 구조체 하나다","t":"'바깥 변수를 기억하는 함수' 는 마법이 아닙니다. <b>코드가 있는 곳의 주소와, 기억할 변수들을 담은 상자</b>를 한 묶음으로 만든 것이에요. 그래서 무엇을 담았느냐가 곧 동작이 됩니다 — <b>값을 담았는지 그 변수가 사는 자리를 담았는지</b>가 결과를 가릅니다."},{"h":"어느 함수를 부를지 나중에 정한다","t":"부를 함수가 컴파일할 때 정해지면 그냥 그 주소로 점프합니다. 하지만 실제 타입에 따라 달라져야 하면, <b>객체마다 '내 함수들의 주소표' 를 들고 다니게</b> 하고 실행 중에 그 표를 봐요. 한 번 더 거치는 셈이라 <b>인라인 같은 최적화가 막힙니다</b>."},{"h":"안 쓰면 공짜, 쓰면 비싸다","t":"요즘 예외 처리는 <b>던지지 않는 동안 비용이 거의 0</b>이 되도록 만들어져 있습니다. 대신 실제로 던지면 표를 뒤져 되감아야 해서 <b>아주 비싸요</b>. 재어 보면 값으로 알리는 것보다 수백 배 느립니다. 그래서 예외는 <b>드문 일에만</b> 씁니다."}],"code":{"t":"소스에는 있고 기계어에는 없는 것들","c":"소스에 적은 것                기계어에서의 모습\n\n  지역 변수                     스택 프레임 안의 자리 (오프셋)\n  함수보다 오래 사는 값         힙에 할당하고 주소만 넘긴다\n  클로저                        [코드 주소 + 담아 둔 변수 상자]\n  가상 메서드 호출              객체 → 함수 주소표 → 그 자리로 점프\n  제네릭                        타입을 지우거나, 타입마다 코드를 찍어 낸다\n  try / catch                   실행 코드가 아니라 옆에 놓인 표\n  소멸자 · finally              되감는 길목마다 끼워 넣은 정리 코드\n\n측정해 보면\n  예외를 던져 알리기   2682 ms   ┐ 100만 번, 절반 실패\n  값으로 돌려주기         3 ms   ┘ 889배\n  던지지 않고 try 로 감싸기만 하면 차이 없음 (1.50 대 1.51 ms)"},"key":["값의 수명이 스택에 둘지 힙에 둘지를 정한다","클로저는 코드 주소와 담아 둔 변수를 묶은 구조체다","동적 디스패치는 주소표를 한 번 더 거치므로 인라인이 막힌다","제네릭은 타입을 지우거나 타입마다 코드를 찍어 낸다","예외는 안 던지면 공짜지만 던지면 수백 배 비싸다"]}},{"t":"실행 시간의 표현 II","q":[{"t":"choice","k":"클로저의 정체","cat":"internals","q":"클로저가 기계어 수준에서 어떻게 표현되는지 가장 정확히 설명한 것은?","code":"const add = (a) =&gt; (b) =&gt; a + b;\nconst add5 = add(5);\n\nadd5 는 무엇을 들고 있어야 하는가?","o":["실행할 코드의 주소와, 기억해야 할 변수를 담은 상자를 묶은 구조체다 — 부를 때 그 상자를 숨은 인자처럼 함께 넘긴다고 실무에서는 실제로 이해할 수 있다","바깥 함수의 스택 프레임을 통째로 복사해 들고 있다","전역 표에 등록해 두고 이름으로 찾아 부른다","함수의 소스 코드를 문자열로 담고 있다가 부를 때마다 그것을 다시 해석해 실행한다 그래서 클로저를 많이 만들면 문자열 파싱 비용이 계속 쌓인다고 실무에서는 분명히 그대로 볼 수 있다"],"a":0,"ex":"클로저는 특별한 것이 아니라 <b>구조체 하나</b>다 — 자료와 코드 주소를 함께 담은.\n개념: 그래서 '함수를 값처럼 주고받는다' 는 것이 가능하다. 실제로 주고받는 것은 그 구조체의 주소다.\n실무: 그리고 그 상자에 무엇이 들어 있는지가 성능과 동작을 정한다. 큰 객체를 담으면 그것이 계속 살아 있게 되고 — <b>클로저 하나가 메모리를 붙들고 있는</b> 흔한 누수의 원인이다."},{"t":"choice","k":"무엇을 담았나","cat":"debug","q":"아래 두 반복문이 만든 함수들의 결과가 다르다. 실행 시간의 표현으로 설명하면?","code":"for (var i = 0; i &lt; 3; i++) fs.push(() =&gt; i);\nfs.map(f =&gt; f())   →  [3, 3, 3]\n\nfor (let j = 0; j &lt; 3; j++) gs.push(() =&gt; j);\ngs.map(g =&gt; g())   →  [0, 1, 2]","o":["화살표 함수가 두 경우에 서로 다른 방식으로 변환되기 때문이며 변수와는 무관하다 앞의 반복문은 함수 선언으로, 뒤는 표현식으로 변환되기 때문이다.","앞은 변수가 사는 자리 한 칸을 셋이 함께 담았고, 뒤는 반복마다 새 자리를 만들어 각자 담았기 때문이다","앞은 값을 복사해 담았고 뒤는 참조를 담았기 때문이다","앞의 반복문이 끝난 뒤 함수들이 다시 실행되었기 때문이다"],"a":1,"ex":"결과가 <b>3, 3, 3</b> 이라는 것이 결정적이다 — 셋 다 같은 칸을 보고 있고, 반복이 끝난 뒤의 값을 읽었다.\n개념: 클로저가 담는 것은 '그때의 값' 이 아니라 '그 변수가 사는 자리' 다. 자리를 공유하면 나중에 바뀐 값이 보인다.\n실무: 그래서 반복마다 새 자리를 만드는 문법이 생겼다. 다른 언어에서도 같은 함정이 있고, 대개 '반복 변수를 명시적으로 복사하라' 는 형태로 해결한다."},{"t":"choice","k":"표를 거쳐 부르기","cat":"internals","q":"실제 타입에 따라 다른 함수를 불러야 할 때, 컴파일러는 이것을 무엇으로 바꾸는가?","code":"shape.area()   // shape 이 원인지 사각형인지는 실행 중에 정해진다\n\n각 객체가 자기 종류의 함수 주소표를 가리키고 있다면\n  객체 → 표 → area 자리의 주소 → 그 주소로 점프","o":["타입마다 별도의 프로그램을 만들어 두고 실행할 때 고르게 한다고 꽤 차근차근 이해할 수 있다","함수 이름을 문자열로 들고 다니다가 실행 중에 이름으로 찾는 코드로 바꾼다고 실무에서는 실제로 어렵지 않게 알아 두어야 한다","함수 주소표를 읽어 그 주소로 점프하는 코드","모든 타입에 대한 조건문을 나열한다"],"a":2,"ex":"값 하나를 더 읽는 것뿐인데 <b>영향이 큰 이유</b>가 다음 문제의 내용이다.\n개념: 직접 호출은 주소가 코드에 박혀 있어 컴파일러가 '이 함수가 무엇을 하는지' 를 안다. 표를 거치면 실행 전에는 알 수 없으니 인라인도, 그 뒤에 따라오는 최적화도 막힌다.\n실무: 세 번째 보기 같은 방식을 쓰는 언어도 있다 — 이름으로 찾는 쪽은 훨씬 느리지만 더 유연하다. 두 방식의 절충이 다음 문제의 인라인 캐시다.\n왜 그 답인가: 부를 곳이 실행 중에 정해지므로 메모리를 한 번 더 거친다"},{"t":"choice","k":"대개 같은 종류더라","cat":"perf","q":"같은 호출 자리인데 아래처럼 속도가 다르다. 실행 시간이 어떤 최적화를 하고 있다는 뜻인가?","code":"같은 자리에서 메서드 호출 500만 번\n\n  들어오는 객체가 항상 한 종류    18.0 ms\n  들어오는 객체가 여섯 종류       87.4 ms\n\n  4.8배","o":["객체 종류가 많으면 메모리를 더 써서 캐시가 부족해지기 때문이다","여섯 종류를 순서대로 도느라 분기 예측이 실패한이라고 보면 된다","종류마다 별도의 코드를 만들어 두느라 컴파일하는 시간이 늘어난 것이며 실행과는 무관하다 실행 자체는 두 경우 모두 같은 경로를 지나므로 차이가 없다고 실무에서는 흔히 한 번 더 볼 수 있다","그 자리에 오던 종류를 기억해 두었다가 다음에도 같으면 표를 건너뛰는 최적화다 — 종류가 여러 가지면 기억이 계속 어긋나 이득이 사라진다고 분명히 어렵지 않게 새겨 두어야 한다"],"a":3,"ex":"코드는 한 줄로 같은데 <b>지나가는 객체의 종류만으로</b> 다섯 배가 갈렸다.\n개념: 실제 프로그램에서는 한 호출 자리에 거의 항상 같은 종류가 온다. 그 관찰을 이용해 '지난번과 같으면 곧바로 그 함수로' 를 만들어 둔다.\n실무: 그래서 한 자리에서 온갖 종류를 다루는 코드는 느려진다. 같은 모양의 객체를 쓰고, 속성을 나중에 추가해 모양을 바꾸지 않는 것이 도움이 된다."}],"th":{"sum":"소스에는 클래스·클로저·제네릭·예외가 있지만, <b>기계어에는 그런 것이 없습니다</b>. 있는 것은 메모리 주소와 점프뿐이에요. 그 사이를 컴파일러가 메웁니다 — 편의를 없애는 것이 아니라 <b>기계가 아는 것으로 바꿔 놓는</b> 것이고, 그 바꿔 놓은 모양이 실행 시간의 성능과 제약을 정합니다.","body":[{"h":"값이 어디에 사는지가 먼저 정해진다","t":"지역 변수는 <b>스택</b>에 자리를 잡습니다 — 함수가 시작할 때 통째로 잡고 끝날 때 통째로 놓아요. 아주 싸죠. 문제는 <b>함수보다 오래 사는 값</b>입니다. 그것을 스택에 두면 함수가 끝나는 순간 사라지므로, 컴파일러가 알아채고 <b>힙으로 옮깁니다</b>."},{"h":"클로저는 구조체 하나다","t":"'바깥 변수를 기억하는 함수' 는 마법이 아닙니다. <b>코드가 있는 곳의 주소와, 기억할 변수들을 담은 상자</b>를 한 묶음으로 만든 것이에요. 그래서 무엇을 담았느냐가 곧 동작이 됩니다 — <b>값을 담았는지 그 변수가 사는 자리를 담았는지</b>가 결과를 가릅니다."},{"h":"어느 함수를 부를지 나중에 정한다","t":"부를 함수가 컴파일할 때 정해지면 그냥 그 주소로 점프합니다. 하지만 실제 타입에 따라 달라져야 하면, <b>객체마다 '내 함수들의 주소표' 를 들고 다니게</b> 하고 실행 중에 그 표를 봐요. 한 번 더 거치는 셈이라 <b>인라인 같은 최적화가 막힙니다</b>."},{"h":"안 쓰면 공짜, 쓰면 비싸다","t":"요즘 예외 처리는 <b>던지지 않는 동안 비용이 거의 0</b>이 되도록 만들어져 있습니다. 대신 실제로 던지면 표를 뒤져 되감아야 해서 <b>아주 비싸요</b>. 재어 보면 값으로 알리는 것보다 수백 배 느립니다. 그래서 예외는 <b>드문 일에만</b> 씁니다."}],"code":{"t":"소스에는 있고 기계어에는 없는 것들","c":"소스에 적은 것                기계어에서의 모습\n\n  지역 변수                     스택 프레임 안의 자리 (오프셋)\n  함수보다 오래 사는 값         힙에 할당하고 주소만 넘긴다\n  클로저                        [코드 주소 + 담아 둔 변수 상자]\n  가상 메서드 호출              객체 → 함수 주소표 → 그 자리로 점프\n  제네릭                        타입을 지우거나, 타입마다 코드를 찍어 낸다\n  try / catch                   실행 코드가 아니라 옆에 놓인 표\n  소멸자 · finally              되감는 길목마다 끼워 넣은 정리 코드\n\n측정해 보면\n  예외를 던져 알리기   2682 ms   ┐ 100만 번, 절반 실패\n  값으로 돌려주기         3 ms   ┘ 889배\n  던지지 않고 try 로 감싸기만 하면 차이 없음 (1.50 대 1.51 ms)"},"key":["값의 수명이 스택에 둘지 힙에 둘지를 정한다","클로저는 코드 주소와 담아 둔 변수를 묶은 구조체다","동적 디스패치는 주소표를 한 번 더 거치므로 인라인이 막힌다","제네릭은 타입을 지우거나 타입마다 코드를 찍어 낸다","예외는 안 던지면 공짜지만 던지면 수백 배 비싸다"]}},{"t":"실행 시간의 표현 III","q":[{"t":"choice","k":"지워 버리기","cat":"knowledge","q":"제네릭 타입 정보를 컴파일 뒤에 지워 버리는 방식의 대가는?","code":"소스        목록&lt;문자열&gt;   ·   목록&lt;정수&gt;\n\n컴파일 뒤   목록          ·   목록      (같은 것이 되었다)\n\n실행 중에 '이 목록이 무엇을 담는 목록인지' 를 물으면?","o":["실행 중에는 그 정보가 없어 물어볼 수 없다 — 검사는 컴파일 때 이미 끝났고, 그 뒤로는 타입 없는 목록 하나만 남는다고 짚어 두어야 한다","컴파일된 코드의 크기가 타입 수만큼 늘어난다","실행이 느려진다","타입이 다른 목록끼리 대입되어 실행 중 오류가 난다"],"a":0,"ex":"지우는 방식의 이득은 <b>코드가 한 벌이면 된다</b>는 것이고, 대가가 이것이다.\n개념: 컴파일할 때 검사를 다 했으니 실행 중에 타입을 들고 다닐 이유가 없다는 발상이다. 기존 코드와의 호환도 쉬워진다.\n실무: 그래서 이런 언어에서는 '실행 중에 제네릭 타입으로 분기하기' 가 안 된다. 필요하면 타입을 나타내는 값을 따로 인자로 받아 넘기는 우회를 쓴다."},{"t":"choice","k":"타입마다 찍어 내기","cat":"knowledge","q":"타입마다 별도의 코드를 생성하는 방식은 무엇을 얻고 무엇을 잃는가?","code":"소스        목록&lt;문자열&gt;   ·   목록&lt;정수&gt;\n\n컴파일 뒤   목록_문자열용 코드\n            목록_정수용 코드      (따로 만들어졌다)","o":["실행은 느려지지만 컴파일이 빨라진다","각 코드가 구체적인 타입에 맞춰져 있어 빠르지만, 쓰는 타입만큼 코드가 늘어나 결과물이 커지고 컴파일도 오래 걸린다고 알아 두어야 한다","코드 크기는 그대로이면서 속도만 빨라진다","속도와 크기 두 가지 모두 타입을 지우는 방식보다 유리하다고 볼 수 있다 코드가 늘어나는 것은 링커가 중복을 합쳐 주므로 문제가 되지 않는다고 어느 정도는 새겨 두어야 한다"],"a":1,"ex":"'느린 대신 작다' 와 '빠른 대신 크다' 의 <b>고전적인 맞바꿈</b>이다.\n개념: 타입이 정해지면 크기도 알고 어떤 함수를 부를지도 안다. 표를 거칠 일이 없으니 인라인도 되고 벡터화도 된다.\n실무: 대신 널리 쓰이는 제네릭 함수는 수십 벌이 생긴다. 컴파일이 느려지고 실행 파일이 커지며, 명령어 캐시에도 부담이 된다 — <b>둘 중 하나가 항상 옳지는 않다</b>."},{"t":"choice","k":"오류 메시지가 다른 이유","cat":"debug","q":"제네릭을 잘못 쓴 오류 메시지가 언어마다 크게 다르다. 앞의 두 방식과 어떻게 이어지는가?","code":"지우는 방식\n  '목록에 정수를 넣을 수 없습니다'                (짧다)\n\n찍어 내는 방식\n  '목록_정수용 코드를 만들다가 실패:\n     그 안에서 부른 정렬_정수용 코드에서\n       비교_정수용 코드가 없습니다'              (길다)","o":["메시지 길이는 구현 방식과 무관하며 언어 설계자의 취향이다","지우는 방식은 오류를 실행 중으로 미루기 때문에 메시지가 짧다","찍어 내는 방식은 타입을 채워 넣고 코드를 만들어 보다가 실패하므로, 실패 지점이 소스가 아니라 생성 과정 안쪽이 된다","찍어 내는 방식이 훨씬 더 많은 검사를 하기 때문에 메시지가 길고 복잡해지는 것이다 검사를 많이 할수록 알려 줄 것이 많아 메시지가 자연히 길어진다고 늘 새겨 두어야 한다"],"a":2,"ex":"구현 방식이 <b>개발자가 매일 보는 화면</b>까지 정한다는 예다.\n개념: 지우는 방식은 소스만 보고 검사하므로 실패 지점이 소스 위치와 일치한다. 찍어 내는 방식은 여러 겹을 펼치다 실패하므로 그 경로가 통째로 나온다.\n실무: 그래서 후자를 쓰는 언어들은 '이 타입은 이런 조건을 만족해야 한다' 를 미리 적게 해서, 펼치기 전에 걸러 내고 짧은 메시지를 내려 한다."},{"t":"choice","k":"고르는 기준","cat":"design","q":"새 언어를 설계하며 두 방식 중 하나를 고른다. 판단에 가장 큰 영향을 주는 것은?","code":"지우기      코드 한 벌 · 결과물 작다 · 실행 중 타입 정보 없음\n찍어 내기   타입마다 한 벌 · 빠르다 · 결과물 크고 컴파일 느림","o":["최신 언어일수록 찍어 내는 방식이 옳으므로 그쪽을 고른다고 기본이 되는 내용이라 대체로 그대로 정리할 수 있다","컴파일러를 만들기 쉬운 쪽이 선택된다고 실무에서는 어느 정도는 알아 두어야 한다","문법이 얼마나 간결한가다","그 언어가 어디에 쓰일 것인가다고 이 단원에서는 정리할 수 있다"],"a":3,"ex":"두 방식 다 널리 쓰이는 언어들이 채택하고 있다 — <b>어느 쪽도 틀리지 않았다</b>.\n개념: 시스템 언어는 추상화를 써도 손으로 쓴 것만큼 빨라야 한다는 목표가 있어 찍어 내는 쪽으로 간다. 오래된 기존 코드와 함께 돌아야 하는 언어는 지우는 쪽이 현실적이었다.\n실무: 쓰는 입장에서도 이 차이를 알면 도움이 된다. 실행 중에 타입을 물어볼 수 있는지, 결과물 크기가 왜 그렇게 커지는지가 여기서 나온다.\n왜 그 답인가: 실행 속도가 최우선인 시스템 언어는 찍어 내는 쪽을, 배포 크기와 호환을 중시하면 지우는 쪽을 고른다"}],"th":{"sum":"소스에는 클래스·클로저·제네릭·예외가 있지만, <b>기계어에는 그런 것이 없습니다</b>. 있는 것은 메모리 주소와 점프뿐이에요. 그 사이를 컴파일러가 메웁니다 — 편의를 없애는 것이 아니라 <b>기계가 아는 것으로 바꿔 놓는</b> 것이고, 그 바꿔 놓은 모양이 실행 시간의 성능과 제약을 정합니다.","body":[{"h":"값이 어디에 사는지가 먼저 정해진다","t":"지역 변수는 <b>스택</b>에 자리를 잡습니다 — 함수가 시작할 때 통째로 잡고 끝날 때 통째로 놓아요. 아주 싸죠. 문제는 <b>함수보다 오래 사는 값</b>입니다. 그것을 스택에 두면 함수가 끝나는 순간 사라지므로, 컴파일러가 알아채고 <b>힙으로 옮깁니다</b>."},{"h":"클로저는 구조체 하나다","t":"'바깥 변수를 기억하는 함수' 는 마법이 아닙니다. <b>코드가 있는 곳의 주소와, 기억할 변수들을 담은 상자</b>를 한 묶음으로 만든 것이에요. 그래서 무엇을 담았느냐가 곧 동작이 됩니다 — <b>값을 담았는지 그 변수가 사는 자리를 담았는지</b>가 결과를 가릅니다."},{"h":"어느 함수를 부를지 나중에 정한다","t":"부를 함수가 컴파일할 때 정해지면 그냥 그 주소로 점프합니다. 하지만 실제 타입에 따라 달라져야 하면, <b>객체마다 '내 함수들의 주소표' 를 들고 다니게</b> 하고 실행 중에 그 표를 봐요. 한 번 더 거치는 셈이라 <b>인라인 같은 최적화가 막힙니다</b>."},{"h":"안 쓰면 공짜, 쓰면 비싸다","t":"요즘 예외 처리는 <b>던지지 않는 동안 비용이 거의 0</b>이 되도록 만들어져 있습니다. 대신 실제로 던지면 표를 뒤져 되감아야 해서 <b>아주 비싸요</b>. 재어 보면 값으로 알리는 것보다 수백 배 느립니다. 그래서 예외는 <b>드문 일에만</b> 씁니다."}],"code":{"t":"소스에는 있고 기계어에는 없는 것들","c":"소스에 적은 것                기계어에서의 모습\n\n  지역 변수                     스택 프레임 안의 자리 (오프셋)\n  함수보다 오래 사는 값         힙에 할당하고 주소만 넘긴다\n  클로저                        [코드 주소 + 담아 둔 변수 상자]\n  가상 메서드 호출              객체 → 함수 주소표 → 그 자리로 점프\n  제네릭                        타입을 지우거나, 타입마다 코드를 찍어 낸다\n  try / catch                   실행 코드가 아니라 옆에 놓인 표\n  소멸자 · finally              되감는 길목마다 끼워 넣은 정리 코드\n\n측정해 보면\n  예외를 던져 알리기   2682 ms   ┐ 100만 번, 절반 실패\n  값으로 돌려주기         3 ms   ┘ 889배\n  던지지 않고 try 로 감싸기만 하면 차이 없음 (1.50 대 1.51 ms)"},"key":["값의 수명이 스택에 둘지 힙에 둘지를 정한다","클로저는 코드 주소와 담아 둔 변수를 묶은 구조체다","동적 디스패치는 주소표를 한 번 더 거치므로 인라인이 막힌다","제네릭은 타입을 지우거나 타입마다 코드를 찍어 낸다","예외는 안 던지면 공짜지만 던지면 수백 배 비싸다"]}},{"t":"실행 시간의 표현 IV","q":[{"t":"choice","k":"던지면 무슨 일이","cat":"internals","q":"예외가 던져졌을 때 실행 시간이 하는 일을 가장 정확히 설명한 것은?","code":"A 가 B 를 부르고, B 가 C 를 불렀다\nC 에서 예외가 났고, 잡는 곳은 A 에 있다\n\n스택   [ A ][ B ][ C ]\n                    ↑ 여기서 던졌다","o":["스택을 되짚어 올라가며 잡는 곳을 찾고, 지나치는 프레임마다 정리 작업을 실행한다 — 표를 뒤져 가며 하는 일이라 그냥 반환하는 것과는 비교가 안 되게 비싸다고 늘 한 번 더 알아 두어야 한다","프로그램이 잠시 멈추고 운영체제가 스택을 정리해 준다","곧바로 A 의 잡는 자리로 점프한다","C 가 특별한 반환값을 돌려주고 B 와 A 가 차례로 그것을 확인한다"],"a":0,"ex":"두 번째 보기가 매력적이지만 틀렸다 — <b>지나치는 프레임을 그냥 버릴 수 없다</b>.\n개념: 중간 프레임에 열어 둔 파일이나 잡아 둔 락이 있을 수 있다. 그것을 정리하지 않고 건너뛰면 자원이 샌다. 그래서 프레임마다 '여기서 되감을 때 할 일' 을 찾아 실행한다.\n실무: 이 되감기 비용이 예외를 비싸게 만든다. 표를 찾는 일 자체가 느리고, 최적화하기도 어렵다."},{"t":"choice","k":"안 던지면 공짜","cat":"perf","q":"아래 두 측정이 함께 말해 주는 것은?","code":"100만 번, 절반이 실패하는 상황\n  예외를 던져 알리기   2682.0 ms\n  값으로 돌려주기         3.0 ms      889배\n\n던지지 않고 try 로 감싸기만\n  감싼 것    1.50 ms\n  안 감싼 것 1.51 ms      차이 없음","o":["예외가 느린 것은 그저 측정 오차일 뿐이며 실제로는 값을 반환하는 것과 아주 거의 비슷하다고 흔히 볼 수 있다","감싸 두는 것 자체는 공짜이고 실제로 던질 때만 비싸다고 늘 보아도 된다","try 로 감싸면 오히려 더 빨라지므로 되도록 많이 감싸 두어야 한다고 흔히 그대로 정리할 수 있다","예외를 쓰려면 try 블록을 되도록 최대한 크게 잡아야 한다고 늘 알아 두어야 한다"],"a":1,"ex":"요즘 구현은 <b>안 던지는 경로에 아무 코드도 넣지 않는다</b>. 필요한 정보는 실행 코드가 아니라 옆에 놓인 표에 있다.\n개념: 그래서 '성능 때문에 try 를 줄인다' 는 흔한 조언은 근거가 없다. 줄여야 할 것은 던지는 횟수다.\n실무: 판단 기준은 빈도다. 100번에 한 번 나는 일이면 예외가 읽기 좋고, 절반이 실패하는 일이면 값으로 돌려주는 편이 낫다 — 889배 차이가 그 이유다.\n왜 그 답인가: 그래서 예외 처리를 아끼는 것이 아니라 예외를 던지는 빈도를 아껴야 한다"},{"t":"choice","k":"정리를 보장하기","cat":"internals","q":"예외가 지나가도 정리 작업이 반드시 실행되도록 컴파일러는 무엇을 하는가?","code":"function f() {\n  const lock = acquire();\n  try { work(); }\n  finally { lock.release(); }     // 예외가 나도 반드시\n}","o":["정리는 보장되지 않으며 대부분의 경우에만 실행된다","예외가 나면 실행 시간이 소스를 다시 읽어 finally 블록의 위치를 찾아내 실행해 준다 그래서 finally 를 쓰면 소스 파일을 함께 배포해야 한다고 실무에서는 충분히 곰곰이 말할 수 있다","정상적으로 끝나는 길과 예외로 빠져나가는 길 양쪽에 정리 코드를 넣거나, 되감기 표에 등록해 둔다 — 나가는 모든 길목을 컴파일러가 챙긴다","finally 블록을 별도 스레드에서 실행해 본체와 분리한다"],"a":2,"ex":"요점은 <b>나가는 길이 하나가 아니라는 것</b>이다 — 정상 반환, 예외, 중간 반환이 모두 나가는 길이다.\n개념: 컴파일러는 그 길을 전부 찾아 같은 정리 코드를 끼워 넣거나, 되감기 과정에서 부를 수 있도록 표에 적어 둔다. 사람이 손으로 하기에는 빠뜨리기 쉬운 일이다.\n실무: 그래서 자원 정리는 finally 나 그에 해당하는 언어 기능에 맡긴다. '오류가 난 다음 줄에서 정리한다' 는 방식은 <b>예외가 지나가는 길을 놓친다</b>."},{"t":"choice","k":"무엇으로 알릴까","cat":"design","q":"실패를 알리는 방법을 정한다. 이 단원의 측정에서 따라 나오는 기준은?","code":"상황 A   설정 파일이 없다              프로그램 실행당 한 번\n상황 B   입력 검증 실패                 요청 절반\n상황 C   목록에서 찾는 항목이 없다      호출마다 흔함","o":["모든 실패를 값으로 알려야 성능이 좋다고 실제 현장에서 자주 마주치는 꼴이라 어느 정도는 있는 그대로 알아 두어야 한다","모든 실패를 예외로 알려야 놓치지 않게 된다고 이 단원에서는 흔히 그대로 말할 수 있다","실패의 심각도에 따라 정하는 것이며 빈도와는 아무 관계가 없다고 대체로 차근차근 새겨 두어야 한다","드물면 예외, 흔하면 값이라고 봐도 된다"],"a":3,"ex":"빈도 말고 다른 기준도 있지만, <b>이 단원이 근거를 준 것은 빈도</b>다.\n개념: 상황 A 는 예외가 좋다 — 드물고, 잊으면 안 되고, 부르는 쪽이 대개 처리할 수 없다. 상황 C 는 값이 좋다 — 흔하고, 실패가 정상적인 결과 중 하나다.\n실무: 함께 볼 기준은 '<b>부르는 쪽이 잊어도 되는가</b>' 다. 값으로 돌려주면 확인을 잊을 수 있고, 예외는 잊으면 프로그램이 멈춘다. 이 트랙의 오류 진단 단원과 이어지는 판단이다.\n왜 그 답인가: 흔한 실패를 예외로 알리면 정상 경로가 사실상 느린 경로가 된다"}],"th":{"sum":"소스에는 클래스·클로저·제네릭·예외가 있지만, <b>기계어에는 그런 것이 없습니다</b>. 있는 것은 메모리 주소와 점프뿐이에요. 그 사이를 컴파일러가 메웁니다 — 편의를 없애는 것이 아니라 <b>기계가 아는 것으로 바꿔 놓는</b> 것이고, 그 바꿔 놓은 모양이 실행 시간의 성능과 제약을 정합니다.","body":[{"h":"값이 어디에 사는지가 먼저 정해진다","t":"지역 변수는 <b>스택</b>에 자리를 잡습니다 — 함수가 시작할 때 통째로 잡고 끝날 때 통째로 놓아요. 아주 싸죠. 문제는 <b>함수보다 오래 사는 값</b>입니다. 그것을 스택에 두면 함수가 끝나는 순간 사라지므로, 컴파일러가 알아채고 <b>힙으로 옮깁니다</b>."},{"h":"클로저는 구조체 하나다","t":"'바깥 변수를 기억하는 함수' 는 마법이 아닙니다. <b>코드가 있는 곳의 주소와, 기억할 변수들을 담은 상자</b>를 한 묶음으로 만든 것이에요. 그래서 무엇을 담았느냐가 곧 동작이 됩니다 — <b>값을 담았는지 그 변수가 사는 자리를 담았는지</b>가 결과를 가릅니다."},{"h":"어느 함수를 부를지 나중에 정한다","t":"부를 함수가 컴파일할 때 정해지면 그냥 그 주소로 점프합니다. 하지만 실제 타입에 따라 달라져야 하면, <b>객체마다 '내 함수들의 주소표' 를 들고 다니게</b> 하고 실행 중에 그 표를 봐요. 한 번 더 거치는 셈이라 <b>인라인 같은 최적화가 막힙니다</b>."},{"h":"안 쓰면 공짜, 쓰면 비싸다","t":"요즘 예외 처리는 <b>던지지 않는 동안 비용이 거의 0</b>이 되도록 만들어져 있습니다. 대신 실제로 던지면 표를 뒤져 되감아야 해서 <b>아주 비싸요</b>. 재어 보면 값으로 알리는 것보다 수백 배 느립니다. 그래서 예외는 <b>드문 일에만</b> 씁니다."}],"code":{"t":"소스에는 있고 기계어에는 없는 것들","c":"소스에 적은 것                기계어에서의 모습\n\n  지역 변수                     스택 프레임 안의 자리 (오프셋)\n  함수보다 오래 사는 값         힙에 할당하고 주소만 넘긴다\n  클로저                        [코드 주소 + 담아 둔 변수 상자]\n  가상 메서드 호출              객체 → 함수 주소표 → 그 자리로 점프\n  제네릭                        타입을 지우거나, 타입마다 코드를 찍어 낸다\n  try / catch                   실행 코드가 아니라 옆에 놓인 표\n  소멸자 · finally              되감는 길목마다 끼워 넣은 정리 코드\n\n측정해 보면\n  예외를 던져 알리기   2682 ms   ┐ 100만 번, 절반 실패\n  값으로 돌려주기         3 ms   ┘ 889배\n  던지지 않고 try 로 감싸기만 하면 차이 없음 (1.50 대 1.51 ms)"},"key":["값의 수명이 스택에 둘지 힙에 둘지를 정한다","클로저는 코드 주소와 담아 둔 변수를 묶은 구조체다","동적 디스패치는 주소표를 한 번 더 거치므로 인라인이 막힌다","제네릭은 타입을 지우거나 타입마다 코드를 찍어 낸다","예외는 안 던지면 공짜지만 던지면 수백 배 비싸다"]}}],"ord":3},{"t":"최적화·코드 생성과 실행 방식","l":[{"t":"IR과 최적화 기법","q":[{"t":"choice","k":"cmp-opt-ir4","q":"다음 변환에 사용된 최적화 기법 두 가지를 순서대로 고르면?","ex":"3 * 4 를 컴파일 타임에 계산해 12로 바꾼 것이 상수 접기다. c는 계산 후 아무 곳에서도 사용되지 않아 결과에 영향을 주지 않으므로 죽은 코드 제거로 삭제된다.","code":"변환 전:            변환 후:\n  a = 3 * 4;          a = 12;\n  b = a + 1;          b = a + 1;\n  c = 999;            return b;\n  return b;","o":["인라이닝과 강도 감소 이렇게 두 가지 기법이다","루프 언롤링과 명령어 스케줄링 이렇게 두 가지 기법이라고 대체로 곰곰이 정리할 수 있다","레지스터 할당과 스필 처리 두 가지","상수 접기, DCE"],"a":3},{"t":"choice","k":"cmp-opt-ir2","q":"최적화가 지켜야 하는 가장 근본적인 원칙은?","ex":"최적화는 semantics-preserving 변환이어야 하며, 같은 입력에 대해 관찰 가능한 결과가 달라지면 그것은 최적화가 아니라 버그다. 인라이닝처럼 코드 크기를 오히려 늘리는 최적화도 있으므로 줄 수 감소는 목표가 아니다.","o":["코드 줄 수를 줄인다","관찰 가능한 의미를 보존이라고 흔히 말할 수 있다","필요하다면 프로그램의 의미를 바꿔서라도 속도를 높여야 한다고 흔히 새겨 두어야 한다","실행 시간을 절반 이하로 줄여야 한다고 꽤 무리 없이 이해할 수 있다"],"a":1},{"t":"choice","k":"cmp-opt-ir5","q":"SSA(정적 단일 배정) 형태의 특징으로 옳은 것은?","ex":"SSA에서는 재대입 대신 x1, x2 같은 새 이름을 만들기 때문에 어떤 사용이 어떤 정의에서 왔는지 한눈에 드러난다. 제어 흐름이 합류하는 지점에서는 phi 함수로 여러 정의를 합치며, 이 성질 덕분에 상수 전파나 DCE 같은 분석이 훨씬 간단해진다.","o":["각 변수에 값이 정확히 한 번만 배정되어 정의-사용 관계가 명확해지고 데이터 흐름 분석이 쉬워진다고 충분히 알아 두어야 한다","모든 변수를 전역 변수로 바꿔 스코프라는 개념 자체를 없애 버리는 형태다 이름이 하나로 합쳐지므로 정의-사용 관계를 찾기 쉬워진다고 차근차근 알아 두어야 한다","레지스터를 하나만 사용하도록 강제한다","소스 코드의 주석을 IR에 그대로 보존한다"],"a":0},{"t":"input","k":"cmp-opt-ir6","q":"동일한 계산을 두 번 하는 대신 첫 결과를 재사용하는 최적화의 한국어 이름은? (예: OO OOO 제거)","ex":"공통 부분식 제거(CSE)는 같은 피연산자로 같은 연산을 반복하는 곳을 찾아 앞서 계산한 값을 다시 쓴다. 다만 그 사이에 피연산자가 변경되지 않았다는 것이 보장되어야 의미가 보존된다.","a":["공통 부분식 제거"]},{"t":"choice","k":"cmp-opt-ir3","q":"루프 불변 코드 이동(LICM)이 하는 일은?","ex":"LICM은 반복해도 결과가 같은 계산을 찾아 루프 진입 전에 한 번만 실행하도록 옮긴다. 곱셈을 시프트로 바꾸는 것은 강도 감소, 호출을 펼치는 것은 인라이닝으로 각각 다른 최적화다.","o":["루프 전체를 삭제한다","함수 호출을 호출한 지점에 그대로 펼쳐 넣어 준다 루프 안의 계산을 밖으로 옮기는 일은 다른 최적화가 맡는다고 꽤 차근차근 짚어 두어야 한다","루프 본문에서 반복마다 값이 변하지 않는 계산을 루프 밖으로 끌어낸다고 비교적 자주 차근차근 정리할 수 있다","루프 안의 곱셈을 값이 같은 더 싼 덧셈이나 시프트 연산으로 바꿔서 넣어 준다고 이 단원에서는 분명히 어렵지 않게 이해할 수 있다"],"a":2},{"t":"choice","k":"cmp-opt-ir1","q":"컴파일러가 AST에서 곧바로 기계어를 만들지 않고 중간 표현(IR)을 두는 이유로 가장 적절한 것은?","ex":"M개 언어와 N개 대상 아키텍처가 있을 때 IR을 가운데 두면 M×N개가 아니라 M+N개의 부품만 만들면 된다. 게다가 상수 접기나 DCE 같은 최적화를 IR 수준에서 한 번만 구현하면 모든 언어와 모든 대상이 그 혜택을 공유한다.","o":["IR이 소스 코드보다 사람이 읽기 좋기 때문","IR을 거쳐야 타입 검사를 할 수 있기 때문","IR 이 없으면 소스에 있는 문법 오류를 잡아낼 수 없기 때문이다 문법 검사는 IR 을 만드는 과정에서 함께 이루어지기 때문이라고 기본이 되는 내용이라 꽤 어렵지 않게 할 수 있다","언어와 대상 CPU의 조합마다 컴파일러를 새로 만들지 않아도 되고 최적화 패스를 공유할 수 있기 때문이다"],"a":3}],"th":{"sum":"앞단이 만든 AST는 중간 표현(IR)으로 낮아진 뒤 의미를 보존하는 최적화를 거쳐 기계어로 내려간다. 같은 언어라도 인터프리터, AOT 컴파일, JIT 중 어떤 방식으로 실행하느냐에 따라 성능 특성이 달라진다.","body":[{"h":"IR과 최적화","t":"IR은 소스 언어와 대상 기계 사이에 놓인 중간 언어로, 3-주소 코드처럼 단순한 형태를 쓴다. 여러 언어와 여러 CPU를 조합할 때 각 조합마다 컴파일러를 만들지 않아도 되게 해 주고, 최적화 패스가 공유할 공통 기반이 된다. SSA(정적 단일 배정) 형태는 각 변수에 값이 딱 한 번만 배정되도록 만들어 정의-사용 관계를 명확히 하고 데이터 흐름 분석을 쉽게 한다. 최적화는 반드시 관찰 가능한 의미를 보존해야 하며, 상수 접기, 공통 부분식 제거(CSE), 죽은 코드 제거(DCE), 인라이닝, 루프 불변 코드 이동(LICM), 강도 감소가 대표적이다."},{"h":"코드 생성과 레지스터 할당","t":"코드 생성은 크게 명령어 선택, 레지스터 할당, 명령어 스케줄링으로 나뉜다. 명령어 선택은 IR 연산을 대상 CPU의 실제 명령어로 대응시키고, 레지스터 할당은 무제한처럼 다루던 가상 레지스터를 물리 레지스터의 유한한 개수에 밀어 넣는다. 이 문제는 동시에 살아 있는 값끼리 간선을 잇는 간섭 그래프의 그래프 색칠로 모델링되며, 색이 모자라면 일부 값을 메모리로 밀어내는 스필(spill)이 발생해 메모리 접근 비용이 생긴다. 명령어 스케줄링은 파이프라인 지연을 줄이도록 순서를 재배치한다."},{"h":"인터프리터, AOT, JIT","t":"인터프리터는 소스나 바이트코드를 읽어 즉시 실행하므로 시작이 빠르고 디버깅과 반복 개발이 편하지만, 실행 중 해석 오버헤드가 있다. AOT 컴파일은 미리 기계어를 만들어 두어 실행이 빠른 대신 별도의 빌드 단계가 필요하다. 바이트코드 VM은 그 중간 형태다. JIT은 런타임에 자주 실행되는 핫 경로를 찾아 기계어로 컴파일하며, 실제로 흘러온 타입 같은 런타임 정보를 이용한 추측 최적화를 한다. 가정이 깨지면 역최적화(deoptimization)로 인터프리터로 되돌아가며, 컴파일 자체에 드는 워밍업 비용이 있어 짧게 끝나는 프로그램에서는 이득이 적을 수 있다."}],"code":{"c":"원본 IR (3-주소 코드)\n  t1 = 2 * 3\n  t2 = a + t1\n  t3 = a + t1      ; t2와 같은 계산\n  t4 = t2 + t3\n  t5 = 99          ; 아무도 안 씀\n  return t4\n\n상수 접기 -> t1 = 6\nCSE       -> t3 삭제, t3 자리에 t2 사용\nDCE       -> t5 삭제\n\n최적화 후\n  t1 = 6\n  t2 = a + t1\n  t4 = t2 + t2\n  return t4","cap":"상수 접기·CSE·DCE를 차례로 적용해도 반환값의 의미는 그대로다."},"key":["IR은 여러 언어와 여러 대상 CPU를 잇는 공통 기반이고 SSA는 흐름 분석을 돕는다","최적화는 관찰 가능한 의미를 보존하며 더 빠르거나 작은 코드를 만든다","JIT은 런타임 정보를 활용한 추측 최적화와 역최적화를 하며 워밍업 비용이 있다"]}},{"t":"코드 생성과 레지스터 할당","q":[{"t":"choice","k":"cmp-gen-reg1","q":"코드 생성 단계의 주요 하위 작업을 올바르게 묶은 것은?","ex":"코드 생성은 IR 연산을 실제 CPU 명령으로 고르고(명령어 선택), 값을 물리 레지스터에 배치하고(레지스터 할당), 파이프라인 효율을 위해 순서를 조정한다(스케줄링). 나머지 보기는 앞단 또는 컴파일러 바깥의 작업이다.","o":["링킹, 로딩, 가비지 컬렉션, 프로파일링, 캐시 배치 다섯 가지라고 꽤 설명할 수 있다","심볼 테이블 구축, 스코프 해석, 타입 추론 코드 생성이 시작되기 전에 이 세 가지가 먼저 끝나 있어야 한다.","토큰화, 파싱, 타입 검사","명령어 선택, 레지스터 할당, 명령어 스케줄링이라고 이해해야 한다"],"a":3},{"t":"choice","k":"cmp-gen-reg2","q":"레지스터 할당을 그래프 색칠 문제로 모델링할 때, 간섭 그래프의 간선이 뜻하는 것은?","ex":"간섭 그래프의 정점은 값(가상 레지스터)이고, 생존 구간이 겹쳐 동시에 살아 있는 두 값 사이에 간선을 긋는다. 인접한 정점을 다른 색으로 칠하는 것이 곧 겹치는 값에 서로 다른 레지스터를 주는 것이며, 색의 개수가 물리 레지스터 개수에 해당한다.","o":["두 값이 동시에 살아 있어 같은 레지스터를 쓸 수 없다","두 값이 항상 함께 계산된다","두 값의 타입이 같다","두 값이 같은 함수 안에 선언되어 있다는 자리"],"a":0},{"t":"choice","k":"cmp-gen-reg3","q":"스필(spill)이 발생하는 상황과 그 결과로 옳은 것은?","ex":"동시에 살아 있는 값의 수가 물리 레지스터 수를 넘으면 일부를 스택 메모리로 밀어내야 하고, 이후 사용할 때마다 load/store가 추가된다. 레지스터 접근보다 메모리 접근이 훨씬 느리므로 좋은 할당기는 스필을 최소화하거나 반복 횟수가 적은 곳에서 스필하도록 고른다.","o":["타입 검사가 실패해 오류가 보고된다","물리 레지스터가 부족해 일부 값을 메모리에 저장했다가 다시 읽어 오며, 메모리 접근 비용이 늘어난다고 늘 곰곰이 새겨 두어야 한다","IR이 너무 커서 컴파일이 중단된다","레지스터가 남아돌아 값을 여러 레지스터에 복제해 두며, 그만큼 성능이 향상된다는 뜻이다 값이 여러 곳에 있으면 그중 가까운 것을 골라 읽을 수 있기 때문이다."],"a":1},{"t":"input","k":"cmp-gen-reg4","q":"다음 IR에서 세 값 a, b, c 중 서로 생존 구간이 전혀 겹치지 않아 같은 레지스터를 재사용할 수 있는 값은 총 몇 개의 물리 레지스터로 충분한가? (숫자로)","ex":"각 값은 정의된 직후 한 번 쓰이고 바로 죽으므로 어느 두 값도 동시에 살아 있지 않다. 간섭 그래프에 간선이 하나도 없어 색 하나, 즉 물리 레지스터 하나로 세 값을 모두 처리할 수 있다.","code":"a = 1\nuse(a)      ; 이후 a는 죽음\nb = 2\nuse(b)      ; 이후 b는 죽음\nc = 3\nuse(c)","a":["1"]},{"t":"choice","k":"cmp-gen-reg6","q":"지역 최적화, 전역 최적화, 프로시저 간 최적화의 범위를 올바르게 구분한 것은?","ex":"지역 최적화는 분기가 없는 직선 코드인 기본 블록 안에서만 이루어지고, 전역 최적화는 한 함수의 CFG 전체를 보며 분기와 루프를 가로지른다. 프로시저 간 최적화는 여러 함수를 함께 보므로 인라이닝처럼 호출 경계를 넘는 변환이 가능하다.","o":["셋 다 같은 범위를 다르게 부르는 이름일 뿐이다","지역: 런타임 / 전역: 컴파일 타임 / 프로시저 간: 링크 타임에만 존재하는 것으로 나뉜다 세 가지가 서로 다른 시점에 일어나므로 범위가 아니라 시점으로 나눈다.","지역: 기본 블록 내 / 전역: 함수 내 제어 흐름 그래프 전체 / 프로시저 간: 함수 경계를 넘어","지역: 한 줄 안 / 전역: 파일 하나 전체 / 프로시저 간: 프로젝트 전체의 주석까지 빠짐없이 모두 포함해서 본다"],"a":2},{"t":"choice","k":"cmp-gen-reg5","q":"명령어 스케줄링의 목적으로 가장 적절한 것은?","ex":"메모리 로드처럼 결과가 늦게 나오는 명령 뒤에 그 결과를 바로 쓰는 명령이 오면 CPU가 멈춰 기다린다. 스케줄러는 그 사이에 독립적인 명령을 끼워 넣어 대기 시간을 메우며, 물론 데이터 의존 관계를 어기지 않는 범위에서만 순서를 바꾼다.","o":["레지스터를 모두 스필시켜 메모리만 쓰도록 만드는 것 메모리는 레지스터보다 넉넉하므로 순서를 맞추기가 쉬워진다고 지금 다루는 맥락에서는 실제로 짚어 두어야 한다","소스 코드에 적힌 줄 순서를 실행할 때도 그대로 유지하도록 아주 끝까지 강제하는 것을 뜻한다고 이 단원에서는 실제로 그대로 짚어 두어야 한다","명령어 개수를 절반 수준으로 줄여서 실행 시간을 그만큼 짧게 만드는 것을 뜻한다고 기본이 되는 내용이라 실제로 그대로 할 수 있다","파이프라인 지연이나 메모리 대기 시간을 줄이도록 명령 순서를 재배치하는 것이다"],"a":3}],"th":{"sum":"앞단이 만든 AST는 중간 표현(IR)으로 낮아진 뒤 의미를 보존하는 최적화를 거쳐 기계어로 내려간다. 같은 언어라도 인터프리터, AOT 컴파일, JIT 중 어떤 방식으로 실행하느냐에 따라 성능 특성이 달라진다.","body":[{"h":"코드 생성과 레지스터 할당","t":"코드 생성은 크게 명령어 선택, 레지스터 할당, 명령어 스케줄링으로 나뉜다. 명령어 선택은 IR 연산을 대상 CPU의 실제 명령어로 대응시키고, 레지스터 할당은 무제한처럼 다루던 가상 레지스터를 물리 레지스터의 유한한 개수에 밀어 넣는다. 이 문제는 동시에 살아 있는 값끼리 간선을 잇는 간섭 그래프의 그래프 색칠로 모델링되며, 색이 모자라면 일부 값을 메모리로 밀어내는 스필(spill)이 발생해 메모리 접근 비용이 생긴다. 명령어 스케줄링은 파이프라인 지연을 줄이도록 순서를 재배치한다."},{"h":"IR과 최적화","t":"IR은 소스 언어와 대상 기계 사이에 놓인 중간 언어로, 3-주소 코드처럼 단순한 형태를 쓴다. 여러 언어와 여러 CPU를 조합할 때 각 조합마다 컴파일러를 만들지 않아도 되게 해 주고, 최적화 패스가 공유할 공통 기반이 된다. SSA(정적 단일 배정) 형태는 각 변수에 값이 딱 한 번만 배정되도록 만들어 정의-사용 관계를 명확히 하고 데이터 흐름 분석을 쉽게 한다. 최적화는 반드시 관찰 가능한 의미를 보존해야 하며, 상수 접기, 공통 부분식 제거(CSE), 죽은 코드 제거(DCE), 인라이닝, 루프 불변 코드 이동(LICM), 강도 감소가 대표적이다."},{"h":"인터프리터, AOT, JIT","t":"인터프리터는 소스나 바이트코드를 읽어 즉시 실행하므로 시작이 빠르고 디버깅과 반복 개발이 편하지만, 실행 중 해석 오버헤드가 있다. AOT 컴파일은 미리 기계어를 만들어 두어 실행이 빠른 대신 별도의 빌드 단계가 필요하다. 바이트코드 VM은 그 중간 형태다. JIT은 런타임에 자주 실행되는 핫 경로를 찾아 기계어로 컴파일하며, 실제로 흘러온 타입 같은 런타임 정보를 이용한 추측 최적화를 한다. 가정이 깨지면 역최적화(deoptimization)로 인터프리터로 되돌아가며, 컴파일 자체에 드는 워밍업 비용이 있어 짧게 끝나는 프로그램에서는 이득이 적을 수 있다."}],"code":{"c":"원본 IR (3-주소 코드)\n  t1 = 2 * 3\n  t2 = a + t1\n  t3 = a + t1      ; t2와 같은 계산\n  t4 = t2 + t3\n  t5 = 99          ; 아무도 안 씀\n  return t4\n\n상수 접기 -> t1 = 6\nCSE       -> t3 삭제, t3 자리에 t2 사용\nDCE       -> t5 삭제\n\n최적화 후\n  t1 = 6\n  t2 = a + t1\n  t4 = t2 + t2\n  return t4","cap":"상수 접기·CSE·DCE를 차례로 적용해도 반환값의 의미는 그대로다."},"key":["IR은 여러 언어와 여러 대상 CPU를 잇는 공통 기반이고 SSA는 흐름 분석을 돕는다","최적화는 관찰 가능한 의미를 보존하며 더 빠르거나 작은 코드를 만든다","JIT은 런타임 정보를 활용한 추측 최적화와 역최적화를 하며 워밍업 비용이 있다"]}},{"t":"인터프리터 vs 컴파일 vs JIT","q":[{"t":"input","k":"cmp-run-jit5","q":"JIT이 핫 경로를 식별하고 컴파일하기까지 최고 성능에 도달하지 못하는 초기 구간을 가리키는 용어는? (한국어로, 예: OO 비용/시간의 앞 두 글자)","ex":"실행 초반에는 아직 프로파일 정보가 부족하고 컴파일도 끝나지 않아 인터프리터 속도로 동작하는데, 이 구간을 워밍업이라 한다. 그래서 짧게 끝나는 프로그램은 JIT의 이득을 충분히 누리지 못하고, 벤치마크에서도 워밍업 구간을 제외하고 측정하는 것이 일반적이다.","a":["워밍업"]},{"t":"choice","k":"cmp-run-jit1","q":"인터프리터 방식의 특징으로 옳은 것은?","ex":"인터프리터는 별도의 빌드 단계 없이 바로 실행하므로 편집-실행 주기가 짧고 오류 지점의 소스 문맥을 유지하기 쉽다. 대신 매 실행마다 해석 비용이 들어 같은 코드를 반복 실행할 때 AOT 컴파일보다 불리하다.","o":["코드를 즉시 실행할 수 있어 시작이 빠르고 반복 개발·디버깅이 편하다","실행하기 전에 기계어로 된 실행 파일을 만들어 두어야 한다","실행 중 해석 오버헤드가 전혀 없다","타입 검사를 컴파일 타임에만 수행한다"],"a":0},{"t":"choice","k":"cmp-run-jit3","q":"JIT 컴파일러의 동작 방식으로 옳은 것은?","ex":"JIT은 실행 중 프로파일링으로 뜨거운 메서드나 루프를 찾아 그 부분만 기계어로 컴파일한다. 이때 \"이 자리에는 항상 정수가 온다\" 같은 런타임 관찰을 가정으로 삼아 AOT가 하기 어려운 공격적인 최적화를 적용한다.","o":["소스 코드를 컴파일하지 않고 문자열 그대로 한 줄씩 해석해 그때그때 실행한다 미리 컴파일해 두는 단계가 없어 시작이 빠른 대신 계속 느리다고 어느 정도는 알아 두어야 한다","프로그램 전체를 실행 전에 기계어로 컴파일해 파일로 저장한다","런타임에 자주 실행되는 핫 경로를 찾아 기계어로 컴파일하고 실제 타입 같은 런타임 정보로 추측 최적화를 한다","타입 검사를 생략해 속도를 얻는다"],"a":2},{"t":"choice","k":"cmp-run-jit4","q":"JIT의 역최적화(deoptimization)가 필요한 이유는?","ex":"JIT은 관찰된 타입 등을 가정하고 검사 코드를 붙인 채 최적화하는데, 예상 밖의 타입이 들어오면 그 가정이 깨진다. 이때 최적화된 코드를 버리고 인터프리터나 덜 최적화된 버전으로 실행 상태를 옮겨야 정확성이 유지된다.","o":["레지스터가 부족해질 때 코드를 삭제해야 하기 때문","가비지 컬렉션이 실패했을 때 메모리를 원래 상태로 되돌리기 위해서 필요하다 메모리가 부족해지면 컴파일된 코드부터 버려야 하기 때문이라고 분명히 차근차근 설명할 수 있다","소스 코드의 문법 오류를 실행 중 고치기 위해서","추측 최적화가 세운 가정이 실행 중 깨질 수 있어 안전한 인터프리터 실행으로 되돌아가야 하기 때문이라고 대체로 그대로 말할 수 있다"],"a":3},{"t":"choice","k":"cmp-run-jit2","q":"\"인터프리터는 항상 컴파일러보다 느리다\"는 서술이 부정확한 이유는?","ex":"정상 상태의 실행 속도는 보통 AOT 컴파일된 코드가 빠르지만, 스크립트를 한 번 실행하는 것 같은 상황에서는 빌드 시간이 그 이득을 지운다. 전체 소요 시간이라는 관점에서 보면 어느 쪽이 유리한지는 워크로드에 따라 달라진다.","o":["짧게 끝나는 프로그램에서는 컴파일에 드는 시간까지 합치면 인터프리터가 전체적으로 더 빠를 수 있기 때문이다","인터프리터는 중간 단계 없이 기계어를 직접 실행하므로 어떤 경우에도 결국 훨씬 더 빠르기 때문이라고 기본이 되는 내용이라 늘 무리 없이 볼 수 있다","컴파일러는 실행을 하지 않아 비교 대상이 아니기 때문","인터프리터와 컴파일러는 같은 프로그램에 대해 어떤 경우에도 같은 성능을 내기 때문 실행하는 방식만 다를 뿐 결국 같은 계산을 같은 횟수만큼 하기 때문이라고 한 번 더 짚어 두어야 한다"],"a":0},{"t":"choice","k":"cmp-run-jit6","q":"바이트코드 VM 방식(예: 소스를 바이트코드로 컴파일한 뒤 VM이 실행)의 위치로 가장 적절한 설명은?","ex":"바이트코드 VM은 소스를 한 번만 파싱해 조밀한 명령 형태로 바꿔 두므로 매번 소스를 해석하는 것보다 빠르고, 기계어에 종속되지 않아 이식성이 좋다. 여기에 JIT을 얹어 뜨거운 바이트코드만 기계어로 승격시키는 구조가 현대 런타임에서 흔하다.","o":["AOT 기계어 컴파일과 완전히 동일한이라고 되어 있다","미리 한 번 컴파일해 파싱 비용을 없애되 실행은 VM이 담당하는 중간이라고 곰곰이 알아 두어야 한다","소스를 한 줄씩 다시 파싱하며 실행하므로 순수 인터프리터보다 더 느리다","타입 검사를 수행하지 않는다는 점에서 다른 방식과 구분된다"],"a":1}],"th":{"sum":"앞단이 만든 AST는 중간 표현(IR)으로 낮아진 뒤 의미를 보존하는 최적화를 거쳐 기계어로 내려간다. 같은 언어라도 인터프리터, AOT 컴파일, JIT 중 어떤 방식으로 실행하느냐에 따라 성능 특성이 달라진다.","body":[{"h":"IR과 최적화","t":"IR은 소스 언어와 대상 기계 사이에 놓인 중간 언어로, 3-주소 코드처럼 단순한 형태를 쓴다. 여러 언어와 여러 CPU를 조합할 때 각 조합마다 컴파일러를 만들지 않아도 되게 해 주고, 최적화 패스가 공유할 공통 기반이 된다. SSA(정적 단일 배정) 형태는 각 변수에 값이 딱 한 번만 배정되도록 만들어 정의-사용 관계를 명확히 하고 데이터 흐름 분석을 쉽게 한다. 최적화는 반드시 관찰 가능한 의미를 보존해야 하며, 상수 접기, 공통 부분식 제거(CSE), 죽은 코드 제거(DCE), 인라이닝, 루프 불변 코드 이동(LICM), 강도 감소가 대표적이다."},{"h":"코드 생성과 레지스터 할당","t":"코드 생성은 크게 명령어 선택, 레지스터 할당, 명령어 스케줄링으로 나뉜다. 명령어 선택은 IR 연산을 대상 CPU의 실제 명령어로 대응시키고, 레지스터 할당은 무제한처럼 다루던 가상 레지스터를 물리 레지스터의 유한한 개수에 밀어 넣는다. 이 문제는 동시에 살아 있는 값끼리 간선을 잇는 간섭 그래프의 그래프 색칠로 모델링되며, 색이 모자라면 일부 값을 메모리로 밀어내는 스필(spill)이 발생해 메모리 접근 비용이 생긴다. 명령어 스케줄링은 파이프라인 지연을 줄이도록 순서를 재배치한다."},{"h":"인터프리터, AOT, JIT","t":"인터프리터는 소스나 바이트코드를 읽어 즉시 실행하므로 시작이 빠르고 디버깅과 반복 개발이 편하지만, 실행 중 해석 오버헤드가 있다. AOT 컴파일은 미리 기계어를 만들어 두어 실행이 빠른 대신 별도의 빌드 단계가 필요하다. 바이트코드 VM은 그 중간 형태다. JIT은 런타임에 자주 실행되는 핫 경로를 찾아 기계어로 컴파일하며, 실제로 흘러온 타입 같은 런타임 정보를 이용한 추측 최적화를 한다. 가정이 깨지면 역최적화(deoptimization)로 인터프리터로 되돌아가며, 컴파일 자체에 드는 워밍업 비용이 있어 짧게 끝나는 프로그램에서는 이득이 적을 수 있다."}],"code":{"c":"원본 IR (3-주소 코드)\n  t1 = 2 * 3\n  t2 = a + t1\n  t3 = a + t1      ; t2와 같은 계산\n  t4 = t2 + t3\n  t5 = 99          ; 아무도 안 씀\n  return t4\n\n상수 접기 -> t1 = 6\nCSE       -> t3 삭제, t3 자리에 t2 사용\nDCE       -> t5 삭제\n\n최적화 후\n  t1 = 6\n  t2 = a + t1\n  t4 = t2 + t2\n  return t4","cap":"상수 접기·CSE·DCE를 차례로 적용해도 반환값의 의미는 그대로다."},"key":["IR은 여러 언어와 여러 대상 CPU를 잇는 공통 기반이고 SSA는 흐름 분석을 돕는다","최적화는 관찰 가능한 의미를 보존하며 더 빠르거나 작은 코드를 만든다","JIT은 런타임 정보를 활용한 추측 최적화와 역최적화를 하며 워밍업 비용이 있다"]}}],"ord":4},{"t":"컴파일 다음에 오는 것 — 링크와 빌드","g":"","l":[{"t":"링크와 빌드 I","q":[{"t":"choice","k":"undefined reference","cat":"debug","q":"각 파일은 <code>gcc -c</code> 로 문제없이 컴파일되는데, 마지막에 합칠 때만 <code>undefined reference to 'add'</code> 가 난다. 무슨 뜻인가?","code":"// math.h\nint add(int, int);        // 선언만 있음\n// main.c 는 add() 를 부른다\n// add() 의 몸통은 어디에도 없다","o":["add 의 몸통(정의)이 링크 대상 어디에도 없다.","함수 이름의 철자가 헤더와 서로 다르므로 컴파일러가 경고를 내 준이라고 꽤 그대로 짚어 두어야 한다","헤더를 포함하지 않아 컴파일이 실패한이라고 본다","함수가 static 으로 선언돼 최적화 단계에서 제거되어 버린이라고 본다"],"a":0,"ex":"컴파일러는 '있다고 했으니 있겠지' 하고 넘어가고, 링커가 진짜로 찾는다.\n개념: 선언은 '이런 이름과 모양의 것이 어딘가 있다' 는 약속이고, 정의는 실제 몸통이다. 컴파일 단계는 선언만 보면 통과하므로, 몸통이 없다는 사실은 링크에서야 드러난다.\n실무: 오류 메시지에 나온 심볼을 정의한 파일이 빌드 대상에 있는지, 라이브러리라면 -l 로 넣었는지 확인한다. 정의는 있는데도 안 보인다면 이름 맹글링이나 링크 순서를 의심한다.\n왜 그 답인가: 그 정의를 담은 <code>.o</code> 나 라이브러리를 링크에 포함해야 한다"},{"t":"choice","k":"multiple definition","cat":"debug","q":"헤더에 짧은 함수를 넣어 두었더니 파일이 늘어난 뒤부터 <code>multiple definition of 'clamp'</code> 로 링크가 깨진다. 원인과 해결은?","code":"// util.h\nint clamp(int v){ return v < 0 ? 0 : v; }   // 정의가 헤더에 있다","o":["헤더 가드가 없어서 같은 파일 안에서 두 번 포함된 것이므로 <code>#pragma once</code> 를 넣으면 해결된다","텍스트 복사라 포함한 파일 수만큼 정의가 생김","링크 순서가 잘못돼 같은 오브젝트가 두 번 들어간이라고 보면 된다","함수가 너무 짧아 컴파일러가 인라인하면서 심볼을 중복 생성한이라고 봐도 된다"],"a":1,"ex":"헤더 가드는 '한 파일 안에서 두 번' 을 막을 뿐, '여러 파일에 하나씩' 은 못 막는다.\n개념: 헤더 가드는 같은 번역 단위 안의 중복 포함만 방지한다. a.c 와 b.c 가 각각 그 헤더를 포함하면 정의가 두 벌 만들어지고, 링커가 둘을 만나 충돌한다.\n실무: 헤더에는 선언만 둔다. 굳이 헤더에 몸통을 두려면 inline(C++ 에서는 여러 정의를 허용) 이나 static(파일마다 별도 사본) 을 쓴다. 상수도 마찬가지라 C++ 에서는 constexpr·inline 변수를 쓴다.\n왜 그 답인가: 헤더에는 선언만 두거나 <code>static</code>·<code>inline</code> 으로 만든다"},{"t":"choice","k":"선언과 정의","q":"여러 파일에서 같은 전역 변수를 쓰려고 헤더에 <code>int counter;</code> 라고 적었다. 올바른 방법은?","code":"// config.h\nint counter;          // ← 이게 문제\n// a.c, b.c 가 모두 config.h 를 포함한다","o":["지금 코드가 맞다. 컴파일러가 같은 이름이면 하나로 합쳐 준다","헤더에 static int counter; 를 두면 모든 파일이 같은 값을 그대로 공유하게 된다 파일마다 사본이 생기지만 링커가 그것들을 하나로 합쳐 주기 때문이라고 흔히 말할 수 있다","헤더에는 extern int counter; 로 선언만 두고, 소스 파일 하나에 int counter; 로 정의를 둔다고 흔히 이해해야 한다","헤더에 <code>const int counter;</code> 로 바꾸면 중복이 사라진다"],"a":2,"ex":"전역 변수는 '선언은 여러 번, 정의는 딱 한 번' 이라는 규칙을 따른다.\n개념: extern 은 '이 이름이 다른 곳에 정의돼 있다' 는 선언이라 여러 파일에 있어도 된다. 정의는 실제 저장 공간을 만드는 일이라 프로그램 전체에 하나여야 한다.\n실무: static 을 쓰면 파일마다 별개의 변수가 생겨 '공유' 라는 목적과 정반대가 된다 — 값이 서로 달라지는 버그로 나타난다. 애초에 전역 변수를 줄이고, 필요하면 접근 함수를 통해 노출하는 편이 안전하다."},{"t":"choice","k":"정적 vs 동적","q":"같은 코드를 정적 라이브러리(<code>.a</code>)로 링크할 때와 동적 라이브러리(<code>.so</code>)로 링크할 때의 차이로 옳은 것은?","code":"gcc main.o libutil.a       # 정적\ngcc main.o -L. -lutil      # 동적(libutil.so)","o":["동적 라이브러리는 실행 파일 안에 복사되므로 배포가 간단하고 실행도 빠르다","정적 라이브러리는 실행 시점에 로드되므로 라이브러리만 고치면 재빌드 없이 그대로 반영되고, 동적 라이브러리는 실행 파일에 복사된다 그래서 배포할 때는 정적 쪽이 갱신이 쉽고 크기도 작아진다.","둘은 링크 방식만 다를 뿐 실행 파일 크기와 배포 방식은 같다","정적은 필요한 부분이 실행 파일에 복사돼 배포가 단순한 대신 크고, 동적은 실행 시점에 공유돼 작고 갱신이 쉬운 대신 그 파일이 있어야 한다고 정리되어 있다"],"a":3,"ex":"'언제 합치느냐' 하나가 배포·크기·갱신을 전부 바꾼다.\n개념: 정적 링크는 빌드 시점에 필요한 오브젝트를 실행 파일에 붙인다. 동적 링크는 이름만 적어 두고 실행할 때 로더가 찾아 붙인다.\n실무: 컨테이너처럼 환경을 통째로 배포한다면 정적 링크가 사고를 줄인다(라이브러리 없음 오류가 사라진다). 여러 프로그램이 같은 라이브러리를 쓰고 보안 패치를 빨리 반영해야 한다면 동적이 낫다."}],"th":{"sum":"컴파일이 끝나도 프로그램은 아직 없습니다. 파일마다 따로 번역된 조각들을 <b>하나로 잇는 일</b>(링크)이 남아 있고, 실무에서 헤매는 시간의 상당 부분이 여기에서 나옵니다.","body":[{"h":"컴파일은 파일 하나씩, 링크는 전부 모아서","t":"컴파일러는 소스 파일을 <b>하나씩 따로</b> 번역합니다. 그래서 <code>add()</code> 를 부르는 파일은 '그런 함수가 있다' 는 <b>선언</b>만 보면 통과하고, <b>실제 몸통이 어디 있는지</b>는 신경 쓰지 않아요. 그 몸통을 찾아 주소를 채워 넣는 것이 링커의 일이고, 못 찾으면 그제서야 <code>undefined reference</code> 가 납니다 — <b>컴파일은 성공했는데 링크에서 실패하는</b> 오류가 이렇게 생깁니다."},{"h":"헤더는 복사·붙여넣기다","t":"<code>#include</code> 는 그 파일의 내용을 <b>글자 그대로 그 자리에 붙여 넣는</b> 것뿐입니다. 그래서 헤더에 함수 <b>정의</b>를 두면 그 헤더를 포함한 파일 수만큼 같은 함수가 생겨 <code>multiple definition</code> 이 나고, 헤더 하나를 고치면 <b>그것을 포함한 모든 파일이 다시 컴파일</b>됩니다. 빌드가 느린 이유의 대부분이 여기 있습니다."},{"h":"빌드는 '무엇이 바뀌었나' 를 판단하는 문제다","t":"증분 빌드는 <b>의존성 그래프</b>를 따라 바뀐 것만 다시 만듭니다. 그런데 판단 근거가 <b>파일 수정 시각</b>이면, 내용이 같은데 시각만 바뀌어도 전부 다시 만들고 반대로 시각이 뒤죽박죽인 환경에서는 <b>바뀐 것을 건너뜁니다</b>. 요즘 빌드 도구가 <b>내용 해시</b>로 옮겨 간 이유이고, 그래야 캐시를 여러 사람이 나눠 쓸 수 있습니다."}],"code":{"t":"네 단계를 눈으로","c":"main.c ─전처리→ main.i ─컴파일→ main.s ─어셈블→ main.o ┐\n                                                        ├─링크→ 실행 파일\nutil.c ─────────────────────────────────→ util.o ┘\n\n$ gcc -c main.c      # 여기까지는 파일 하나씩\n$ gcc main.o util.o  # 여기서 처음 서로를 본다","cap":"오류가 어느 화살표에서 났는지가 곧 원인이다"},"key":["컴파일 오류와 링크 오류는 원인이 완전히 다르다","#include 는 텍스트 복사 — 헤더에는 선언만 둔다","라이브러리는 링크 순서와 실행 시점 탐색 경로가 따로 있다","증분 빌드는 의존성 그래프와 '바뀜' 을 판단하는 방식이 좌우한다"]}},{"t":"링크와 빌드 II","q":[{"t":"choice","k":"링크 순서","cat":"debug","q":"라이브러리를 분명히 넣었는데도 <code>undefined reference</code> 가 난다. 순서만 바꿨더니 해결됐다. 왜 그런가?","code":"gcc -lutil main.o     # 실패\ngcc main.o -lutil     # 성공","o":["전통적인 링커는 왼쪽에서 오른쪽으로 훑으며 그 시점에 아직 못 찾은 심볼만 라이브러리에서 꺼낸다. 라이브러리가 먼저 오면 필요한 심볼이 아직 없어 아무것도 꺼내지 않는다","오브젝트 파일과 라이브러리를 섞어서 넘기면 링커가 처리 순서를 임의로 정하기 때문이며, 순서를 바꾸면 우연히 맞아떨어진 것이다 그래서 어느 순서로 적든 결과가 같아야 하는데 우연히 달라진 것이다.","-l 옵션은 마지막에 와야 한다는 문법 규칙 때문이다","앞에 온 라이브러리는 최적화 단계에서 제거되기 때문이다"],"a":0,"ex":"링커는 한 번 훑고 지나가며, 뒤돌아보지 않는다.\n개념: 정적 라이브러리는 오브젝트의 묶음이고, 링커는 '지금까지 모인 미해결 심볼' 을 채울 수 있는 멤버만 꺼낸다. 라이브러리를 먼저 만나면 미해결 심볼이 없으니 그냥 지나친다.\n실무: 규칙은 '쓰는 쪽을 왼쪽, 제공하는 쪽을 오른쪽'. 서로 참조하는 라이브러리는 두 번 적거나 --start-group/--end-group 으로 감싼다. 빌드 도구가 대신해 주는 경우가 많아 직접 링크할 때만 드러난다."},{"t":"choice","k":"이름 맹글링","cat":"debug","q":"C++ 프로젝트에서 C 라이브러리 함수를 부르는데 링크가 안 된다. 헤더도 포함했고 라이브러리도 넣었다. 원인은?","code":"// C 로 컴파일된 libfoo: 심볼 이름 = foo\n// C++ 에서 참조하는 이름  = _Z3fooi","o":["라이브러리를 <code>-static</code> 으로 링크하면 이름 문제가 사라진다","C++ 은 오버로딩 때문에 인자 타입을 이름에 섞어 넣는다(맹글링). 헤더를 extern \"C\" 로 감싸 C 이름 규칙을 쓰게 한다","C 라이브러리는 C++ 에서 그대로 쓸 수 없으므로 래퍼를 C++ 로 다시 작성해 감싸 주어야 한다 헤더를 포함해도 C++ 컴파일러가 그 선언을 인식하지 못하기 때문이다.","C++ 컴파일러가 <code>-std</code> 를 낮춰야 C 심볼을 인식한다"],"a":1,"ex":"같은 함수인데 컴파일러가 부르는 이름이 다르다.\n개념: C++ 은 같은 이름의 함수를 인자 타입으로 구분해야 해서 심볼 이름에 타입 정보를 인코딩한다. C 는 이름을 거의 그대로 쓴다. 그래서 서로의 심볼을 못 찾는다.\n실무: C 헤더는 보통 <code>#ifdef __cplusplus / extern \"C\" { ... }</code> 로 스스로를 감싸 둔다. 그렇지 않은 헤더는 포함할 때 감싸 준다. nm 이나 objdump 로 실제 심볼 이름을 보면 원인이 바로 드러난다."},{"t":"choice","k":"실행 시점 탐색","cat":"debug","q":"빌드는 성공하는데 실행하면 <code>error while loading shared libraries: libutil.so.1</code> 로 죽는다. 링크할 때는 있었던 파일이다. 무엇이 다른가?","code":"gcc main.o -L/opt/build/lib -lutil   # 링크 성공\n./app                                # 실행 실패","o":["동적 라이브러리는 실행 파일과 같은 디렉터리에 있어야 하므로 그리로 복사해 두면 된다고 차근차근 이해할 수 있다","라이브러리 버전 번호가 붙은 파일은 링크할 수 없으므로 심볼릭 링크를 따로 하나 만들어 두어야 한다고 대체로 차근차근 알아 두어야 한다","링크 시점의 탐색 경로(<code>-L</code>)와 실행 시점의 탐색 경로는 별개다.","실행 파일에 실행 권한이 없어 로더가 라이브러리를 찾지 못하게 된이라고 곰곰이 할 수 있다"],"a":2,"ex":"링커가 찾은 경로는 실행할 때 아무도 기억해 주지 않는다.\n개념: -L 은 빌드할 때만 쓰이고, 실행할 때는 동적 로더가 rpath·LD_LIBRARY_PATH·ldconfig 캐시·표준 경로 순으로 다시 찾는다. 두 경로가 다르면 이런 상황이 된다.\n실무: ldd 로 어떤 라이브러리를 어디서 찾는지 확인한다. 배포에는 -Wl,-rpath 로 경로를 실행 파일에 박거나, 아예 정적 링크나 컨테이너로 환경을 고정하는 편이 안정적이다.\n왜 그 답인가: rpath 를 넣거나 라이브러리를 표준 경로에 두거나 <code>LD_LIBRARY_PATH</code> 로 알려 줘야 한다"},{"t":"choice","k":"ABI 깨짐","cat":"debug","q":"구조체에 필드를 하나 추가하고 <b>라이브러리만</b> 다시 빌드해 교체했더니, 애플리케이션이 엉뚱한 값을 읽거나 죽는다. 원인은?","code":"// 이전: struct Cfg { int a; int b; };\n// 이후: struct Cfg { int a; int x; int b; };   // 가운데 삽입","o":["구조체 크기가 커져 메모리가 부족해진이라고 되어 있다","라이브러리의 버전 번호를 올리지 않아 로더가 옛 파일을 그대로 쓴 것이므로 번호만 올리면 된다 구조체 배치 자체는 컴파일러가 실행 시점에 다시 계산해 맞춰 준다고 늘 차근차근 이해할 수 있다","구조체는 이름으로 접근하므로 필드 순서는 영향이 없다","필드를 가운데 넣어 b 의 위치(오프셋)가 밀렸는데, 애플리케이션은 옛 배치를 그대로 박아 둔 채 실행된다. 양쪽을 함께 다시 빌드해야 한다"],"a":3,"ex":"컴파일된 코드에는 필드 이름이 아니라 '몇 번째 바이트' 가 박혀 있다.\n개념: 컴파일러는 cfg->b 를 '시작 주소 + 4바이트' 같은 상수 오프셋으로 바꾼다. 라이브러리 쪽 배치가 바뀌어도 이미 컴파일된 애플리케이션은 옛 오프셋을 그대로 쓴다 — 이것이 ABI 가 깨진다는 뜻이다.\n실무: 공개 구조체는 필드를 <b>끝에만</b> 추가하고, 크기가 바뀌면 소버전이 아니라 메이저 버전을 올린다. 아예 구조체를 감추고(불투명 포인터) 접근 함수만 노출하면 이 문제에서 벗어난다."}],"th":{"sum":"컴파일이 끝나도 프로그램은 아직 없습니다. 파일마다 따로 번역된 조각들을 <b>하나로 잇는 일</b>(링크)이 남아 있고, 실무에서 헤매는 시간의 상당 부분이 여기에서 나옵니다.","body":[{"h":"컴파일은 파일 하나씩, 링크는 전부 모아서","t":"컴파일러는 소스 파일을 <b>하나씩 따로</b> 번역합니다. 그래서 <code>add()</code> 를 부르는 파일은 '그런 함수가 있다' 는 <b>선언</b>만 보면 통과하고, <b>실제 몸통이 어디 있는지</b>는 신경 쓰지 않아요. 그 몸통을 찾아 주소를 채워 넣는 것이 링커의 일이고, 못 찾으면 그제서야 <code>undefined reference</code> 가 납니다 — <b>컴파일은 성공했는데 링크에서 실패하는</b> 오류가 이렇게 생깁니다."},{"h":"헤더는 복사·붙여넣기다","t":"<code>#include</code> 는 그 파일의 내용을 <b>글자 그대로 그 자리에 붙여 넣는</b> 것뿐입니다. 그래서 헤더에 함수 <b>정의</b>를 두면 그 헤더를 포함한 파일 수만큼 같은 함수가 생겨 <code>multiple definition</code> 이 나고, 헤더 하나를 고치면 <b>그것을 포함한 모든 파일이 다시 컴파일</b>됩니다. 빌드가 느린 이유의 대부분이 여기 있습니다."},{"h":"빌드는 '무엇이 바뀌었나' 를 판단하는 문제다","t":"증분 빌드는 <b>의존성 그래프</b>를 따라 바뀐 것만 다시 만듭니다. 그런데 판단 근거가 <b>파일 수정 시각</b>이면, 내용이 같은데 시각만 바뀌어도 전부 다시 만들고 반대로 시각이 뒤죽박죽인 환경에서는 <b>바뀐 것을 건너뜁니다</b>. 요즘 빌드 도구가 <b>내용 해시</b>로 옮겨 간 이유이고, 그래야 캐시를 여러 사람이 나눠 쓸 수 있습니다."}],"code":{"t":"네 단계를 눈으로","c":"main.c ─전처리→ main.i ─컴파일→ main.s ─어셈블→ main.o ┐\n                                                        ├─링크→ 실행 파일\nutil.c ─────────────────────────────────→ util.o ┘\n\n$ gcc -c main.c      # 여기까지는 파일 하나씩\n$ gcc main.o util.o  # 여기서 처음 서로를 본다","cap":"오류가 어느 화살표에서 났는지가 곧 원인이다"},"key":["컴파일 오류와 링크 오류는 원인이 완전히 다르다","#include 는 텍스트 복사 — 헤더에는 선언만 둔다","라이브러리는 링크 순서와 실행 시점 탐색 경로가 따로 있다","증분 빌드는 의존성 그래프와 '바뀜' 을 판단하는 방식이 좌우한다"]}},{"t":"링크와 빌드 III","q":[{"t":"choice","k":"헤더 의존성","q":"헤더 파일 하나에 주석 한 줄을 고쳤을 뿐인데 <b>프로젝트 전체가 다시 컴파일</b>된다. 구조적인 원인과 대응은?","code":"// common.h  ← 거의 모든 .c 가 포함한다\n#include \"common.h\"","o":["그 헤더를 포함한 모든 파일이 의존 관계에 있어 함께 무효화된다고 할 수 있다","헤더는 원래 매번 전체 재빌드를 유발하므로 피할 방법이 없다","주석은 전처리 단계에서 제거되므로 재빌드가 일어날 리 없고, 다른 원인이 있다고 대체로 볼 수 있다","빌드 도구가 주석 변경을 감지하지 못해 전체 빌드로 넘어간 것이다. 캐시를 지우면 해결된다고 기본이 되는 내용이라 알아 두어야 한다"],"a":0,"ex":"'무엇을 포함했는가' 가 곧 '무엇이 함께 다시 빌드되는가' 다.\n개념: 증분 빌드는 의존성 그래프를 따라간다. 모두가 포함하는 거대 헤더가 있으면 그 그래프가 사실상 전체와 연결돼, 작은 변경도 전체 빌드가 된다.\n실무: 헤더를 역할별로 쪼개고, 타입만 필요하면 전방 선언으로 대체하고, 구현 세부는 소스 파일로 내린다(pimpl). 요즘 도구는 내용 해시로 판단해 '실질적으로 안 바뀐' 헤더는 재빌드를 건너뛰기도 한다.\n왜 그 답인가: 헤더를 잘게 나누고 전방 선언으로 포함을 줄이면 영향 범위가 좁아진다"},{"t":"choice","k":"빌드 캐시","q":"빌드 캐시를 붙였는데 CI 에서는 <b>적중률이 거의 0</b> 이다. 로컬에서는 잘 맞는다. 가장 그럴듯한 원인은?","code":"# CI 는 매번 새 워크스페이스에 체크아웃한다\n/builds/run-1234/src/main.c\n/builds/run-1235/src/main.c","o":["빌드 캐시는 같은 머신에서만 동작하므로 CI 에서는 원래부터 쓸 수가 없는 것이라고 기본이 되는 내용이라 꽤 한 번 더 설명할 수 있다","캐시 키에 절대 경로·타임스탬프처럼 매번 달라지는 값이 섞여 있다고 차근차근 할 수 있다","CI 머신이 로컬보다 훨씬 느려서 캐시 조회가 타임아웃되어 버리기 때문이라고 실무에서는 늘 무리 없이 정리할 수 있다","컴파일러 버전이 CI 와 로컬에서 다르면 캐시는 무효가 되므로 버전을 맞추면 100% 적중한다고 이 단원에서 다루는 범위 안에서는 늘 한 번 더 새겨 두어야 한다"],"a":1,"ex":"캐시는 '같은 입력이면 같은 출력' 이라는 약속 위에서만 동작한다.\n개념: 입력에 경로·시각·머신 이름 같은 것이 섞이면 내용이 같아도 키가 매번 달라진다. 반대로 컴파일러 버전·플래그처럼 결과를 바꾸는 값이 키에서 빠지면 잘못된 결과를 재사용하게 된다.\n실무: 키에는 소스 내용 해시·컴파일러 버전·플래그를 넣고, 경로는 상대화하거나 -ffile-prefix-map 으로 정규화한다. 적중률은 지표로 걸어 두고 떨어지면 원인을 찾는다.\n왜 그 답인가: 내용 해시와 상대 경로만으로 키를 만들어야 한다"},{"t":"choice","k":"링크 타임 최적화","q":"LTO(링크 타임 최적화)를 켜면 무엇이 달라지는가?","code":"gcc -flto -O2 -c a.c b.c\ngcc -flto -O2 a.o b.o -o app","o":["여러 오브젝트를 하나로 합쳐 파일 수를 줄여 주는 기능이라 실행 성능과는 아무 관계가 없다 최적화는 각 파일을 컴파일할 때 이미 전부 끝나 있기 때문이라고 흔히 한 번 더 정리할 수 있다","실행 시점에 프로파일을 보고 최적화하므로 첫 실행이 느려진다","오브젝트에 중간 표현을 남겨 두었다가 링크할 때 파일 경계를 넘어 인라인·데드 코드 제거를 한다. 대신 링크 시간과 메모리가 크게 는다고 봐도 무방하다","링크 속도를 높이려고 최적화를 생략하는 옵션이다"],"a":2,"ex":"파일 하나씩 보던 최적화기의 시야를 프로그램 전체로 넓히는 것이다.\n개념: 보통의 컴파일은 번역 단위 안에서만 최적화하므로 다른 파일의 작은 함수는 인라인할 수 없다. LTO 는 중간 표현을 링크까지 들고 가 그 경계를 없앤다.\n실무: 성능이나 바이너리 크기가 중요한 릴리스 빌드에 켜고, 개발 중에는 링크가 느려져 끄는 것이 보통이다. 최적화 범위가 넓어지는 만큼 미정의 동작에 의존한 코드가 새로 깨질 수 있으니 켠 뒤에는 테스트를 다시 돌린다."},{"t":"choice","k":"데드 코드 제거","q":"정적 라이브러리를 링크했더니 <b>쓰지도 않는 함수들까지</b> 실행 파일에 들어와 크기가 커졌다. 줄이는 방법은?","code":"gcc -ffunction-sections -fdata-sections -c ...\ngcc -Wl,--gc-sections ...","o":["실행 파일을 압축하면 링크 결과 자체가 줄어든다","<code>-O3</code> 로 올리면 컴파일러가 다른 파일의 미사용 함수까지 제거한다","링커는 모든 심볼을 포함하므로 라이브러리를 잘게 쪼개는 수밖에 없다","함수·데이터를 각각 별도 섹션에 두고 링커에게 참조되지 않은 섹션을 버리게 한다"],"a":3,"ex":"링커는 '섹션' 단위로 버리므로, 잘게 나눠 둬야 버릴 수 있다.\n개념: 기본 설정에서는 한 오브젝트의 코드가 하나의 섹션에 뭉쳐 있어, 그중 하나만 쓰여도 통째로 들어온다. 함수마다 섹션을 나누면 링커가 참조 그래프를 따라 안 쓰이는 것만 제거할 수 있다.\n실무: 임베디드나 배포 크기가 중요한 곳에서 표준 기법이다. 다만 참조가 겉으로 안 보이는 코드(약한 심볼·인터럽트 벡터·리플렉션 대상)는 KEEP 지시로 지켜 줘야 한다."}],"th":{"sum":"컴파일이 끝나도 프로그램은 아직 없습니다. 파일마다 따로 번역된 조각들을 <b>하나로 잇는 일</b>(링크)이 남아 있고, 실무에서 헤매는 시간의 상당 부분이 여기에서 나옵니다.","body":[{"h":"컴파일은 파일 하나씩, 링크는 전부 모아서","t":"컴파일러는 소스 파일을 <b>하나씩 따로</b> 번역합니다. 그래서 <code>add()</code> 를 부르는 파일은 '그런 함수가 있다' 는 <b>선언</b>만 보면 통과하고, <b>실제 몸통이 어디 있는지</b>는 신경 쓰지 않아요. 그 몸통을 찾아 주소를 채워 넣는 것이 링커의 일이고, 못 찾으면 그제서야 <code>undefined reference</code> 가 납니다 — <b>컴파일은 성공했는데 링크에서 실패하는</b> 오류가 이렇게 생깁니다."},{"h":"헤더는 복사·붙여넣기다","t":"<code>#include</code> 는 그 파일의 내용을 <b>글자 그대로 그 자리에 붙여 넣는</b> 것뿐입니다. 그래서 헤더에 함수 <b>정의</b>를 두면 그 헤더를 포함한 파일 수만큼 같은 함수가 생겨 <code>multiple definition</code> 이 나고, 헤더 하나를 고치면 <b>그것을 포함한 모든 파일이 다시 컴파일</b>됩니다. 빌드가 느린 이유의 대부분이 여기 있습니다."},{"h":"빌드는 '무엇이 바뀌었나' 를 판단하는 문제다","t":"증분 빌드는 <b>의존성 그래프</b>를 따라 바뀐 것만 다시 만듭니다. 그런데 판단 근거가 <b>파일 수정 시각</b>이면, 내용이 같은데 시각만 바뀌어도 전부 다시 만들고 반대로 시각이 뒤죽박죽인 환경에서는 <b>바뀐 것을 건너뜁니다</b>. 요즘 빌드 도구가 <b>내용 해시</b>로 옮겨 간 이유이고, 그래야 캐시를 여러 사람이 나눠 쓸 수 있습니다."}],"code":{"t":"네 단계를 눈으로","c":"main.c ─전처리→ main.i ─컴파일→ main.s ─어셈블→ main.o ┐\n                                                        ├─링크→ 실행 파일\nutil.c ─────────────────────────────────→ util.o ┘\n\n$ gcc -c main.c      # 여기까지는 파일 하나씩\n$ gcc main.o util.o  # 여기서 처음 서로를 본다","cap":"오류가 어느 화살표에서 났는지가 곧 원인이다"},"key":["컴파일 오류와 링크 오류는 원인이 완전히 다르다","#include 는 텍스트 복사 — 헤더에는 선언만 둔다","라이브러리는 링크 순서와 실행 시점 탐색 경로가 따로 있다","증분 빌드는 의존성 그래프와 '바뀜' 을 판단하는 방식이 좌우한다"]}},{"t":"링크와 빌드 IV","q":[{"t":"choice","k":"디버그 심볼","q":"릴리스 바이너리가 200MB 나 된다. 디버그 심볼을 떼면 20MB 가 되는데, 그러면 크래시 스택을 읽을 수 없다. 실무에서 쓰는 방법은?","code":"objcopy --only-keep-debug app app.debug\nstrip --strip-debug app","o":["심볼을 담은 파일을 따로 떼어 보관하고 배포본은 스트립한다.","심볼을 떼면 복원이 불가능하므로 큰 바이너리를 그대로 배포하는 수밖에 없다고 한 걸음 물러나 전체를 훑어보면 비교적 자주 짚어 두어야 한다","릴리스 빌드에서는 최적화 때문에 심볼이 의미가 없으므로 애초에 만들 필요조차 없다고 늘 어렵지 않게 이해할 수 있다","디버그 심볼 대신 로그를 늘리면 같은 정보를 얻을 수 있다"],"a":0,"ex":"심볼은 버리는 것이 아니라 '따로 보관하는' 것이다.\n개념: 디버그 정보는 실행에 필요 없지만 주소를 함수·줄 번호로 되돌리는 데 필요하다. 배포본에서 떼어 내고 빌드 산출물로 보관하면 크기와 디버깅 가능성을 둘 다 얻는다.\n실무: 빌드 ID 로 바이너리와 심볼 파일을 짝지어 저장하고, 크래시 리포터가 그 ID 로 심볼을 찾아 스택을 복원한다. 심볼 파일은 내부에만 두는 것이 보통이다 — 배포하면 역공학이 쉬워진다.\n왜 그 답인가: 크래시 덤프가 오면 저장해 둔 심볼 파일로 스택을 복원한다"},{"t":"choice","k":"재현 가능한 빌드","q":"같은 커밋을 두 번 빌드했는데 <b>바이너리 해시가 다르게</b> 나온다. 공급망 보안을 위해 같게 만들려면 무엇을 없애야 하나?","code":"__DATE__ / __TIME__\n/builds/run-1234/src/main.c   (절대 경로)\n병렬 빌드의 파일 처리 순서","o":["동적 링크 때문이므로 정적 링크로 바꾸면 같아진다고 분명히 한 번 더 짚어 두어야 한다","빌드 시각·절대 경로 같은 환경 값을 고정한다고 보면 된다","해시가 매번 달라지는 것은 정상이므로 서명으로만 검증해야 한다고 본다 같은 소스라도 컴파일러가 매번 다른 코드를 만들어 내기 때문이다.","최적화가 비결정적이므로 -O0 로 낮춘다"],"a":1,"ex":"'같은 소스에서 같은 바이너리' 는 저절로 되지 않는다.\n개념: 타임스탬프, 빌드 경로, 사용자 이름, 병렬 처리 순서, 해시 순서에 의존한 자료구조 같은 것들이 결과에 섞여 들어간다. 그 값들을 고정하거나 정규화해야 재현이 가능해진다.\n실무: SOURCE_DATE_EPOCH 로 시각을 고정하고, -ffile-prefix-map 으로 경로를 정규화하고, 아카이브는 정렬된 순서로 만든다. 재현 가능한 빌드는 '내가 받은 바이너리가 그 소스에서 나왔다' 를 제3자가 검증하게 해 준다."},{"t":"choice","k":"헤더 가드","q":"헤더 가드(<code>#ifndef</code>)와 <code>#pragma once</code> 가 실제로 막아 주는 것은?","code":"// a.h 를 b.h 도 포함하고, main.c 도 직접 포함한다\n#ifndef A_H\n#define A_H\n...\n#endif","o":["여러 소스 파일이 같은 정의를 만들어 내면서 생기는 multiple definition 링크 오류 헤더가 두 번 펼쳐지는 것은 전처리기가 알아서 걸러 주기 때문이다.","빌드 시간이 쓸데없이 늘어나는 것을 막아 준다 — 포함한 횟수만큼 그만큼 같은 컴파일이 반복되기 때문이라고 실무에서는 흔히 있는 그대로 정리할 수 있다","한 소스 파일을 전처리할 때 같은 헤더가 두 번 이상 펼쳐져 타입·구조체가 중복 정의되는 컴파일 오류라고 곰곰이 짚어 두어야 한다","헤더 파일이 순환 참조되는 것을 근본적으로 해결한다"],"a":2,"ex":"가드는 '번역 단위 하나' 안에서만 효력이 있다.\n개념: 한 .c 를 전처리하면 헤더가 여러 경로로 여러 번 딸려 들어올 수 있다. 가드는 두 번째부터를 건너뛰어 같은 타입 정의가 반복되는 것을 막는다. 파일이 달라지면 가드 매크로도 다시 정의되므로 파일 간 중복은 못 막는다.\n실무: #pragma once 는 거의 모든 컴파일러가 지원하고 실수가 적어 널리 쓰인다. 순환 포함은 가드로 '무한 루프' 만 면할 뿐 해결되지 않으니 전방 선언으로 끊어야 한다."},{"t":"choice","k":"순환 포함","cat":"debug","q":"<code>a.h</code> 와 <code>b.h</code> 가 서로를 포함한다. 가드가 있어 무한 루프는 안 나지만 <b>'알 수 없는 타입' 오류</b>가 난다. 올바른 해결은?","code":"// a.h\n#include \"b.h\"\nstruct A { struct B *b; };\n// b.h\n#include \"a.h\"\nstruct B { struct A *a; };","o":["포함 순서를 바꿔서 먼저 포함되는 쪽을 정하면 해결된다고 흔히 짚어 두어야 한다","두 헤더를 하나로 합치는 것이 유일한 방법이라고 여러 자료에서 공통으로 짚는 대목까지 더해서 보면 있는 그대로 새겨 두어야 한다","가드를 #pragma once 로 바꾸면 순환 참조가 그대로 해소된다고 이 단원에서는 실제로 볼 수 있다","전방 선언으로 포함을 없앤다고 충분히 이해할 수 있다"],"a":3,"ex":"포인터를 쓰는 데는 타입의 '이름' 만 있으면 되고, '내용' 은 필요 없다.\n개념: 가드 때문에 두 번째 포함이 건너뛰어지면, 어느 한쪽은 상대 타입의 정의를 못 본 채로 컴파일된다. 그런데 포인터 멤버는 크기가 정해져 있어 전방 선언만으로 충분하다.\n실무: '값으로 담으면 정의가 필요하고, 포인터·참조로 담으면 선언이면 된다' 가 판단 기준이다. 전방 선언으로 포함을 줄이면 순환도 풀리고 빌드 시간도 함께 줄어든다.\n정답에 함께 적혀 있던 표기: <code>struct B;</code>"}],"th":{"sum":"컴파일이 끝나도 프로그램은 아직 없습니다. 파일마다 따로 번역된 조각들을 <b>하나로 잇는 일</b>(링크)이 남아 있고, 실무에서 헤매는 시간의 상당 부분이 여기에서 나옵니다.","body":[{"h":"컴파일은 파일 하나씩, 링크는 전부 모아서","t":"컴파일러는 소스 파일을 <b>하나씩 따로</b> 번역합니다. 그래서 <code>add()</code> 를 부르는 파일은 '그런 함수가 있다' 는 <b>선언</b>만 보면 통과하고, <b>실제 몸통이 어디 있는지</b>는 신경 쓰지 않아요. 그 몸통을 찾아 주소를 채워 넣는 것이 링커의 일이고, 못 찾으면 그제서야 <code>undefined reference</code> 가 납니다 — <b>컴파일은 성공했는데 링크에서 실패하는</b> 오류가 이렇게 생깁니다."},{"h":"헤더는 복사·붙여넣기다","t":"<code>#include</code> 는 그 파일의 내용을 <b>글자 그대로 그 자리에 붙여 넣는</b> 것뿐입니다. 그래서 헤더에 함수 <b>정의</b>를 두면 그 헤더를 포함한 파일 수만큼 같은 함수가 생겨 <code>multiple definition</code> 이 나고, 헤더 하나를 고치면 <b>그것을 포함한 모든 파일이 다시 컴파일</b>됩니다. 빌드가 느린 이유의 대부분이 여기 있습니다."},{"h":"빌드는 '무엇이 바뀌었나' 를 판단하는 문제다","t":"증분 빌드는 <b>의존성 그래프</b>를 따라 바뀐 것만 다시 만듭니다. 그런데 판단 근거가 <b>파일 수정 시각</b>이면, 내용이 같은데 시각만 바뀌어도 전부 다시 만들고 반대로 시각이 뒤죽박죽인 환경에서는 <b>바뀐 것을 건너뜁니다</b>. 요즘 빌드 도구가 <b>내용 해시</b>로 옮겨 간 이유이고, 그래야 캐시를 여러 사람이 나눠 쓸 수 있습니다."}],"code":{"t":"네 단계를 눈으로","c":"main.c ─전처리→ main.i ─컴파일→ main.s ─어셈블→ main.o ┐\n                                                        ├─링크→ 실행 파일\nutil.c ─────────────────────────────────→ util.o ┘\n\n$ gcc -c main.c      # 여기까지는 파일 하나씩\n$ gcc main.o util.o  # 여기서 처음 서로를 본다","cap":"오류가 어느 화살표에서 났는지가 곧 원인이다"},"key":["컴파일 오류와 링크 오류는 원인이 완전히 다르다","#include 는 텍스트 복사 — 헤더에는 선언만 둔다","라이브러리는 링크 순서와 실행 시점 탐색 경로가 따로 있다","증분 빌드는 의존성 그래프와 '바뀜' 을 판단하는 방식이 좌우한다"]}}],"ord":5},{"t":"컴파일러가 말을 거는 법 — 오류 진단과 복구","g":"","l":[{"t":"진단과 복구 I","q":[{"t":"choice","k":"왜 계속 읽나","q":"구문 오류를 하나 만났을 때 컴파일러가 그 자리에서 끝내지 않고 <b>계속 읽어 나가는</b> 이유는?","code":"error: 3번째 줄 — ';' 가 필요합니다\nerror: 9번째 줄 — 'foo' 를 찾을 수 없습니다\nerror: 14번째 줄 — 인자 개수가 맞지 않습니다\n(오류 3개)","o":["한 번 돌릴 때마다 오류를 하나씩만 알려 주면 고치고 다시 돌리기를 오류 개수만큼 반복해야 하기 때문이다. 한 번에 여러 개를 보고하려면 오류 뒤에도 상태를 추스르고 읽어 나가야 한다고 설명할 수 있다","표준이 모든 오류를 한 번에 보고하도록 정해 두었기 때문이다. 컴파일러는 그 규정을 따르는 것뿐이고, 하나만 보고하고 멈추면 표준을 어기는 구현이 된다 오류를 하나만 보고하는 구현은 규격을 따르지 않은 것으로 본다.","뒤쪽 코드를 읽어야 앞쪽 오류의 원인을 알 수 있기 때문이다","오류가 하나뿐인 파일은 드물어서 통계적으로 그 편이 빠르기 때문이다"],"a":0,"ex":"'오류 복구' 라고 부르는 이 동작이 없으면 컴파일러는 쓸 만한 도구가 못 된다.\n개념: 오류를 만나면 파서는 지금 무엇을 읽던 중인지 확신할 수 없게 된다. 그래도 멈추지 않으려면 <b>믿을 만한 자리까지 건너뛰고</b> 다시 시작해야 한다. 세미콜론이나 닫는 중괄호처럼 '여기서부터는 새 문장' 이라고 볼 만한 표시를 찾아 그 뒤부터 다시 읽는 방식이 흔하다.\n실무: 그래서 오류 목록의 <b>첫 번째 것부터</b> 보는 습관이 중요하다. 뒤쪽 오류들은 앞의 오류 때문에 파서가 헷갈려서 생긴 것일 수 있다."},{"t":"choice","k":"하나 고쳤더니 열 개가 사라졌다","cat":"debug","q":"오류 12개가 떴는데 첫 번째 하나만 고쳤더니 나머지가 전부 사라졌다. 무슨 일이 있었던 것인가?","code":"error: 5번째 줄 — 'Config' 를 찾을 수 없습니다   ← 진짜 원인 (import 누락)\nerror: 12번째 줄 — 'Config' 를 찾을 수 없습니다\nerror: 18번째 줄 — 타입이 맞지 않습니다\n… 9개 더","o":["고친 줄이 우연히 뒤쪽 코드도 바꿔 준이라고 본다","뒤의 오류들은 첫 오류가 만들어 낸 연쇄 오류였다.","오류 개수 표시가 부정확한 것이고 실제로는 처음부터 오류가 하나였다고 여러 자료를 놓고 보면 대체로 어렵지 않게 이해할 수 있다","컴파일러가 오류를 중복 보고하는 버그이며 최신 버전에서는 하나만 나오게 된다고 꽤 한 번 더 새겨 두어야 한다"],"a":1,"ex":"오류 12개를 보고 겁먹을 필요가 없는 이유.\n개념: 컴파일러는 모르는 이름을 만나면 그 자리에 '알 수 없는 타입' 을 임시로 놓고 계속 간다. 그 값을 쓰는 코드마다 검사에 실패하니 오류가 번식한다. 좋은 컴파일러는 이런 <b>이미 망가진 타입에서 파생된 오류를 눌러</b> 보고하지 않으려 애쓴다.\n실무: 오류가 쏟아지면 <b>위에서부터 하나만</b> 고치고 다시 돌린다. 아래쪽부터 손대면 사라질 오류를 고치느라 시간을 쓰고, 심하면 멀쩡한 코드를 망가뜨린다.\n왜 그 답인가: 이름 하나를 못 찾으면 그 타입을 쓰는 모든 곳이 함께 무너지므로, 원인 하나를 고치면 딸려 나온 것들도 함께 사라진다"},{"t":"choice","k":"세미콜론 하나에 폭주하는 이유","cat":"internals","q":"닫는 중괄호 하나를 빠뜨렸을 뿐인데 그 아래 모든 함수에서 오류가 난다. 파서 입장에서 무슨 일이 벌어지는가?","code":"fn a() {\n    …\n            ← 여기 } 가 빠졌다\nfn b() { … }\nfn c() { … }","o":["중괄호 개수는 어휘 분석 단계에서 세므로 파서와는 무관한 문제다","들여쓰기를 보고 블록을 판단하므로 들여쓰기만 맞추면 해결된다","파서는 아직 a 안에 있다고 보고 fn b 를 함수 안에 나타난 이상한 것으로 해석한다. 구조 자체가 어긋났으므로 그 뒤 전부가 잘못된 자리에 있는 것으로 보인다고 늘 그대로 알아 두어야 한다","컴파일러가 파일 끝에서만 균형을 검사하므로 마지막 함수에서만 오류가 나야 정상이다. 중간 함수에서 오류가 나는 것은 진단 구현이 덜 다듬어졌다는 뜻이다 중괄호의 짝은 토큰을 세는 일이라 파싱이 다 끝난 뒤에야 알 수 있다."],"a":2,"ex":"'오류 위치' 와 '실수한 위치' 가 크게 어긋나는 대표적인 경우.\n개념: 괄호는 구조를 정하는 표시라서, 하나가 빠지면 그 뒤 코드 전체가 <b>다른 구조로 읽힌다</b>. 컴파일러가 짚어 주는 줄은 '이상하다는 것을 깨달은 자리' 이지 '실수한 자리' 가 아니다.\n실무: 이럴 때는 오류 줄이 아니라 <b>그 위에서 열린 채 안 닫힌 괄호</b>를 찾는다. 편집기의 괄호 짝 표시와 자동 들여쓰기가 가장 빠른 도구다 — 들여쓰기가 갑자기 어긋나는 지점이 대개 범인이다."},{"t":"choice","k":"위치를 들고 다니기","cat":"internals","q":"컴파일러가 '<code>main.rs:3:18</code>' 처럼 줄과 칸을 정확히 짚으려면 무엇이 필요한가?","code":"토큰: { 종류: 문자열리터럴, 값: \"5\", 위치: 파일#1 3행 18열~20열 }","o":["오류가 났을 때 소스를 처음부터 다시 읽어 같은 내용을 찾으면 된다","컴파일러는 위치를 알 수 없어 파일 단위로만 보고할 수 있다","줄 번호는 어휘 분석기가 세고 뒤 단계에서는 필요 없다","토큰과 트리 노드가 값뿐 아니라 원본에서의 위치 범위를 함께 들고 다녀야 한다. 뒤 단계에서 오류를 발견해도 그 위치를 따라 원본 자리로 되돌아갈 수 있다고 차근차근 볼 수 있다"],"a":3,"ex":"타입 오류는 파싱이 한참 끝난 뒤에 발견되는데도 줄과 칸을 짚어 준다 — 위치를 들고 왔기 때문이다.\n개념: 어휘 분석기가 토큰을 만들 때 위치를 붙여 두고, 파서가 트리를 만들 때 그 위치를 노드에 물려준다. 그래서 의미 분석이나 최적화 단계에서 문제를 찾아도 사람이 쓴 자리를 가리킬 수 있다.\n실무: 이 위치를 잃어버리면 진단이 급격히 나빠진다 — 매크로를 펼친 뒤 <b>생성된 코드의 위치</b>를 보고해 버리면 사람은 자기가 쓰지도 않은 줄을 보게 된다. 좋은 구현은 '펼쳐진 자리' 와 '펼치게 만든 자리' 를 함께 보여 준다."}],"th":{"sum":"컴파일러가 하루에 우리에게 가장 많이 하는 일은 <b>번역이 아니라 거절</b>입니다. 그 거절을 어떻게 설명하느냐가 언어의 체감 난이도를 절반쯤 정해요 — 같은 실수라도 어떤 컴파일러는 한 줄로 짚어 주고, 어떤 컴파일러는 서른 줄을 쏟아냅니다.","body":[{"h":"첫 오류에서 멈추면 안 된다","t":"오류 하나를 만날 때마다 컴파일을 끝내 버리면, 고치고 다시 돌리기를 <b>오류 개수만큼 반복</b>해야 합니다. 그래서 컴파일러는 오류를 만나면 <b>어떻게든 상태를 추스르고 계속 읽습니다</b>. 다만 추스르는 방식이 서툴면 있지도 않은 오류를 줄줄이 만들어 내요 — 이 균형이 진단 품질의 핵심입니다."},{"h":"위치를 잃으면 설명할 수 없다","t":"'타입이 안 맞는다' 만으로는 쓸모가 없습니다. <b>어느 파일 몇 번째 줄 몇 번째 칸</b>인지 짚어 줘야 하죠. 그래서 토큰과 트리 노드는 값뿐 아니라 <b>원본에서의 위치</b>를 함께 들고 다닙니다. 매크로나 템플릿을 펼친 뒤에도 이 위치를 잃지 않아야 사람이 쓴 자리로 되돌려 말할 수 있습니다."},{"h":"좋은 메시지는 다음 행동을 알려 준다","t":"쓸모 있는 오류는 네 가지를 담습니다 — <b>무엇이</b> 잘못됐고, <b>어디서</b> 났고, <b>왜</b> 문제이고, <b>무엇을 하면</b> 되는지. 마지막 하나가 빠진 메시지는 정확해도 막막합니다. 요즘 컴파일러들이 '혹시 이걸 쓰려던 건가요?' 라며 고칠 코드를 직접 보여 주는 이유입니다."}],"code":{"t":"같은 실수, 다른 설명","c":"소스           let x: i32 = \"5\";\n\n불친절한 쪽    error: type mismatch\n\n친절한 쪽      error: 타입이 맞지 않습니다\n                 --> main.rs:3:18\n                  |\n                3 |   let x: i32 = \"5\";\n                  |          ---   ^^^ 여기는 &str 입니다\n                  |          |\n                  |          i32 를 기대했습니다\n                  |\n               도움말: 문자열을 숫자로 바꾸려면\n                3 |   let x: i32 = \"5\".parse().unwrap();"},"key":["오류 하나에서 멈추지 않으려면 상태를 추스르고 계속 읽어야 한다","추스르는 방식이 서툴면 없는 오류가 줄줄이 딸려 나온다","토큰과 노드는 값과 함께 원본 위치를 들고 다닌다","좋은 메시지는 무엇·어디서·왜·어떻게를 담는다"]}},{"t":"진단과 복구 II","q":[{"t":"choice","k":"좋은 메시지의 네 가지","cat":"design","q":"<code>error: type mismatch</code> 라는 메시지가 정확한데도 쓸모가 적은 이유는?","code":"error: type mismatch","o":["무엇이 잘못됐는지만 있고 어디서·왜·무엇을 할지가 없다.","영어로 되어 있어 읽기 어렵기 때문이다","메시지가 짧아서 컴파일러가 그만큼 대충 검사하고 넘어갔다는 뜻이기 때문이다","'type mismatch' 는 부정확한 표현이고 'type error' 가 맞기 때문이다"],"a":0,"ex":"진단 품질을 이야기할 때 기준이 되는 네 가지.\n개념: 무엇이(기대한 타입과 실제 타입), 어디서(파일·줄·칸), 왜(그 자리에 왜 그 타입이 필요한지), 무엇을 하면(고칠 방법). 앞의 셋은 컴파일러가 이미 아는 정보이고, 마지막 하나가 진짜 차이를 만든다.\n실무: 직접 도구를 만들 때도 같다 — 검증 실패나 설정 오류를 보고할 때 '무엇이 틀렸다' 로 끝내지 말고 <b>고친 모습을 보여 준다</b>. 사용자가 문서를 뒤지지 않아도 되게 하는 것이 목표다.\n왜 그 답인가: 특히 다음 행동을 알려 주지 않으면 사람은 정확한 메시지를 앞에 두고도 막힌다"},{"t":"choice","k":"혹시 이걸 쓰려던 건가요","cat":"internals","q":"<code>lenght</code> 라고 잘못 쓰면 컴파일러가 '혹시 <code>length</code> 인가요?' 라고 제안한다. 어떻게 후보를 찾는가?","code":"error: 'lenght' 를 찾을 수 없습니다\n도움말: 'length' 를 쓰려던 것인가요?","o":["이름 사전을 내장하고 있어 사전에 있는 단어만 제안한다","스코프 안의 이름들과 <b>철자가 얼마나 다른지를 거리로 재어</b> 가장 가까운 것을 고른다. 한두 글자 차이처럼 충분히 가까울 때만 제안하고, 멀면 아무 말도 하지 않는다","실행해 보고 성공하는 이름을 찾아 제안한다","과거에 다른 사용자들이 고친 기록을 모아 통계로 제안해 준다. 자주 함께 고쳐진 짝을 표로 들고 있다가 같은 오타가 나오면 그 짝을 보여 주는 식이다 그래서 처음 보는 오타에는 아무 제안도 하지 못한다."],"a":1,"ex":"간단한 문자열 거리 계산 하나가 체감을 크게 바꾼다.\n개념: 두 문자열을 같게 만들려면 글자를 몇 번 넣고 빼고 바꿔야 하는지를 세는 방식이 흔하다. 그 수가 작을수록 오타일 가능성이 높다. 후보는 <b>지금 이 자리에서 보이는 이름</b>으로 한정해야 엉뚱한 제안이 줄어든다.\n실무: 제안이 틀리면 오히려 방해가 되므로 <b>기준을 넉넉히 잡지 않는 것</b>이 중요하다. 이름 길이에 비례해 허용 거리를 정하고, 후보가 여럿이면 여러 개를 나열하거나 아예 제안하지 않는 구현이 많다."},{"t":"choice","k":"경고와 오류 사이","cat":"design","q":"쓰지 않는 변수는 <b>오류가 아니라 경고</b>다. 이 경계는 무엇을 기준으로 정하는가?","code":"warning: 변수 'tmp' 를 쓰지 않았습니다\nerror:   'Config' 를 찾을 수 없습니다","o":["표준에 적힌 것은 오류, 컴파일러가 덧붙인 것은 경고 연산자라고 설명할 수 있다","실행 중에 문제가 되는 것은 경고, 컴파일 중에 문제가 되는 것은 오류라고 한 번 더 볼 수 있다","그 코드에 정해진 의미가 있느냐가 기준이라고 흔히 짚어 두어야 한다","고치기 쉬우면 경고, 어려우면 오류다"],"a":2,"ex":"'번역할 수 있는가' 와 '좋은 코드인가' 는 다른 질문이다.\n개념: 컴파일러의 본업은 의미가 정해진 프로그램을 번역하는 것이다. 의미가 정해지지 않으면 더 갈 수 없으니 오류다. 반면 '의미는 분명한데 실수처럼 보이는 것' 은 번역은 되므로 경고로 알린다.\n실무: 경고를 방치하면 진짜 경고가 묻히므로, 프로젝트를 시작할 때 <b>경고를 오류로 승격</b>해 두는 팀이 많다. 다만 컴파일러를 올릴 때 새 경고가 생겨 빌드가 깨질 수 있으니, 승격은 켜되 새 경고는 따로 유예하는 식으로 운영한다.\n왜 그 답인가: 안 쓰는 변수는 의미가 분명하니 번역할 수 있어 경고로 두고, 없는 이름은 무엇으로 번역할지 정할 수 없으니 오류다"},{"t":"choice","k":"오류에 번호를 붙이는 이유","cat":"ops","q":"일부 컴파일러는 <code>error[E0308]</code> 처럼 오류마다 번호를 붙인다. 무엇을 위한 것인가?","code":"error[E0308]: mismatched types\n  자세한 설명: rustc --explain E0308","o":["번역된 메시지를 쓰지 못하게 막기 위한 장치다","번호가 작을수록 심각한 오류라는 순위를 나타낸다","컴파일러 내부에서 오류를 처리하는 순서를 정하기 위한이라고 보면 된다","메시지 문구가 판마다 바뀌어도 번호는 그대로라, 긴 설명 문서와 이어 붙이고 검색·통계·억제 규칙의 기준으로 삼을 수 있다"],"a":3,"ex":"문구는 사람을 위한 것이고 번호는 도구를 위한 것이다.\n개념: 메시지 문구는 더 친절하게 바꾸려고 자주 손본다. 그런데 문구로 검색하거나 규칙을 걸어 두면 판이 바뀔 때마다 깨진다. 번호는 안정된 식별자 역할을 해서, 긴 해설 문서·자주 겪는 오류 통계·특정 경고만 끄는 설정을 모두 그 위에 올릴 수 있다.\n실무: 팀에서 자주 걸리는 오류 번호를 세어 보면 <b>어떤 개념이 부족한지</b>가 드러난다. 사내 문서를 그 번호에 맞춰 정리해 두면 새로 온 사람이 훨씬 빨리 적응한다."}],"th":{"sum":"컴파일러가 하루에 우리에게 가장 많이 하는 일은 <b>번역이 아니라 거절</b>입니다. 그 거절을 어떻게 설명하느냐가 언어의 체감 난이도를 절반쯤 정해요 — 같은 실수라도 어떤 컴파일러는 한 줄로 짚어 주고, 어떤 컴파일러는 서른 줄을 쏟아냅니다.","body":[{"h":"첫 오류에서 멈추면 안 된다","t":"오류 하나를 만날 때마다 컴파일을 끝내 버리면, 고치고 다시 돌리기를 <b>오류 개수만큼 반복</b>해야 합니다. 그래서 컴파일러는 오류를 만나면 <b>어떻게든 상태를 추스르고 계속 읽습니다</b>. 다만 추스르는 방식이 서툴면 있지도 않은 오류를 줄줄이 만들어 내요 — 이 균형이 진단 품질의 핵심입니다."},{"h":"위치를 잃으면 설명할 수 없다","t":"'타입이 안 맞는다' 만으로는 쓸모가 없습니다. <b>어느 파일 몇 번째 줄 몇 번째 칸</b>인지 짚어 줘야 하죠. 그래서 토큰과 트리 노드는 값뿐 아니라 <b>원본에서의 위치</b>를 함께 들고 다닙니다. 매크로나 템플릿을 펼친 뒤에도 이 위치를 잃지 않아야 사람이 쓴 자리로 되돌려 말할 수 있습니다."},{"h":"좋은 메시지는 다음 행동을 알려 준다","t":"쓸모 있는 오류는 네 가지를 담습니다 — <b>무엇이</b> 잘못됐고, <b>어디서</b> 났고, <b>왜</b> 문제이고, <b>무엇을 하면</b> 되는지. 마지막 하나가 빠진 메시지는 정확해도 막막합니다. 요즘 컴파일러들이 '혹시 이걸 쓰려던 건가요?' 라며 고칠 코드를 직접 보여 주는 이유입니다."}],"code":{"t":"같은 실수, 다른 설명","c":"소스           let x: i32 = \"5\";\n\n불친절한 쪽    error: type mismatch\n\n친절한 쪽      error: 타입이 맞지 않습니다\n                 --> main.rs:3:18\n                  |\n                3 |   let x: i32 = \"5\";\n                  |          ---   ^^^ 여기는 &str 입니다\n                  |          |\n                  |          i32 를 기대했습니다\n                  |\n               도움말: 문자열을 숫자로 바꾸려면\n                3 |   let x: i32 = \"5\".parse().unwrap();"},"key":["오류 하나에서 멈추지 않으려면 상태를 추스르고 계속 읽어야 한다","추스르는 방식이 서툴면 없는 오류가 줄줄이 딸려 나온다","토큰과 노드는 값과 함께 원본 위치를 들고 다닌다","좋은 메시지는 무엇·어디서·왜·어떻게를 담는다"]}},{"t":"진단과 복구 III","q":[{"t":"choice","k":"누구를 탓할 것인가","cat":"internals","q":"타입을 추론하는 언어에서 타입 충돌이 났을 때, 컴파일러가 <b>어느 줄을 짚을지</b> 정하기 어려운 이유는?","code":"let mut xs = vec![];   // ← 여기서 타입이 정해진다\nxs.push(1);            // ← i32 로 굳는다\nxs.push(\"둘\");         // ← 여기서 충돌이 드러난다","o":["충돌은 마지막 줄에서 드러나지만 타입은 앞에서 정해져서 연산자라고 보아야 한다","충돌이 나면 맨 첫 줄을 짚도록 표준에 미리 그렇게 정해져 있기 때문이라고 늘 있는 그대로 짚어 두어야 한다","추론은 파일 전체를 한꺼번에 한 번에 처리하므로 줄 단위 보고 자체가 불가능하기 때문이라고 늘 그대로 짚어 두어야 한다","추론에는 위치 정보가 없어 어느 줄인지 알 수가 없기 때문이라고 실제로 무리 없이 설명할 수 있다"],"a":0,"ex":"타입 추론이 편한 만큼 오류 메시지는 어려워진다.\n개념: 명시적으로 타입을 적는 언어에서는 '적어 둔 것과 다르다' 고 말하면 그만이다. 추론에서는 <b>결정된 지점</b>과 <b>모순이 드러난 지점</b>이 떨어져 있어서, 어디를 원인으로 볼지가 판단의 문제가 된다.\n실무: 그래서 좋은 컴파일러는 두 자리를 <b>함께</b> 보여 준다 — '여기서 i32 로 정해졌는데 여기서 &amp;str 이 왔다'. 우리가 할 수 있는 대응은 애매한 곳에 타입을 적어 주는 것이다. 타입 표기 한 줄이 오류를 훨씬 가까운 자리로 끌어온다.\n왜 그 답인가: 어느 쪽을 원래 의도로 볼지 컴파일러가 알 수 없어, 짚는 자리가 사람의 생각과 어긋날 수 있다"},{"t":"choice","k":"펼친 뒤에 난 오류","cat":"debug","q":"매크로나 템플릿을 쓴 코드에서 오류가 나면 메시지가 유독 길고 낯선 이유는?","code":"내가 쓴 것:   MY_ASSERT(x > 0);\n오류가 난 곳: (펼쳐진 뒤의) 내부 코드 수십 줄","o":["매크로는 표준이 아니라 확장 기능이라 진단 규칙이 적용되지 않기 때문이다. 그래서 컴파일러가 위치를 되돌려 주지 못하고 내부 표현을 그대로 찍는다 펼치기 전 코드를 보여 주려면 매크로를 표준에 넣어야 한다.","오류는 <b>펼쳐진 결과</b>에서 발견되는데 사람이 쓴 것은 펼치기 전 한 줄이라, 위치와 내용을 원래 자리로 되돌려 주지 않으면 <b>본 적 없는 코드</b>에 대한 설명을 읽게 된다","매크로는 어휘 분석 전에 처리되어 위치 정보가 없기 때문이다","매크로 안의 코드는 최적화가 더 공격적으로 적용되기 때문이다"],"a":1,"ex":"'내가 쓰지도 않은 코드' 에 대한 오류를 읽어 본 사람은 다 안다.\n개념: 펼치기는 코드를 다른 코드로 바꾸는 일이다. 그 결과에서 문제가 나므로, 진단이 쓸모 있으려면 <b>펼쳐진 자리와 그것을 부른 자리를 함께</b> 들고 있어야 한다. 좋은 구현은 '이 오류는 여기서 펼쳐진 것이고, 부른 곳은 여기다' 라는 자취를 함께 보여 준다.\n실무: 이 자취가 부실한 환경에서는 <b>펼친 결과를 직접 뽑아 보는 것</b>이 가장 빠르다. 대부분의 컴파일러가 전처리·펼치기 결과만 출력하는 옵션을 제공한다."},{"t":"choice","k":"링크 오류가 불친절한 이유","cat":"internals","q":"컴파일 오류는 줄과 칸을 짚어 주는데 링크 오류는 <code>undefined reference to `_ZN3foo3barEv'</code> 처럼 불친절하다. 왜 그런가?","code":"컴파일: 소스를 보고 있다      → 줄·칸·타입을 안다\n링크  : 목적 파일만 보고 있다  → 이름과 주소만 남았다","o":["링커는 표준에 진단 규칙이 없어 구현마다 마음대로 만들기 때문이다","링크 단계는 선택 사항이라 진단에 공을 들이지 않는 대목","링커는 소스를 보지 않는다. 이미 기계어로 번역된 조각들을 이름으로 이어 붙일 뿐이라, 원본의 줄이나 타입 정보가 대부분 사라진 상태다 — 게다가 그 이름은 타입 정보가 섞여 뭉개진이다","링크는 병렬로 처리되어 어느 파일에서 났는지 추적할 수 없기 때문이다. 여러 오브젝트를 동시에 읽어 들이므로 오류가 난 순간의 파일을 특정할 수 없다 그래서 오류 메시지에 줄 번호 대신 심볼 이름만 남는 것이다."],"a":2,"ex":"단계가 뒤로 갈수록 정보가 줄고, 정보가 줄면 설명이 나빠진다.\n개념: 컴파일러는 소스와 타입을 모두 들고 있어서 풍부하게 설명할 수 있다. 링커에게 도착할 때쯤이면 남은 것은 <b>기호 이름과 주소</b>뿐이다. C++ 처럼 같은 이름에 여러 타입을 허용하는 언어는 타입을 이름 속에 섞어 넣기 때문에 그 이름마저 읽기 어렵다.\n실무: 뭉개진 이름은 되돌려 주는 도구가 있다. 그리고 원인은 대개 셋 중 하나다 — 정의를 안 만들었거나, 라이브러리를 안 넣었거나, 선언과 정의의 타입이 미묘하게 다르거나."},{"t":"choice","k":"확신할 수 없을 때","cat":"design","q":"정적 분석기가 실제로는 문제없는 코드에까지 경고를 내는 일이 있다. 왜 이렇게 만들어져 있는가?","code":"실제 문제 있음 · 경고함    → 맞음\n실제 문제 없음 · 경고함    → 거짓 경보\n실제 문제 있음 · 경고 안 함 → 놓침","o":["분석기가 실행 결과를 미리 계산하지 않아 생기는 문제이며 실행해 보면 사라진다. 실제 값을 넣어 돌려 보면 어느 분기가 성립하는지 알 수 있으므로, 실행 정보를 함께 주면 경고가 정확해진다 그래서 실행 정보를 함께 넣어 주면 거짓 경보가 완전히 사라진다고 꽤 짚어 두어야 한다","분석기의 구현이 아직 미완성이라 시간이 지나면 거짓 경보가 0 이 된다","거짓 경보는 사용자가 코드를 더 명확히 쓰도록 유도하려는 의도적 장치다","실행해 보지 않고 모든 경우를 정확히 판정하는 것은 일반적으로 불가능하다. 그래서 놓치지 않는 쪽을 택하면 거짓 경보가 늘고, 거짓 경보를 줄이면 진짜를 놓친다 — 어느 쪽으로 기울일지를 도구가 정하는 것이다"],"a":3,"ex":"'왜 이 경고가 뜨지?' 의 상당수는 도구가 안전한 쪽으로 기울었기 때문이다.\n개념: 프로그램이 어떤 성질을 갖는지 자동으로 완벽하게 판정하는 것은 이론적으로 불가능하다. 그래서 분석기는 <b>확신할 수 없으면 어느 한쪽으로 기울여야</b> 한다. 컴파일러의 타입 검사도 마찬가지라, 실행하면 멀쩡할 코드를 거절하는 경우가 있다.\n실무: 거짓 경보가 많은 규칙은 사람들이 무시하기 시작하고, 그러면 그 규칙은 사실상 없는 것이 된다. 그래서 규칙을 도입할 때는 <b>거짓 경보 비율을 먼저 재 보고</b> 높으면 끄거나 범위를 좁힌다."}],"th":{"sum":"컴파일러가 하루에 우리에게 가장 많이 하는 일은 <b>번역이 아니라 거절</b>입니다. 그 거절을 어떻게 설명하느냐가 언어의 체감 난이도를 절반쯤 정해요 — 같은 실수라도 어떤 컴파일러는 한 줄로 짚어 주고, 어떤 컴파일러는 서른 줄을 쏟아냅니다.","body":[{"h":"첫 오류에서 멈추면 안 된다","t":"오류 하나를 만날 때마다 컴파일을 끝내 버리면, 고치고 다시 돌리기를 <b>오류 개수만큼 반복</b>해야 합니다. 그래서 컴파일러는 오류를 만나면 <b>어떻게든 상태를 추스르고 계속 읽습니다</b>. 다만 추스르는 방식이 서툴면 있지도 않은 오류를 줄줄이 만들어 내요 — 이 균형이 진단 품질의 핵심입니다."},{"h":"위치를 잃으면 설명할 수 없다","t":"'타입이 안 맞는다' 만으로는 쓸모가 없습니다. <b>어느 파일 몇 번째 줄 몇 번째 칸</b>인지 짚어 줘야 하죠. 그래서 토큰과 트리 노드는 값뿐 아니라 <b>원본에서의 위치</b>를 함께 들고 다닙니다. 매크로나 템플릿을 펼친 뒤에도 이 위치를 잃지 않아야 사람이 쓴 자리로 되돌려 말할 수 있습니다."},{"h":"좋은 메시지는 다음 행동을 알려 준다","t":"쓸모 있는 오류는 네 가지를 담습니다 — <b>무엇이</b> 잘못됐고, <b>어디서</b> 났고, <b>왜</b> 문제이고, <b>무엇을 하면</b> 되는지. 마지막 하나가 빠진 메시지는 정확해도 막막합니다. 요즘 컴파일러들이 '혹시 이걸 쓰려던 건가요?' 라며 고칠 코드를 직접 보여 주는 이유입니다."}],"code":{"t":"같은 실수, 다른 설명","c":"소스           let x: i32 = \"5\";\n\n불친절한 쪽    error: type mismatch\n\n친절한 쪽      error: 타입이 맞지 않습니다\n                 --> main.rs:3:18\n                  |\n                3 |   let x: i32 = \"5\";\n                  |          ---   ^^^ 여기는 &str 입니다\n                  |          |\n                  |          i32 를 기대했습니다\n                  |\n               도움말: 문자열을 숫자로 바꾸려면\n                3 |   let x: i32 = \"5\".parse().unwrap();"},"key":["오류 하나에서 멈추지 않으려면 상태를 추스르고 계속 읽어야 한다","추스르는 방식이 서툴면 없는 오류가 줄줄이 딸려 나온다","토큰과 노드는 값과 함께 원본 위치를 들고 다닌다","좋은 메시지는 무엇·어디서·왜·어떻게를 담는다"]}},{"t":"진단과 복구 IV","q":[{"t":"choice","k":"타이핑하는 동안 보여 주려면","cat":"design","q":"편집기가 타이핑하는 도중에도 오류를 밑줄로 보여 주려면, 파서가 보통의 컴파일러와 어떻게 달라야 하는가?","code":"let x = foo(         ← 아직 쓰는 중\n                      편집기는 지금도 무언가 보여 줘야 한다","o":["코드가 깨진 상태에서도 트리를 만들어 내야 한다.","컴파일러를 그대로 쓰되 오류가 나면 화면 갱신을 그냥 건너뛰게 된다고 차근차근 말할 수 있다","편집기는 정규식으로 검사하고 파서는 쓰지 않는다","타이핑이 멈출 때까지 기다렸다가 완전한 코드가 되었을 때에만 파싱하게 된다고 여러 자료를 놓고 보면 분명히 한 번 더 알아 두어야 한다"],"a":0,"ex":"'깨진 코드를 다루는 능력' 이 편집기용 파서의 핵심 요구사항이다.\n개념: 배치 컴파일러는 잘못된 프로그램을 거절하면 임무 완수다. 편집기는 다르다 — 사용자가 코드를 쓰는 <b>거의 모든 순간이 문법적으로 깨진 상태</b>이고, 그 상태에서도 도움을 줘야 한다. 그래서 오류 노드를 품은 트리를 만들고, 아는 데까지의 정보로 기능을 제공한다.\n실무: 여기에 '고친 부분만 다시 파싱하는' 방식이 더해져야 큰 파일에서도 즉시 반응한다. 요즘은 컴파일러와 편집기가 같은 파서를 공유하도록 만드는 흐름이 뚜렷하다 — 두 벌을 따로 두면 진단이 서로 달라진다.\n왜 그 답인가: 오류 자리에 '빠진 부분' 을 표시한 노드를 넣어서라도 트리를 완성해야 자동완성·정의로 이동 같은 기능이 계속 동작한다"},{"t":"choice","k":"고친 곳만 다시 하기","cat":"perf","q":"파일 하나를 고쳤을 때 프로젝트 전체가 아니라 <b>그 파일과 그것에 기대는 곳만</b> 다시 컴파일하려면 무엇이 필요한가?","code":"a.c 를 고쳤다 → 무엇을 다시 해야 하나?","o":["모든 파일을 다시 컴파일하는 것이 유일하게 안전한 방법이다. 무엇이 무엇에 기대는지는 컴파일해 봐야 알 수 있으므로 미리 적어 둘 방법이 없다 의존 관계를 적어 두어도 실제로 바뀌었는지는 확인할 수 없기 때문이다.","무엇이 무엇에 기대는지를 적어 둔 의존 관계와, 파일이 정말 바뀌었는지 판단할 기준(시각이나 내용 해시)이 필요하다. 둘이 있어야 다시 할 최소 범위를 정할 수 있다고 꽤 여기면 된다","컴파일러가 자동으로 판단하므로 아무 준비도 필요 없다","파일 크기를 비교해 커진 파일만 다시 컴파일하면 된다"],"a":1,"ex":"빌드 도구가 하는 일의 절반이 이것이다.\n개념: 헤더 하나를 고치면 그것을 포함한 모든 파일이 영향을 받는다. 그 관계를 모르면 전부 다시 하거나, 덜 해서 <b>낡은 결과를 섞어 쓰는</b> 위험을 진다. 그래서 컴파일러가 '이 파일이 무엇을 읽었는지' 를 함께 뱉어 주고 빌드 도구가 그것을 기록한다.\n실무: 판단 기준을 수정 시각으로만 잡으면 파일을 되돌리거나 시계가 어긋날 때 틀린다. 내용 해시를 쓰면 <b>주석만 고친 경우</b>에도 결과가 같아 다시 안 해도 되는 것을 알아챌 수 있다."},{"t":"choice","k":"무시당하는 경고의 운명","cat":"review","q":"팀 빌드에서 경고가 3,000개 쌓여 있다. 실질적으로 어떤 상태인가?","code":"빌드 로그: warning … × 3,000\n새 경고 1개가 추가되면?","o":["경고는 빌드 결과에 영향을 주지 않으므로 상태를 논할 필요가 없다","3,000개 중 대부분은 무해하므로 문제될 것이 없다","경고 기능이 <b>사실상 꺼진 것과 같다</b>","경고가 많다는 것은 컴파일러가 열심히 검사한다는 뜻이라 오히려 좋은 신호라고 실무에서는 대체로 이해할 수 있다"],"a":2,"ex":"경고는 개수가 아니라 <b>0 에서 얼마나 벗어났는지</b>로 관리하는 것이다.\n개념: 신호가 소음에 묻히면 신호가 아니다. 3,000개가 있는 곳에 하나가 더해지는 것은 아무 사건도 아니고, 사람들은 로그를 아예 안 보게 된다. 이 상태에서 경고는 비용만 있고 값어치는 없다.\n실무: 한 번에 3,000개를 고치는 것은 비현실적이니, <b>지금 개수를 상한으로 못 박고</b> 그 이상 늘면 빌드를 실패시키는 방식이 현실적이다. 그러고 나서 파일이나 규칙 단위로 조금씩 줄여 간다.\n왜 그 답인가: 새로 생긴 진짜 경고 하나가 3,000개 속에 묻혀 아무도 못 본다. 개수를 0 으로 만들고 늘어나지 못하게 막는 것이 켜 두는 것보다 중요하다"},{"t":"choice","k":"친절함의 값","cat":"perf","q":"진단을 친절하게 만들수록 컴파일러가 치르는 비용은?","code":"위치 범위 보관 · 오타 후보 탐색 · 원인 자리 추적 · 고친 코드 제안","o":["비용은 없다. 진단은 컴파일이 끝난 뒤 별도로 계산되기 때문이라고 있는 그대로 알아 두어야 한다","친절한 진단은 컴파일을 빠르게 만든다고 지금 다루는 맥락에서는 분명히 볼 수 있다","생성되는 기계어의 품질이 떨어진다고 충분히 곰곰이 새겨 두어야 한다","메모리와 시간이 든다고 흔히 한 번 더 설명할 수 있다"],"a":3,"ex":"좋은 컴파일러는 '잘될 때는 빠르고 안 될 때는 친절하다'.\n개념: 대부분의 컴파일은 성공한다. 그 흔한 경우에 진단용 정보를 잔뜩 계산하면 매번 손해다. 그래서 평소에는 최소한만 들고 있다가 <b>오류가 확정된 순간</b> 그 지점만 다시 들여다보며 후보를 찾고 설명을 조립한다.\n실무: 우리가 만드는 도구에도 그대로 쓰인다 — 정상 경로는 가볍게, 실패 경로에서만 맥락을 모아 자세히 보고한다. 모든 요청에서 상세 로그를 남기면 평소에 비용을 내고 정작 필요할 때 로그가 넘쳐 못 읽는다.\n왜 그 답인가: 위치를 계속 들고 다니고, 후보를 찾고, 원인 자리를 추적해야 한다. 그래서 오류가 없을 때는 이 일을 되도록 미루고, <b>오류가 실제로 났을 때만</b> 비싼 분석을 하는 식으로 설계한다"}],"th":{"sum":"컴파일러가 하루에 우리에게 가장 많이 하는 일은 <b>번역이 아니라 거절</b>입니다. 그 거절을 어떻게 설명하느냐가 언어의 체감 난이도를 절반쯤 정해요 — 같은 실수라도 어떤 컴파일러는 한 줄로 짚어 주고, 어떤 컴파일러는 서른 줄을 쏟아냅니다.","body":[{"h":"첫 오류에서 멈추면 안 된다","t":"오류 하나를 만날 때마다 컴파일을 끝내 버리면, 고치고 다시 돌리기를 <b>오류 개수만큼 반복</b>해야 합니다. 그래서 컴파일러는 오류를 만나면 <b>어떻게든 상태를 추스르고 계속 읽습니다</b>. 다만 추스르는 방식이 서툴면 있지도 않은 오류를 줄줄이 만들어 내요 — 이 균형이 진단 품질의 핵심입니다."},{"h":"위치를 잃으면 설명할 수 없다","t":"'타입이 안 맞는다' 만으로는 쓸모가 없습니다. <b>어느 파일 몇 번째 줄 몇 번째 칸</b>인지 짚어 줘야 하죠. 그래서 토큰과 트리 노드는 값뿐 아니라 <b>원본에서의 위치</b>를 함께 들고 다닙니다. 매크로나 템플릿을 펼친 뒤에도 이 위치를 잃지 않아야 사람이 쓴 자리로 되돌려 말할 수 있습니다."},{"h":"좋은 메시지는 다음 행동을 알려 준다","t":"쓸모 있는 오류는 네 가지를 담습니다 — <b>무엇이</b> 잘못됐고, <b>어디서</b> 났고, <b>왜</b> 문제이고, <b>무엇을 하면</b> 되는지. 마지막 하나가 빠진 메시지는 정확해도 막막합니다. 요즘 컴파일러들이 '혹시 이걸 쓰려던 건가요?' 라며 고칠 코드를 직접 보여 주는 이유입니다."}],"code":{"t":"같은 실수, 다른 설명","c":"소스           let x: i32 = \"5\";\n\n불친절한 쪽    error: type mismatch\n\n친절한 쪽      error: 타입이 맞지 않습니다\n                 --> main.rs:3:18\n                  |\n                3 |   let x: i32 = \"5\";\n                  |          ---   ^^^ 여기는 &str 입니다\n                  |          |\n                  |          i32 를 기대했습니다\n                  |\n               도움말: 문자열을 숫자로 바꾸려면\n                3 |   let x: i32 = \"5\".parse().unwrap();"},"key":["오류 하나에서 멈추지 않으려면 상태를 추스르고 계속 읽어야 한다","추스르는 방식이 서툴면 없는 오류가 줄줄이 딸려 나온다","토큰과 노드는 값과 함께 원본 위치를 들고 다닌다","좋은 메시지는 무엇·어디서·왜·어떻게를 담는다"]}}],"ord":6},{"t":"컴파일한 뒤에도 원래 코드를 읽는 법 — 디버그 정보와 소스맵","g":"","l":[{"t":"원래 코드로 되돌리기 I","q":[{"t":"choice","k":"줄 번호가 하나뿐인 이유","cat":"debug","q":"배포된 웹 앱의 오류 보고에 아래 같은 위치만 찍힌다. 줄 번호가 늘 1인 까닭은?","code":"TypeError: Cannot read properties of undefined\n    at t (app.9f2c1b.js:1:24817)\n    at n (app.9f2c1b.js:1:25102)\n    at app.9f2c1b.js:1:31944","o":["번들러가 모든 파일을 줄바꿈 없이 한 줄로 이어 붙였기 때문이라고 곰곰이 알아 두어야 한다","오류 보고 도구가 첫 줄만 기록하도록 설정되어 있기 때문이다","압축된 파일에서는 브라우저가 줄 번호를 계산하지 못해 1로 고정하기 때문이라고 여러 자료에서 공통으로 짚는 대목까지 더해서 보면 분명히 곰곰이 말할 수 있다","오류가 실제로 파일의 첫 줄에서 났고, 나머지는 그 안에서 호출된 것이기 때문이라고 여러 자료를 놓고 보면 실제로 한 번 더 알아 두어야 한다"],"a":0,"ex":"줄바꿈도 바이트라서, 최소화 과정에서 가장 먼저 지워지는 것 중 하나다.\n개념: 위치를 '몇 째 줄 몇 째 칸' 으로 표현하는데 줄이 하나뿐이면 <b>칸 번호만 남는다</b>. 24817번째 글자라는 정보는 정확하지만 사람에게는 쓸모가 없다.\n실무: 그래서 이 숫자를 원본 위치로 되돌려 주는 표가 필요하다. 그 표가 소스맵이고, 다음 문제들에서 무엇이 들어 있는지 본다.\n왜 그 답인가: 그래서 위치를 나타내는 정보가 사실상 칸 번호 하나뿐이다"},{"t":"choice","k":"사라진 함수","cat":"internals","q":"아래 C 코드를 최적화해 컴파일한 뒤 심볼을 찾아보니 add 가 없다. 왜인가?","code":"static int add(int a, int b) { return a + b; }\n\nint compute(int n) {\n  int s = 0;\n  for (int i = 0; i &lt; n; i++) s = add(s, i);\n  return s;\n}\n\n// nm 으로 add 를 찾으면 → 결과 없음\n// 디스어셈블해도 add 를 부르는 call 명령이 없다","o":["static 으로 선언한 함수는 실행 파일에 포함되지 않고 헤더에만 존재하기 때문이다","컴파일러가 본문을 부르는 자리에 펼쳐 넣어서","두 줄짜리 함수는 컴파일러가 상수로 미리 계산해 치환하기 때문이다","쓰이지 않는 함수로 판단되어 통째로 제거되었기 때문이다"],"a":1,"ex":"인라인은 호출 비용을 없애는 가장 흔한 최적화다.\n개념: 문제는 그 뒤다 — 실행 중 오류가 나도 <b>스택에 add 라는 칸이 존재하지 않는다</b>. 컴파일러가 만든 코드와 사람이 쓴 코드가 일대일이 아니게 된 것이다.\n실무: 디버그 정보를 넣으면 컴파일러가 '여기는 원래 add 를 펼친 자리다' 라는 기록을 함께 남긴다. 그 기록이 있어야 디버거가 사라진 칸을 되살려 보여 줄 수 있다.\n왜 그 답인가: 함수는 사라졌지만 하는 일은 남아 있다"},{"t":"choice","k":"이름이 짧아진다","cat":"knowledge","q":"최소화 도구가 지역 변수 이름을 한 글자로 바꾸면서도 프로그램이 그대로 도는 이유는?","code":"// 원본\nfunction totalPrice(items, taxRate) {\n  let subtotal = 0;\n  for (const item of items) subtotal += item.price;\n  return subtotal * (1 + taxRate);\n}\n\n// 최소화\nfunction t(e,n){let r=0;for(const o of e)r+=o.price;return r*(1+n)}","o":["자바스크립트 엔진이 실행할 때 원래 이름을 되살려서 쓰기 때문이다","최소화 도구가 이름 대응표를 파일 안에 함께 넣어 두기 때문이다","지역 이름은 그 안에서만 쓰이므로 일관되게 바꾸면 뜻이 보존되기 때문이다 — 반면 price 처럼 바깥과 약속된 이름은 바꾸지 못해 그대로 남았다고 볼 수 있다","이름은 주석과 같아 실행에 아무 영향을 주지 않기 때문이다"],"a":2,"ex":"<code>item.price</code> 의 <code>price</code> 가 그대로 남은 것을 보면 규칙이 보인다.\n개념: 이름 바꾸기는 <b>범위가 닫혀 있을 때만</b> 안전하다. 객체 속성이나 내보내는 함수 이름은 바깥에서 그 이름으로 찾으므로 건드릴 수 없다.\n실무: 그래서 문자열로 속성에 접근하는 코드를 최소화하면 깨질 수 있다. 그리고 디버깅 관점에서는 <b>사람이 붙인 이름이 통째로 날아간다</b> 는 대가를 치른 셈이다."},{"t":"choice","k":"줄이 뒤섞인다","cat":"internals","q":"최적화를 켜고 디버거로 한 줄씩 실행하니 커서가 위아래로 튄다. 이것은 무엇을 뜻하는가?","code":"원본           최적화 후 기계어\n 10줄  ─┐\n 11줄  ─┼──→  명령 A   (10줄과 12줄이 합쳐진 것)\n 12줄  ─┘     명령 B   (11줄에서 온 것)\n              명령 C   (10줄에서 온 것)","o":["소스 파일이 빌드한 뒤에 수정되는 바람에 줄 번호가 그만큼 밀려 버린이라고 흔히 정리할 수 있다","디버그 정보가 어딘가에서 손상되어 잘못된 줄을 가리키고 있는 것이므로 처음부터 새로 다시 빌드해야 한다고 이 단원에서는 흔히 알아 두어야 한다","디버거가 최적화된 코드를 제대로 지원하지 않아서 임의의 줄을 그냥 아무렇게나 보여 주는 뜻이라고 보면 된다","디버그 정보가 기계어 위치마다 원본 줄을 정직하게 적어 둔 결과 라고 적는 기호"],"a":3,"ex":"커서가 튀는 것은 <b>표가 틀려서가 아니라 맞아서</b> 생기는 현상이다.\n개념: 최적화는 명령을 옮기고 합치고 지운다. 그 결과 '기계어 한 덩어리' 대 '원본 한 줄' 의 대응이 일대일이 아니게 되고, 표는 그 사실을 그대로 반영한다.\n실무: 그래서 값을 한 줄씩 따라가야 하는 조사에서는 최적화를 낮춘 빌드를 따로 만든다. 다만 그 빌드는 <b>원래 버그를 재현하지 못할 수도</b> 있다는 점을 염두에 둔다.\n왜 그 답인가: 최적화가 계산 순서를 바꿨으니 대응도 그렇게 튄다"}],"th":{"sum":"컴파일과 번들링은 <b>사람이 읽던 것을 기계가 읽을 것으로 바꾸는 일</b>입니다. 그러면 문제가 터졌을 때 되짚을 길이 사라지죠. 그래서 컴파일러는 결과물과 <b>별도로 대응표</b>를 남깁니다 — 네이티브 쪽의 디버그 정보와 웹 쪽의 소스맵이 그것입니다.","body":[{"h":"왜 읽을 수 없게 되는가","t":"이름은 짧아지고(<code>userCount</code> → <code>a</code>), 함수는 <b>호출한 자리에 통째로 펼쳐지고</b>, 줄은 합쳐지고 순서까지 바뀝니다. 남은 것은 '잘 도는 코드' 지 '읽을 수 있는 코드' 가 아니에요. 스택 트레이스에 <code>a.js:1:24817</code> 만 찍히는 이유가 이것입니다."},{"h":"결과물이 아니라 옆에 표를 둔다","t":"해결책은 결과물을 되돌리는 것이 아니라 <b>변환하면서 대응표를 같이 적어 두는 것</b>입니다. '결과물의 이 위치는 원본의 저 줄 저 칸' 이라는 기록이죠. 네이티브에서는 <b>DWARF 같은 디버그 섹션</b>이, 웹에서는 <b>.map 파일</b>이 그 표입니다."},{"h":"표를 남겨도 코드는 그대로다","t":"많이 하는 오해가 '디버그 정보를 넣으면 느려진다' 는 것입니다. 실제로는 <b>실행 파일이 커질 뿐 기계어는 한 바이트도 달라지지 않아요</b>. 느려지는 것은 최적화를 끄는 쪽이고, 그것은 별개의 선택입니다. 그래서 <b>최적화는 켜고 디버그 정보도 넣는</b> 조합이 릴리스 빌드의 기본입니다."},{"h":"표는 아무에게나 주면 안 된다","t":"소스맵에는 <b>원본 소스가 통째로 들어 있을 수 있습니다</b>. 그대로 배포하면 최소화한 의미가 없어지죠. 그래서 표는 만들되 <b>공개 경로가 아니라 오류 수집 도구에만</b> 올립니다. 네이티브 쪽도 같습니다 — 심볼을 떼어 배포하고, 떼어 낸 심볼은 따로 보관합니다."}],"code":{"t":"같은 실행 파일, 다른 읽을거리","c":"gcc -O2      t.c -o no_g      →  16000 바이트\ngcc -O2 -g   t.c -o with_g    →  18496 바이트\n\n  기계어(.text) 를 바이트 단위로 비교하면?      완전히 동일\n  늘어난 2496 바이트는 전부 .debug_* 섹션\n\nstrip with_g                  →  14472 바이트\n\n  기계어는 여전히 동일\n  사라진 것은 '이 주소가 main 이다' 라는 이름표뿐\n  그래서 디스어셈블하면 main 자리가 그냥 .text 로 보인다"},"key":["최적화·미니파이는 원본과의 대응을 지운다","컴파일러는 결과물 옆에 대응표를 따로 남긴다","디버그 정보는 파일을 키울 뿐 기계어를 바꾸지 않는다","strip 은 이름을 떼는 것이지 코드를 바꾸는 것이 아니다","소스맵과 심볼은 공개 배포가 아니라 오류 수집 쪽에 올린다"]}},{"t":"원래 코드로 되돌리기 II","q":[{"t":"choice","k":"소스맵에 든 것","cat":"internals","q":"소스맵의 mappings 에 든 <code>AAUI</code> 같은 조각은 무엇을 담고 있는가?","code":"{\n  \"version\": 3,\n  \"sources\": [\"src/cart.js\", \"src/tax.js\"],\n  \"names\": [\"totalPrice\", \"subtotal\"],\n  \"mappings\": \"AAUI,KACF,...\"\n}\n\n// AAUI 를 풀면 → [0, 0, 10, 4]\n//   결과물의 이 위치 = sources[0] 의 10번째 줄 4번째 칸","o":["결과물 위치와 원본 위치의 대응을 숫자 네댓 개로 적은 것이다 — 값은 모두 앞 조각과의 차이로 적어 길이를 줄인다고 꽤 곰곰이 말할 수 있다","최소화 과정에서 바뀐 이름의 대응표를 통째로 적어 둔이라고 봐도 된다","결과물의 무결성을 확인하기 위한 해시값이다","원본 소스 코드 자체를 압축해 담은 대목"],"a":0,"ex":"<code>AAUI</code> 를 풀면 <b>[0, 0, 10, 4]</b> 가 나온다 — 소스 0번, 10줄, 4칸이라는 뜻이다.\n개념: 위치 정보는 개수가 엄청나므로 절대값 대신 <b>앞 값과의 차이</b>만 적고, 그 차이를 여섯 비트짜리 글자로 이어 붙인다. 그래서 눈으로는 뜻 없는 문자열로 보인다.\n실무: 직접 읽을 일은 없지만 형식을 알면 문제를 판단할 수 있다 — <code>sources</code> 경로가 틀려 있으면 아무리 정확한 대응도 원본을 못 찾아 쓸모없어진다."},{"t":"choice","k":"디버그 정보와 속도","cat":"design","q":"릴리스 빌드에 디버그 정보를 넣자는 제안에 '느려진다' 는 반대가 나왔다. 아래 측정 결과가 말해 주는 것은?","code":"gcc -O2      t.c -o no_g     →  16000 바이트\ngcc -O2 -g   t.c -o with_g   →  18496 바이트\n\n두 파일의 .text 섹션 기계어를 바이트 단위로 비교\n  → 완전히 동일\n늘어난 2496 바이트\n  → 전부 .debug_info · .debug_line 등 별도 섹션","o":["반대가 맞다 — 디버그 정보를 넣으면 컴파일러가 최적화를 자동으로 낮춘다","반대가 틀렸다 — 디버그 정보는 파일을 키울 뿐 기계어를 바꾸지 않는다. 느려지는 것은 최적화를 끄는 쪽이고 그것은 별개의 선택이라고 늘 곰곰이 알아 두어야 한다","반대가 맞다 — 파일이 커지면 그만큼 실행 속도도 비례해 느려진다","판단할 수 없다"],"a":1,"ex":"두 옵션은 서로 독립이다. <code>-O2 -g</code> 는 <b>모순되는 조합이 아니다</b>.\n개념: 디버그 섹션은 실행할 때 메모리로 올라가지도 않는다. 디버거나 심볼라이저가 파일에서 따로 읽어 가는 부록에 가깝다.\n실무: 그래서 최적화는 켜고 디버그 정보도 넣은 다음, 배포본에서는 심볼을 떼어 내고 <b>떼어 낸 심볼을 따로 보관</b>하는 방식이 널리 쓰인다."},{"t":"choice","k":"결과물에 남는 한 줄","cat":"knowledge","q":"최소화된 파일 맨 끝의 아래 주석은 어떤 일을 하는가?","code":"...;function t(e,n){...}\n//# sourceMappingURL=app.9f2c1b.js.map","o":["빌드 도구가 다음 빌드에서 캐시를 재사용하도록 기록한 흔적이라고 앞뒤를 나란히 놓고 따져 보면 분명히 곰곰이 정리할 수 있다","대응표를 이 주석 안에 압축해서 그대로 담고 있다고 실제로 어렵지 않게 짚어 두어야 한다","대응표가 어디에 있는지만 알려 준다고 어느 정도는 곰곰이 볼 수 있다","이 파일이 최소화되었음을 표시해 브라우저가 자동으로 그대로 복원하게 한다고 실무에서는 늘 곰곰이 할 수 있다"],"a":2,"ex":"이 한 줄은 <b>가리키는 표지판일 뿐</b>이다. 표 자체는 별도 파일에 있다.\n개념: 그래서 이 주석이 있어도 <code>.map</code> 파일을 배포하지 않으면 되짚을 수 없고, 반대로 주석만 지우고 <code>.map</code> 을 올려 두면 경로를 아는 사람은 여전히 받아 갈 수 있다.\n실무: 즉 이 주석의 유무는 접근을 막는 수단이 아니다. 정말 막으려면 <b>파일 자체를 공개 경로에 두지 않아야</b> 한다.\n왜 그 답인가: 개발자 도구가 필요할 때 그 파일을 따로 받아 원본 위치를 되짚는다"},{"t":"choice","k":"이름표를 떼어 낸다","cat":"internals","q":"실행 파일에서 심볼을 떼어 내면 무엇이 사라지는가?","code":"strip with_g\n  18496 바이트  →  14472 바이트\n\n기계어 바이트를 비교하면          완전히 동일\n디스어셈블 결과를 비교하면\n  전:   main:      55  push %rbp ...\n  후:   .text:     55  push %rbp ...","o":["코드가 압축되어 실행할 때마다 풀어야 하므로 시작이 그만큼 약간 느려지게 된다고 이 단원에서는 꽤 할 수 있다","쓰이지 않는 코드가 함께 제거되어 프로그램이 조금 더 빨라지게 된다고 차근차근 짚어 두어야 한다","디버그 정보만 사라지고 함수 이름은 그대로 남는다고 앞에서 짚은 내용과 지금 보고 있는 대목을 나란히 놓고 따져 보면 늘 이해할 수 있다","주소에 붙어 있던 이름표만 사라진다"],"a":3,"ex":"같은 명령 <code>55 push %rbp</code> 앞의 이름이 <b>main 에서 .text 로 바뀐 것이 차이의 전부</b>다.\n개념: 이름표는 실행에 쓰이지 않는다. 기계는 주소로 움직이고, 이름은 오직 사람과 도구를 위한 것이다.\n실무: 그래서 심볼을 떼면 크래시 보고서가 주소 목록으로만 온다. 그 주소를 다시 함수 이름으로 바꾸려면 <b>떼어 내기 전 파일을 보관</b>해 두어야 한다 — 이것이 다음 문제의 주제다.\n왜 그 답인가: 실행되는 명령은 한 바이트도 바뀌지 않으므로 프로그램은 똑같이 돌지만 사람이 읽을 단서가 없어진다"}],"th":{"sum":"컴파일과 번들링은 <b>사람이 읽던 것을 기계가 읽을 것으로 바꾸는 일</b>입니다. 그러면 문제가 터졌을 때 되짚을 길이 사라지죠. 그래서 컴파일러는 결과물과 <b>별도로 대응표</b>를 남깁니다 — 네이티브 쪽의 디버그 정보와 웹 쪽의 소스맵이 그것입니다.","body":[{"h":"왜 읽을 수 없게 되는가","t":"이름은 짧아지고(<code>userCount</code> → <code>a</code>), 함수는 <b>호출한 자리에 통째로 펼쳐지고</b>, 줄은 합쳐지고 순서까지 바뀝니다. 남은 것은 '잘 도는 코드' 지 '읽을 수 있는 코드' 가 아니에요. 스택 트레이스에 <code>a.js:1:24817</code> 만 찍히는 이유가 이것입니다."},{"h":"결과물이 아니라 옆에 표를 둔다","t":"해결책은 결과물을 되돌리는 것이 아니라 <b>변환하면서 대응표를 같이 적어 두는 것</b>입니다. '결과물의 이 위치는 원본의 저 줄 저 칸' 이라는 기록이죠. 네이티브에서는 <b>DWARF 같은 디버그 섹션</b>이, 웹에서는 <b>.map 파일</b>이 그 표입니다."},{"h":"표를 남겨도 코드는 그대로다","t":"많이 하는 오해가 '디버그 정보를 넣으면 느려진다' 는 것입니다. 실제로는 <b>실행 파일이 커질 뿐 기계어는 한 바이트도 달라지지 않아요</b>. 느려지는 것은 최적화를 끄는 쪽이고, 그것은 별개의 선택입니다. 그래서 <b>최적화는 켜고 디버그 정보도 넣는</b> 조합이 릴리스 빌드의 기본입니다."},{"h":"표는 아무에게나 주면 안 된다","t":"소스맵에는 <b>원본 소스가 통째로 들어 있을 수 있습니다</b>. 그대로 배포하면 최소화한 의미가 없어지죠. 그래서 표는 만들되 <b>공개 경로가 아니라 오류 수집 도구에만</b> 올립니다. 네이티브 쪽도 같습니다 — 심볼을 떼어 배포하고, 떼어 낸 심볼은 따로 보관합니다."}],"code":{"t":"같은 실행 파일, 다른 읽을거리","c":"gcc -O2      t.c -o no_g      →  16000 바이트\ngcc -O2 -g   t.c -o with_g    →  18496 바이트\n\n  기계어(.text) 를 바이트 단위로 비교하면?      완전히 동일\n  늘어난 2496 바이트는 전부 .debug_* 섹션\n\nstrip with_g                  →  14472 바이트\n\n  기계어는 여전히 동일\n  사라진 것은 '이 주소가 main 이다' 라는 이름표뿐\n  그래서 디스어셈블하면 main 자리가 그냥 .text 로 보인다"},"key":["최적화·미니파이는 원본과의 대응을 지운다","컴파일러는 결과물 옆에 대응표를 따로 남긴다","디버그 정보는 파일을 키울 뿐 기계어를 바꾸지 않는다","strip 은 이름을 떼는 것이지 코드를 바꾸는 것이 아니다","소스맵과 심볼은 공개 배포가 아니라 오류 수집 쪽에 올린다"]}},{"t":"원래 코드로 되돌리기 III","q":[{"t":"choice","k":"주소를 이름으로","cat":"ops","q":"배포본에서 온 크래시 보고서에 주소만 찍혀 있다. 이것을 함수 이름과 줄 번호로 되돌리려면 무엇이 필요한가?","code":"크래시 보고서\n  #0  0x0000000000401a37\n  #1  0x0000000000401b02\n  #2  0x00000000004012d5","o":["그 배포본과 정확히 같은 빌드에서 나온 심볼 파일이다 — 다시 빌드한 것은 주소가 달라 쓸 수 없다고 분명히 새겨 두어야 한다","같은 소스에서 다시 컴파일한 파일이면 충분하다","크래시 보고서에 이미 정보가 다 들어 있으므로 별도 파일 없이 해석할 수 있다","주소를 16진수에서 10진수로 바꾸어 소스 줄 번호와 대조하면 된다"],"a":0,"ex":"되짚기는 <b>주소를 열쇠로 표를 찾는 일</b>이라, 표가 그 주소 체계와 맞아야 한다.\n개념: 컴파일러 버전, 최적화 옵션, 심지어 빌드 순서가 조금만 달라도 주소는 밀린다. 밀린 표로 되짚으면 오류가 나지 않고 <b>엉뚱한 함수 이름이 그럴듯하게 나온다</b> — 이쪽이 더 위험하다.\n실무: 그래서 빌드마다 식별자를 붙이고, 그 식별자로 심볼 파일을 찾아 쓰도록 자동화한다. 배포한 빌드의 심볼은 버리지 않고 보관한다."},{"t":"choice","k":"표가 어긋났을 때","cat":"debug","q":"소스맵을 적용했더니 오류 위치가 빈 줄이나 주석을 가리킨다. 가장 가능성 높은 원인은?","code":"오류 위치 → src/cart.js:47\n\n src/cart.js 의 47번째 줄\n  45 |   return total;\n  46 | }\n  47 |                    ← 빈 줄\n  48 | // 세금 계산","o":["브라우저가 소스맵의 줄 번호를 0부터 세기 때문에 결국 한 줄씩 밀려 버린이라고 흔히 알아 두어야 한다","결과물과 소스맵이 서로 다른 시점의 빌드에서 나온이다","빈 줄에도 기계어가 생성되므로 정상적인 결과다","소스맵 형식의 버전이 너무 낮아 정확한 칸 정보를 담지 못한이라고 되어 있다"],"a":1,"ex":"'가까운데 조금 어긋난' 위치는 <b>버전 불일치의 전형적인 증상</b>이다.\n개념: 대응표는 특정 결과물과 특정 소스 사이의 약속이다. 둘 중 하나만 바뀌면 표는 조용히 틀린 답을 준다 — 형식은 멀쩡하니 오류도 나지 않는다.\n실무: 결과물 파일 이름에 내용 해시를 넣고 소스맵도 같은 해시를 쓰면 이런 짝 어긋남을 구조적으로 막을 수 있다.\n왜 그 답인가: 소스가 바뀐 뒤 결과물만 새로 배포되었거나 그 반대다"},{"t":"choice","k":"값을 볼 수 없다","cat":"debug","q":"최적화된 빌드를 디버거로 멈춰 변수를 보니 '최적화로 제거됨' 이라고 나온다. 무엇을 뜻하는가?","code":"(디버거) print subtotal\n  &lt;optimized out&gt;\n\n// 원본에는 분명히 있는 지역 변수다","o":["변수가 아직 초기화되기 전 지점에서 그만 멈춰 버렸기 때문이라고 늘 곰곰이 알아 두어야 한다","디버거의 권한이 부족해서 메모리를 읽지 못한이라고 이 단원에서는 흔히 볼 수 있다","그 변수가 메모리에 존재하지 않기 때문이라고 한 번 더 정리할 수 있다","디버그 정보가 통째로 빠진 빌드라서 변수 이름을 끝내 찾아내지 못한이라고 실무에서는 그대로 할 수 있다"],"a":2,"ex":"디버그 정보가 있어도 <b>없는 값을 보여 줄 수는 없다</b>.\n개념: 최적화는 변수를 레지스터에 두거나, 다른 계산에 합쳐 버리거나, 필요 없어진 구간에서 통째로 없앤다. 표는 '여기서는 그 값이 살아 있지 않다' 는 것까지 기록한다.\n실무: 이 상태에서 값을 보려면 최적화를 낮춘 빌드가 필요하다. 그 전에 로그를 남기는 편이 빠를 때가 많다 — 로그로 찍은 값은 최적화가 지우지 못한다.\n왜 그 답인가: 레지스터에만 있었거나 계산에 흡수되어 사라졌고, 표는 그 사실을 정직하게 알려 주는 것이다"},{"t":"choice","k":"빌드 설정을 정한다","cat":"design","q":"웹 앱 릴리스 빌드의 소스맵 설정을 정하려 한다. 가장 균형 잡힌 선택은?","code":"고를 것\n  A) 소스맵을 만들지 않는다\n  B) 소스맵을 만들어 결과물과 함께 공개 경로에 올린다\n  C) 소스맵을 만들되 오류 수집 도구에만 올리고 공개하지 않는다","o":["A — 만들지 않는 것이 가장 안전하다. 오류는 재현해서 고치면 된다고 이 단원에서는 비교적 자주 그대로 알아 두어야 한다","셋 다 비슷하다 — 최소화된 코드는 어차피 되돌릴 수 있으므로 큰 차이가 없다고 흔히 볼 수 있다","B — 사용자가 직접 신고할 수 있어 디버깅이 빨라진다","C — 되짚을 능력은 확보하면서 원본을 공개하지 않는다."],"a":3,"ex":"핵심은 <b>만드는 것과 배포하는 것을 분리</b>하는 데 있다.\n개념: A 를 고르면 배포본에서만 나는 버그를 영영 읽을 수 없다. B 는 최소화의 의미를 없앤다. C 는 둘 다 피한다.\n실무: 최소화가 코드를 지켜 주지 못한다는 말도 반쯤만 맞다. 이름과 구조가 사라진 코드를 읽는 것은 <b>가능하지만 훨씬 비싸다</b>. 표를 그대로 주는 것은 그 비용을 0으로 만들어 주는 일이다.\n왜 그 답인가: 표를 만드는 것과 아무에게나 주는 것은 별개의 결정이다"}],"th":{"sum":"컴파일과 번들링은 <b>사람이 읽던 것을 기계가 읽을 것으로 바꾸는 일</b>입니다. 그러면 문제가 터졌을 때 되짚을 길이 사라지죠. 그래서 컴파일러는 결과물과 <b>별도로 대응표</b>를 남깁니다 — 네이티브 쪽의 디버그 정보와 웹 쪽의 소스맵이 그것입니다.","body":[{"h":"왜 읽을 수 없게 되는가","t":"이름은 짧아지고(<code>userCount</code> → <code>a</code>), 함수는 <b>호출한 자리에 통째로 펼쳐지고</b>, 줄은 합쳐지고 순서까지 바뀝니다. 남은 것은 '잘 도는 코드' 지 '읽을 수 있는 코드' 가 아니에요. 스택 트레이스에 <code>a.js:1:24817</code> 만 찍히는 이유가 이것입니다."},{"h":"결과물이 아니라 옆에 표를 둔다","t":"해결책은 결과물을 되돌리는 것이 아니라 <b>변환하면서 대응표를 같이 적어 두는 것</b>입니다. '결과물의 이 위치는 원본의 저 줄 저 칸' 이라는 기록이죠. 네이티브에서는 <b>DWARF 같은 디버그 섹션</b>이, 웹에서는 <b>.map 파일</b>이 그 표입니다."},{"h":"표를 남겨도 코드는 그대로다","t":"많이 하는 오해가 '디버그 정보를 넣으면 느려진다' 는 것입니다. 실제로는 <b>실행 파일이 커질 뿐 기계어는 한 바이트도 달라지지 않아요</b>. 느려지는 것은 최적화를 끄는 쪽이고, 그것은 별개의 선택입니다. 그래서 <b>최적화는 켜고 디버그 정보도 넣는</b> 조합이 릴리스 빌드의 기본입니다."},{"h":"표는 아무에게나 주면 안 된다","t":"소스맵에는 <b>원본 소스가 통째로 들어 있을 수 있습니다</b>. 그대로 배포하면 최소화한 의미가 없어지죠. 그래서 표는 만들되 <b>공개 경로가 아니라 오류 수집 도구에만</b> 올립니다. 네이티브 쪽도 같습니다 — 심볼을 떼어 배포하고, 떼어 낸 심볼은 따로 보관합니다."}],"code":{"t":"같은 실행 파일, 다른 읽을거리","c":"gcc -O2      t.c -o no_g      →  16000 바이트\ngcc -O2 -g   t.c -o with_g    →  18496 바이트\n\n  기계어(.text) 를 바이트 단위로 비교하면?      완전히 동일\n  늘어난 2496 바이트는 전부 .debug_* 섹션\n\nstrip with_g                  →  14472 바이트\n\n  기계어는 여전히 동일\n  사라진 것은 '이 주소가 main 이다' 라는 이름표뿐\n  그래서 디스어셈블하면 main 자리가 그냥 .text 로 보인다"},"key":["최적화·미니파이는 원본과의 대응을 지운다","컴파일러는 결과물 옆에 대응표를 따로 남긴다","디버그 정보는 파일을 키울 뿐 기계어를 바꾸지 않는다","strip 은 이름을 떼는 것이지 코드를 바꾸는 것이 아니다","소스맵과 심볼은 공개 배포가 아니라 오류 수집 쪽에 올린다"]}},{"t":"원래 코드로 되돌리기 IV","q":[{"t":"choice","k":"표 안에 든 원본","cat":"security","q":"소스맵을 공개 경로에 올렸더니 최소화 이전 소스가 그대로 노출됐다. 어떤 항목 때문인가?","code":"{\n  \"version\": 3,\n  \"sources\": [\"src/billing.js\"],\n  \"sourcesContent\": [\"function applyDiscount(user){ ... 원본 전체 ... }\"],\n  \"mappings\": \"AAUI,...\"\n}","o":["sourcesContent 다 — 원본 파일 내용을 통째로 담을 수 있는 항목이라, 이것이 있으면 소스맵 하나로 프로젝트를 재구성할 수 있다고 실무에서는 알아 두어야 한다","sources 다","<code>names</code> 다 — 원래 이름이 모두 들어 있어 코드를 되돌릴 수 있다","<code>mappings</code> 다 — 위치 정보를 역산하면 원본 코드를 복원할 수 있다"],"a":0,"ex":"다른 항목들은 위치와 이름만 담지만 <code>sourcesContent</code> 는 <b>소스 그 자체</b>다.\n개념: 이 항목이 있는 이유는 실용적이다 — 개발자 도구가 원본 파일을 따로 받지 않아도 되니까. 그래서 많은 도구가 기본으로 넣는다.\n실무: 공개 경로에 올릴 일이 있다면 이 항목을 빼도록 설정하고, 그렇지 않다면 파일 자체를 올리지 않는다. 주석 한 줄을 지우는 것으로는 막히지 않는다."},{"t":"choice","k":"심볼을 버렸을 때","cat":"ops","q":"빌드 파이프라인이 심볼을 떼어 내고 그 심볼 파일을 보관하지 않는다. 어떤 문제가 언제 드러나는가?","code":"빌드 → strip → 배포\n         └─ 떼어 낸 심볼은 어디에도 저장하지 않음\n\n(몇 주 뒤)\n사용자 크래시 보고 도착 — 주소 목록만 들어 있다","o":["빌드 직후 검증 단계에서 바로 드러난다 — 심볼이 없으면 배포가 실패한다","사고가 난 다음에야 드러난다 — 그때는 배포본과 똑같은 심볼을 만들 방법이 없어 보고서를 해석할 수 없다","문제가 되지 않는다","실행 속도가 느려지는 형태로 서서히 드러난다"],"a":1,"ex":"이런 설정은 <b>평소에는 아무 신호도 내지 않는다</b>. 그래서 위험하다.\n개념: 같은 커밋으로 다시 빌드해도 컴파일러 버전이나 옵션이 조금만 달라지면 주소가 밀린다. 재현 가능한 빌드를 갖추지 않았다면 '다시 빌드하면 된다' 는 기대는 무너진다.\n실무: 배포 산출물에 심볼을 포함해 보관하고, 빌드 식별자로 찾아 쓰도록 자동화한다. 보관 비용은 크래시 하나를 못 읽는 비용보다 훨씬 싸다."},{"t":"choice","k":"이 코드가 없다","cat":"review","q":"동료가 '최소화된 코드는 어차피 읽을 수 있으니 소스맵을 공개해도 된다' 고 한다. 어떻게 답하는 것이 정확한가?","code":"최소화된 코드            소스맵을 함께 주면\n  이름 없음               원래 이름 그대로\n  줄 없음                 원래 줄 번호 그대로\n  주석 없음               주석까지 (sourcesContent 가 있으면)\n  파일 구조 없음          원래 디렉터리 구조 그대로","o":["동료 말이 틀렸다 — 소스맵이 없으면 최소화된 코드는 원리적으로 복원이 불가능하다","동료 말이 맞다","'읽을 수 있다' 와 '비용 없이 읽을 수 있다' 는 다르다 — 표를 주는 것은 그 비용을 0으로 만드는 일이라, 같은 상태로 볼 수 없다고 대체로 어렵지 않게 할 수 있다","동료 말이 맞지만 대역폭이 늘어나는 것이 문제이므로 그 이유로 막아야 한다"],"a":2,"ex":"전제는 맞고 결론이 틀린 주장이다 — 리뷰에서 다루기 까다로운 종류다.\n개념: 최소화가 보호 수단이 아니라는 말은 옳다. 하지만 보안은 대개 <b>가능·불가능이 아니라 비용</b>의 문제다. 주석과 디렉터리 구조까지 그대로 딸려 나가는 것은 최소화된 코드를 읽는 것과 전혀 다른 이야기다.\n실무: 반박할 때는 원리가 아니라 <b>실제로 무엇이 더 노출되는지</b> 를 나열하는 편이 설득력 있다."},{"t":"choice","k":"인라인된 칸을 되살린다","cat":"internals","q":"인라인되어 사라진 함수가 스택 트레이스에 다시 나타나게 하려면 무엇이 있어야 하는가?","code":"readelf 로 디버그 정보를 들여다보면\n\n  DW_TAG_subprogram          compute\n    DW_TAG_inlined_subroutine  add     ← 여기에 펼쳤다는 기록\n    DW_TAG_inlined_subroutine  add","o":["인라인을 끈 빌드를 따로 만드는 방법뿐이다","실행 중에 호출 스택을 별도로 기록하는 계측 코드가 필요하다","함수 이름 심볼만 남아 있으면 되므로 심볼을 떼지 않는 것으로 충분하다","컴파일러가 남긴 인라인 기록이다 — 코드에는 칸이 없지만 표에 '이 주소는 원래 add 를 펼친 자리' 라고 적혀 있어 도구가 되살려 보여 준다"],"a":3,"ex":"실제로 이 예제에서 <code>add</code> 는 두 번 펼쳐졌고, 기록도 두 개 남았다.\n개념: 여기서 이 단원의 주제가 한 번 더 확인된다 — <b>결과물은 원본을 잃지만 표는 잃지 않는다</b>. 되짚기는 언제나 표가 얼마나 자세한지에 달려 있다.\n실무: 이 기록이 있으면 심볼라이저가 한 주소를 여러 줄의 스택으로 펼쳐 준다. 없으면 인라인한 쪽 함수만 보이고, 실제로 터진 자리는 영영 보이지 않는다."}],"th":{"sum":"컴파일과 번들링은 <b>사람이 읽던 것을 기계가 읽을 것으로 바꾸는 일</b>입니다. 그러면 문제가 터졌을 때 되짚을 길이 사라지죠. 그래서 컴파일러는 결과물과 <b>별도로 대응표</b>를 남깁니다 — 네이티브 쪽의 디버그 정보와 웹 쪽의 소스맵이 그것입니다.","body":[{"h":"왜 읽을 수 없게 되는가","t":"이름은 짧아지고(<code>userCount</code> → <code>a</code>), 함수는 <b>호출한 자리에 통째로 펼쳐지고</b>, 줄은 합쳐지고 순서까지 바뀝니다. 남은 것은 '잘 도는 코드' 지 '읽을 수 있는 코드' 가 아니에요. 스택 트레이스에 <code>a.js:1:24817</code> 만 찍히는 이유가 이것입니다."},{"h":"결과물이 아니라 옆에 표를 둔다","t":"해결책은 결과물을 되돌리는 것이 아니라 <b>변환하면서 대응표를 같이 적어 두는 것</b>입니다. '결과물의 이 위치는 원본의 저 줄 저 칸' 이라는 기록이죠. 네이티브에서는 <b>DWARF 같은 디버그 섹션</b>이, 웹에서는 <b>.map 파일</b>이 그 표입니다."},{"h":"표를 남겨도 코드는 그대로다","t":"많이 하는 오해가 '디버그 정보를 넣으면 느려진다' 는 것입니다. 실제로는 <b>실행 파일이 커질 뿐 기계어는 한 바이트도 달라지지 않아요</b>. 느려지는 것은 최적화를 끄는 쪽이고, 그것은 별개의 선택입니다. 그래서 <b>최적화는 켜고 디버그 정보도 넣는</b> 조합이 릴리스 빌드의 기본입니다."},{"h":"표는 아무에게나 주면 안 된다","t":"소스맵에는 <b>원본 소스가 통째로 들어 있을 수 있습니다</b>. 그대로 배포하면 최소화한 의미가 없어지죠. 그래서 표는 만들되 <b>공개 경로가 아니라 오류 수집 도구에만</b> 올립니다. 네이티브 쪽도 같습니다 — 심볼을 떼어 배포하고, 떼어 낸 심볼은 따로 보관합니다."}],"code":{"t":"같은 실행 파일, 다른 읽을거리","c":"gcc -O2      t.c -o no_g      →  16000 바이트\ngcc -O2 -g   t.c -o with_g    →  18496 바이트\n\n  기계어(.text) 를 바이트 단위로 비교하면?      완전히 동일\n  늘어난 2496 바이트는 전부 .debug_* 섹션\n\nstrip with_g                  →  14472 바이트\n\n  기계어는 여전히 동일\n  사라진 것은 '이 주소가 main 이다' 라는 이름표뿐\n  그래서 디스어셈블하면 main 자리가 그냥 .text 로 보인다"},"key":["최적화·미니파이는 원본과의 대응을 지운다","컴파일러는 결과물 옆에 대응표를 따로 남긴다","디버그 정보는 파일을 키울 뿐 기계어를 바꾸지 않는다","strip 은 이름을 떼는 것이지 코드를 바꾸는 것이 아니다","소스맵과 심볼은 공개 배포가 아니라 오류 수집 쪽에 올린다"]}}],"ord":7},{"t":"최적화의 뼈대 — SSA 와 죽은 코드","g":"","l":[{"t":"이름 하나에 정의 하나 I","q":[{"t":"choice","k":"번호를 붙이는 이유","cat":"internals","q":"SSA 로 바꾸면 <code>w = x + y</code> 의 <code>x</code> 를 찾는 일이 어떻게 달라지는가?","code":"원본 : = x 1 · + z x y · = x 10 · + w x y\nSSA  : = x_1 1 · + z_1 x_1 y_1 · = x_2 10 · + w_1 x_2 y_1","o":["이름에 어느 정의인지가 적혀 있어 지도에서 한 번 찾으면 끝난다 — 흐름을 거슬러 올라갈 필요가 없다고 볼 수 있다","달라지지 않는다 — 이름만 길어질 뿐이다","정의를 못 찾게 되므로 별도의 표를 따로 만들어 관리해야 한다는 부담이 생긴다 이름 번호는 최적화용이라 정의를 찾는 데는 도움이 되지 않는다.","번호가 큰 쪽을 고르면 되므로 마지막 대입을 쓴다"],"a":0,"ex":"실행해 확인했다 — <code>w_1</code> 의 피연산자 <code>x_2</code> 를 찾으니 <code>= x_2 10</code> 이 바로 나온다.\n개념: '정의-사용 사슬(def-use chain)' 을 만드는 비용이 거의 사라진다. 최적화 패스 대부분이 이 사슬을 필요로 하므로, SSA 는 <b>한 번 투자해 여러 패스를 싸게 만드는</b> 표현이다.\n실무: LLVM·GCC·V8·JVM 의 최적화 계층이 모두 SSA 나 그 변형 위에서 돈다. 컴파일러 IR 을 읽을 때 번호가 붙어 있으면 그것이 SSA 다."},{"t":"choice","k":"몇 개로 줄었나","cat":"perf","q":"아래 SSA 코드에 상수 전파와 죽은 코드 제거를 적용하면 명령이 몇 개 남는가?","code":"= x_1 1 · = y_1 2 · + z_1 x_1 y_1\n= x_2 10 · + w_1 x_2 y_1 · + r_1 z_1 w_1 · ret r_1","o":["4개 — 상수 대입 네 개가 남는다","2개 — = r_1 15 와 ret r_1 만 남는다","1개 — ret 만 남는다","7개 — 상수 전파는 명령을 줄이지 않기 때문이다"],"a":1,"ex":"실행해 확인했다 — 7개에서 2개로 줄었다.\n개념: 모든 피연산자가 상수라 <code>z_1 = 3</code>, <code>w_1 = 12</code>, <code>r_1 = 15</code> 로 접히고, 그러고 나면 <code>x_1</code>·<code>y_1</code>·<code>z_1</code>·<code>x_2</code>·<code>w_1</code> 이 아무 데서도 안 쓰인다.\n실무: 사람이 이렇게 쓰지는 않지만, 인라인·매크로 전개·상수 인자 전달 뒤에는 이런 코드가 흔하게 생긴다. 그래서 인라인 뒤에 이 두 패스를 다시 돌린다."},{"t":"choice","k":"한 바퀴로는 부족하다","cat":"internals","q":"죽은 코드 제거를 한 번만 돌리면 왜 부족한가?","code":"+ w_1 x_2 y_1     ← w_1 을 지우면\n= x_2 10          ← x_2 도 이제 안 쓰인다","o":["한 번이면 충분하다","지운 명령을 되살려야 하는 경우가 있기 때문이다","명령을 지우면 그 명령이 쓰던 값들이 <b>새로 죽기</b> 때문이다. 변화가 없을 때까지 되풀이해야 한다","phi 명령은 한 번에 못 지우기 때문이다"],"a":2,"ex":"실제로 되풀이하도록 구현하니 7개가 2개까지 줄었다. 한 바퀴만 돌리면 중간에서 멈춘다.\n개념: 이런 '변화가 없을 때까지' 되풀이하는 계산을 고정점 반복이라고 한다. 데이터 흐름 분석 대부분이 같은 모양이다.\n실무: 반복 횟수에 상한을 두지 않으면 버그가 있을 때 컴파일이 안 끝난다. 실제 컴파일러도 상한을 두고, 넘으면 경고를 남긴다."},{"t":"choice","k":"합류점에서","cat":"internals","q":"아래 코드를 SSA 로 바꿀 때 합류점에 무엇이 필요한가?","code":"if (c) { x = 1 } else { x = 2 }\nprint x","o":["아무것도 필요 없다","x 를 SSA 로 바꾸지 않고 원래 이름으로 남겨 둔다","if 를 없애고 두 갈래를 모두 계산한 뒤 고르면 된다","x_3 = phi(x_1, x_2) — 어느 갈래에서 왔든 그 값을 하나의 이름으로 가리키는 표기가 필요하다고 분명히 정리할 수 있다"],"a":3,"ex":"SSA 를 완성하려면 phi 가 반드시 있어야 한다.\n개념: <code>x_2</code> 를 쓰면 else 갈래로 갔을 때만 맞고, then 갈래에서는 틀린다. 그래서 '이 지점에서 이름이 갈라졌다' 는 사실을 표기로 남긴다.\n실무: phi 를 어디에 넣어야 하는지는 지배 경계(dominance frontier)로 계산한다. 필요한 곳에만 넣지 않으면 최적화가 잘못되거나, 너무 많이 넣으면 코드가 커진다."}],"th":{"sum":"이름 하나에 대입을 한 번만 하도록 고쳐 쓰면 '이 값이 어디서 왔나' 가 이름만으로 정해진다. 최적화 대부분이 그 위에서 쉬워진다.","body":[{"t":"같은 이름에 여러 번 대입하면 <code>w = x + y</code> 의 <code>x</code> 가 <b>어느 대입에서 온 것인지</b> 알려면 앞으로 거슬러 올라가며 흐름을 따져야 한다. 분기가 섞이면 이 추적이 금방 복잡해진다."},{"t":"SSA(정적 단일 배정)는 대입할 때마다 이름에 번호를 새로 붙인다. <code>x_1</code>, <code>x_2</code> 처럼. 그러면 정의가 이름당 정확히 하나라서 <b>정의 찾기가 지도 조회 한 번</b>이 된다."},{"t":"분기가 합류하는 지점에서는 어느 쪽에서 왔는지에 따라 값이 다르다. 그래서 <code>x_3 = phi(x_1, x_2)</code> 라는 가짜 명령을 넣어 '어느 쪽에서 왔든 그 값' 을 하나의 이름으로 가리킨다. phi 는 실제 기계 명령이 아니라 <b>코드 생성 직전에 이동 명령으로 풀린다</b>."},{"t":"SSA 위에서는 상수 전파·죽은 코드 제거·공통 부분식 제거가 단순해진다. 특히 '한 번도 안 쓰인 이름' 을 세는 것만으로 죽은 코드를 찾을 수 있는데, 지우고 나면 또 안 쓰이는 것이 생기므로 <b>변화가 없을 때까지 되풀이</b>한다."}],"code":{"c":"원본                SSA\n= x 1               = x_1 1\n= y 2               = y_1 2\n+ z x y             + z_1 x_1 y_1\n= x 10              = x_2 10        ← 새 이름\n+ w x y             + w_1 x_2 y_1   ← 어느 x 인지 이름에 적혀 있다"},"key":["SSA 는 이름마다 정의가 하나뿐이라 정의 추적이 조회 한 번이 된다","합류점에는 phi 를 넣고, 코드 생성 직전에 이동 명령으로 푼다","죽은 코드 제거는 지우고 나면 또 생기므로 변화가 없을 때까지 되풀이한다","phi 는 실제 명령이 아니라 분석을 위한 표기다"]}},{"t":"이름 하나에 정의 하나 II","q":[{"t":"choice","k":"phi 는 무엇이 되는가","cat":"internals","q":"phi 명령은 실제 기계어에서 어떻게 되는가?","code":"L3:  x_3 = phi(x_1 from L1, x_2 from L2)","o":["기계 명령이 아니다고 실무에서는 새겨 두어야 한다","메모리 접근 명령으로 바뀌어 스택에 저장된다고 여러 자료를 놓고 보면 어느 정도는 그대로 정리할 수 있다","그대로 phi 명령으로 컴파일되며 CPU 가 처리한다고 늘 짚어 두어야 한다","조건 분기 명령 하나로 바뀐다고 지금 다루는 맥락에서는 분명히 어렵지 않게 정리할 수 있다"],"a":0,"ex":"phi 는 <b>분석을 위한 표기</b>다.\n개념: L1 끝에 <code>x_3 ← x_1</code>, L2 끝에 <code>x_3 ← x_2</code> 를 넣으면 같은 뜻이 된다. 이 과정을 'SSA 해체' 라고 한다.\n실무: 해체할 때 여러 phi 가 서로를 참조하면 이동 명령의 순서를 잘못 잡아 값이 덮이는 고전적인 버그가 생긴다(swap 문제). 임시 변수를 하나 두어 푼다.\n왜 그 답인가: 코드 생성 직전에 <b>각 앞선 블록 끝에 이동 명령</b>을 넣는 방식으로 풀린다"},{"t":"choice","k":"루프 안에서는","q":"<code>for (i = 0; i &lt; n; i++) s += i;</code> 를 SSA 로 바꾸면 루프 머리에 무엇이 생기는가?","code":"loop:\n  i_2 = phi(i_1 from 진입, i_3 from 루프끝)\n  s_2 = phi(s_1 from 진입, s_3 from 루프끝)","o":["아무것도 안 생긴다 — 루프는 분기가 아니다","변수마다 phi 가 하나씩 생긴다 — 처음 들어올 때의 값과 한 바퀴 돈 뒤의 값 중 하나이기 때문이다","루프 안에서는 SSA 를 쓸 수 없어 원래 이름을 그대로 유지하게 된다 루프는 값이 계속 바뀌므로 한 번만 배정한다는 규칙과 맞지 않는다.","phi 대신 루프 카운터 전용 명령이 생긴다"],"a":1,"ex":"루프 머리는 두 곳에서 들어오는 합류점이다.\n개념: 루프의 phi 를 보면 <b>무엇이 루프를 거치며 변하는지</b>가 한눈에 보인다. 반대로 phi 에 안 걸린 값은 루프 안에서 안 변하므로 밖으로 끌어낼 수 있다.\n실무: 루프 불변 코드 이동·귀납 변수 인식·자동 벡터화가 전부 이 정보에서 출발한다. SSA 가 루프 최적화의 기반이 되는 이유다."},{"t":"choice","k":"메모리는 어떻게 하나","cat":"internals","q":"포인터로 접근하는 메모리는 SSA 로 그대로 다루기 어렵다. 컴파일러는 어떻게 하는가?","code":"int a; int *p = &a;\n*p = 5;      /* 어느 이름을 새로 만들어야 하나? */","o":["메모리도 이름마다 번호를 붙여 레지스터와 완전히 같은 방식으로 다룬다 주소를 넘기든 넘기지 않든 같은 규칙으로 다루면 되기 때문이라고 실무에서는 비교적 자주 짚어 두어야 한다","모든 메모리 접근을 함수 호출로 바꿔 처리한다","주소를 넘기지 않는 지역 변수는 레지스터 값으로 승격해 SSA 로 다루고, 나머지 메모리는 별도의 별칭 분석으로 다룬다","포인터가 있으면 SSA 를 포기하고 원래 표현으로 돌아간다"],"a":2,"ex":"메모리는 '어느 이름을 바꾸는지' 가 컴파일 시점에 안 정해질 수 있다.\n개념: 그래서 컴파일러는 먼저 <b>주소가 새어 나가지 않는 지역 변수</b>를 찾아 레지스터로 승격한다(LLVM 의 mem2reg). 그러면 그것들은 완전한 SSA 로 다룰 수 있다.\n실무: 지역 변수의 주소를 함부로 넘기면 이 승격이 막혀 최적화가 통째로 줄어든다. C 에서 불필요한 <code>&amp;</code> 를 줄이는 것이 실제로 성능에 영향을 주는 이유다."},{"t":"choice","k":"레지스터 할당과의 관계","q":"SSA 는 이름을 계속 늘리는데, 실제 레지스터는 십수 개뿐이다. 모순 아닌가?","code":"x_1, x_2, x_3, ... 수백 개의 이름\nCPU 범용 레지스터: 16개 남짓","o":["이름 수를 16개 이하로 유지하도록 SSA 변환 자체를 제한한다고 흔히 볼 수 있다","SSA 이름 하나당 레지스터 하나가 필요하므로 결국 모두 메모리에 둔다고 차근차근 이해할 수 있다","모순이 맞다 — 그래서 SSA 는 인터프리터에서만 쓴다고 기본이 되는 내용이라 어느 정도는 새겨 두어야 한다","생존 구간이 안 겹치면 같은 레지스터를 쓴다고 꽤 알려져 있다"],"a":3,"ex":"이름의 개수가 아니라 <b>동시에 살아 있는 값의 개수</b>가 문제다.\n개념: SSA 형태에서는 생존 구간의 겹침 그래프가 특별한 성질(현 그래프)을 가져서, 일반적인 그래프 색칠보다 쉽게 최적 색칠을 구할 수 있다는 것이 알려져 있다.\n실무: 그래서 최신 컴파일러는 SSA 를 해체하기 <b>전에</b> 레지스터 할당을 한다. SSA 가 최적화만이 아니라 코드 생성 자체를 돕는다.\n왜 그 답인가: 레지스터 할당이 그 겹침을 보고 배정한다"}],"th":{"sum":"이름 하나에 대입을 한 번만 하도록 고쳐 쓰면 '이 값이 어디서 왔나' 가 이름만으로 정해진다. 최적화 대부분이 그 위에서 쉬워진다.","body":[{"t":"같은 이름에 여러 번 대입하면 <code>w = x + y</code> 의 <code>x</code> 가 <b>어느 대입에서 온 것인지</b> 알려면 앞으로 거슬러 올라가며 흐름을 따져야 한다. 분기가 섞이면 이 추적이 금방 복잡해진다."},{"t":"SSA(정적 단일 배정)는 대입할 때마다 이름에 번호를 새로 붙인다. <code>x_1</code>, <code>x_2</code> 처럼. 그러면 정의가 이름당 정확히 하나라서 <b>정의 찾기가 지도 조회 한 번</b>이 된다."},{"t":"분기가 합류하는 지점에서는 어느 쪽에서 왔는지에 따라 값이 다르다. 그래서 <code>x_3 = phi(x_1, x_2)</code> 라는 가짜 명령을 넣어 '어느 쪽에서 왔든 그 값' 을 하나의 이름으로 가리킨다. phi 는 실제 기계 명령이 아니라 <b>코드 생성 직전에 이동 명령으로 풀린다</b>."},{"t":"SSA 위에서는 상수 전파·죽은 코드 제거·공통 부분식 제거가 단순해진다. 특히 '한 번도 안 쓰인 이름' 을 세는 것만으로 죽은 코드를 찾을 수 있는데, 지우고 나면 또 안 쓰이는 것이 생기므로 <b>변화가 없을 때까지 되풀이</b>한다."}],"code":{"c":"원본                SSA\n= x 1               = x_1 1\n= y 2               = y_1 2\n+ z x y             + z_1 x_1 y_1\n= x 10              = x_2 10        ← 새 이름\n+ w x y             + w_1 x_2 y_1   ← 어느 x 인지 이름에 적혀 있다"},"key":["SSA 는 이름마다 정의가 하나뿐이라 정의 추적이 조회 한 번이 된다","합류점에는 phi 를 넣고, 코드 생성 직전에 이동 명령으로 푼다","죽은 코드 제거는 지우고 나면 또 생기므로 변화가 없을 때까지 되풀이한다","phi 는 실제 명령이 아니라 분석을 위한 표기다"]}},{"t":"이름 하나에 정의 하나 III","q":[{"t":"choice","k":"공통 부분식","cat":"perf","q":"SSA 에서 공통 부분식 제거가 쉬워지는 이유는?","code":"+ t_1 a_1 b_1\n... \n+ t_2 a_1 b_1     ← 같은 계산","o":["피연산자 이름이 같으면 값도 반드시 같다는 것이 보장되므로, 연산자와 피연산자 이름만 비교하면 된다","SSA 는 중복을 자동으로 제거해 주므로 별도의 패스가 필요 없다","SSA 에서는 같은 연산이 두 번 나올 수 없기 때문이다","이름이 번호로 되어 있어 정렬이 빠르기 때문이다"],"a":0,"ex":"이름이 곧 값이라는 성질이 핵심이다.\n개념: 원래 표현에서는 <code>a + b</code> 를 두 번 봐도 그 사이에 <code>a</code> 가 바뀌었는지 확인해야 한다. SSA 에서는 <code>a_1</code> 이면 언제나 같은 값이다.\n실무: 그래서 '(연산자, 피연산자들) → 이름' 지도 하나로 구현된다. 다만 나눗셈처럼 예외를 낼 수 있는 연산은 위치를 함부로 옮기면 안 된다."},{"t":"choice","k":"부수효과가 있으면","cat":"debug","q":"상수 전파와 죽은 코드 제거를 적용할 때 함수 호출은 어떻게 다뤄야 하는가?","code":"= t_1 call(log, \"보냄\")\n/* t_1 은 아무 데서도 안 쓰인다 */","o":["인자가 상수면 지울 수 있다","결과를 안 쓰더라도 부수효과가 있으면 지우면 안 된다 — 부수효과가 없다고 확인된 함수만 지울 수 있다고 이 단원에서는 분명히 이해할 수 있다","함수 호출은 어떤 경우에도 지울 수 없으므로 그대로 두어야 한다 호출한 결과를 쓰지 않더라도 지우면 위험하다고 보기 때문이라고 이 단원에서는 실제로 무리 없이 할 수 있다","안 쓰이는 값이므로 무조건 지운다"],"a":1,"ex":"죽은 코드 제거의 정확성이 걸린 지점이다.\n개념: '값을 안 쓴다' 와 '해도 안 해도 된다' 는 다르다. 로그·입출력·전역 변수 변경은 결과를 안 써도 반드시 일어나야 한다.\n실무: 그래서 컴파일러는 함수에 <b>순수하다</b>는 표시(GCC 의 <code>__attribute__((pure))</code> 등)를 붙일 수 있게 해 둔다. 잘못 붙이면 호출이 사라지는 무서운 버그가 된다."},{"t":"choice","k":"왜 정적인가","q":"SSA 의 '정적 단일 배정' 에서 <b>정적</b>이 뜻하는 것은?","code":"loop: i_2 = phi(...); + i_3 i_2 1; goto loop","o":["값이 실행 중에는 절대로 바뀌지 않는다는 뜻이라고 실제로 곰곰이 설명할 수 있다","컴파일 시점에 값이 이미 정해져 있다는 뜻이다","소스에 대입이 한 곳뿐이라는 뜻이다","정적 타입을 쓰는 언어에서만 쓸 수가 있다는 뜻으로 새기면 된다고 분명히 있는 그대로 짚어 두어야 한다"],"a":2,"ex":"'정적' 은 코드 위의 이야기이지 실행 중의 이야기가 아니다.\n개념: <code>i_3 = i_2 + 1</code> 이라는 명령은 코드에 하나뿐이고, 루프가 천 번 돌면 천 번 실행된다. 그때마다 <code>i_3</code> 의 값은 다르다.\n실무: 이 구분을 놓치면 'SSA 에서는 변수가 안 변한다' 는 오해를 하게 되고, 루프에서 phi 가 왜 필요한지가 설명되지 않는다.\n왜 그 답인가: 루프를 돌면 실행 중에는 여러 번 대입되지만 그것은 상관없다"},{"t":"choice","k":"무엇이 안 쉬워지나","q":"SSA 로 바꾼다고 저절로 쉬워지지 <b>않는</b> 것은?","code":"// 후보: 정의 찾기 / 죽은 코드 제거 / 별칭 분석 / 공통 부분식","o":["공통 부분식 제거","죽은 코드 제거 — SSA 에서 오히려 어려워진다","정의 찾기 — 여전히 흐름을 거슬러 올라가야 한다","별칭 분석 — 두 포인터가 같은 곳을 가리키는지는 이름 번호와 무관한 문제라고 차근차근 알아 두어야 한다"],"a":3,"ex":"SSA 가 해결하는 것은 <b>이름이 가리키는 값의 모호함</b>이다.\n개념: 포인터가 무엇을 가리키는지는 그와 별개의 어려운 문제이고, 일반적으로는 결정 불가능하다. 그래서 별도의 근사 분석을 쓴다.\n실무: C 의 <code>restrict</code> 나 Rust 의 소유권 규칙이 이 분석을 돕기 위한 장치다. 언어가 별칭을 제한할수록 컴파일러가 더 많이 할 수 있다."}],"th":{"sum":"이름 하나에 대입을 한 번만 하도록 고쳐 쓰면 '이 값이 어디서 왔나' 가 이름만으로 정해진다. 최적화 대부분이 그 위에서 쉬워진다.","body":[{"t":"같은 이름에 여러 번 대입하면 <code>w = x + y</code> 의 <code>x</code> 가 <b>어느 대입에서 온 것인지</b> 알려면 앞으로 거슬러 올라가며 흐름을 따져야 한다. 분기가 섞이면 이 추적이 금방 복잡해진다."},{"t":"SSA(정적 단일 배정)는 대입할 때마다 이름에 번호를 새로 붙인다. <code>x_1</code>, <code>x_2</code> 처럼. 그러면 정의가 이름당 정확히 하나라서 <b>정의 찾기가 지도 조회 한 번</b>이 된다."},{"t":"분기가 합류하는 지점에서는 어느 쪽에서 왔는지에 따라 값이 다르다. 그래서 <code>x_3 = phi(x_1, x_2)</code> 라는 가짜 명령을 넣어 '어느 쪽에서 왔든 그 값' 을 하나의 이름으로 가리킨다. phi 는 실제 기계 명령이 아니라 <b>코드 생성 직전에 이동 명령으로 풀린다</b>."},{"t":"SSA 위에서는 상수 전파·죽은 코드 제거·공통 부분식 제거가 단순해진다. 특히 '한 번도 안 쓰인 이름' 을 세는 것만으로 죽은 코드를 찾을 수 있는데, 지우고 나면 또 안 쓰이는 것이 생기므로 <b>변화가 없을 때까지 되풀이</b>한다."}],"code":{"c":"원본                SSA\n= x 1               = x_1 1\n= y 2               = y_1 2\n+ z x y             + z_1 x_1 y_1\n= x 10              = x_2 10        ← 새 이름\n+ w x y             + w_1 x_2 y_1   ← 어느 x 인지 이름에 적혀 있다"},"key":["SSA 는 이름마다 정의가 하나뿐이라 정의 추적이 조회 한 번이 된다","합류점에는 phi 를 넣고, 코드 생성 직전에 이동 명령으로 푼다","죽은 코드 제거는 지우고 나면 또 생기므로 변화가 없을 때까지 되풀이한다","phi 는 실제 명령이 아니라 분석을 위한 표기다"]}},{"t":"이름 하나에 정의 하나 IV","q":[{"t":"choice","k":"IR 을 읽을 때","cat":"debug","q":"LLVM IR 을 읽는데 <code>%3 = add i32 %1, %2</code> 처럼 번호가 붙어 있다. 이것으로 무엇을 알 수 있는가?","code":"%3 = add i32 %1, %2\n%4 = mul i32 %3, 2","o":["%3 을 정의하는 곳이 함수 안에 딱 하나이므로, %3 을 쓰는 자리를 전부 찾으면 그 값의 쓰임이 완전히 파악된다","번호가 큰 것이 먼저 계산된다","번호는 레지스터 번호이므로 실제 하드웨어 레지스터를 뜻한다 그래서 번호가 큰 함수는 레지스터가 모자라 스필이 일어난이라고 늘 곰곰이 새겨 두어야 한다","번호는 실행 순서일 뿐 정의와는 무관하다"],"a":0,"ex":"LLVM IR 은 SSA 형태다.\n개념: 그래서 IR 을 손으로 따라갈 때도 번호만 따라가면 값의 출처가 확정된다. 실제로 최적화 결과를 확인할 때 가장 유용한 성질이다.\n실무: <code>clang -O2 -S -emit-llvm</code> 로 IR 을 뽑아 보면 자기 코드가 어떻게 접히고 지워졌는지 보인다. 성능 의문이 생겼을 때 추측보다 빠르다."},{"t":"choice","k":"변환 비용","cat":"perf","q":"SSA 변환 자체의 비용은 어떻게 다뤄야 하는가?","code":"// 변환 → 여러 최적화 패스 → 해체","o":["변환은 공짜이므로 아무 때나 해도 된다","한 번 변환하고 여러 패스가 그 위에서 돌게 한다 — 패스마다 다시 만들면 이득이 사라진다고 새겨 두어야 한다","패스마다 새로 변환해야 정확하다","변환 비용이 너무 커서 실제 컴파일러에서는 거의 쓰지 않는다 변환에 드는 시간이 최적화로 버는 시간보다 크기 때문이라고 이 단원에서는 곰곰이 볼 수 있다"],"a":1,"ex":"SSA 는 한 번 만들어 오래 쓰는 표현이다.\n개념: 각 패스가 SSA 형태를 <b>유지하면서</b> 코드를 고치도록 만드는 것이 핵심이다. 그래야 다시 만들 필요가 없다.\n실무: 그래서 최적화 패스를 새로 쓸 때 'SSA 를 깨지 않았는가' 를 검사하는 검증기(LLVM 의 verifier)를 함께 돌린다. 깨진 IR 은 뒤쪽 패스에서 이상한 방식으로 터진다."},{"t":"choice","k":"무엇을 먼저 볼까","cat":"debug","q":"최적화를 켰더니 결과가 달라졌다. 어디를 먼저 의심하는가?","code":"-O0 결과: 3.0000001\n-O2 결과: 3.0","o":["레지스터 할당 문제이므로 변수 수를 줄인다","죽은 코드 제거가 원인이므로 그 패스만 끈다","부동소수점 재결합이나 부수효과 가정처럼 최적화가 바꿔도 된다고 가정한 것을 먼저 본다 — 순서를 바꿔도 되는지가 흔한 다툼 지점이다","SSA 변환 쪽에 버그가 있는 것이므로 컴파일러 버전을 올려 본다 최적화 패스는 의미를 바꾸지 않도록 검증되어 있기 때문이다."],"a":2,"ex":"이 단원의 앞부분에서 상수 접기가 결과를 바꿀 수 있다는 것을 이미 봤다.\n개념: 최적화가 결과를 바꾼다면 대개 <b>컴파일러가 허용된 자유를 쓴 것</b>이지 버그가 아니다. 실수 연산 순서, 정의되지 않은 동작, 부수효과 없음 표시가 흔한 원인이다.\n실무: <code>-ffast-math</code> 같은 옵션이 켜져 있는지부터 본다. 그다음 정의되지 않은 동작을 <code>-fsanitize=undefined</code> 로 찾는다 — 여기서 걸리는 경우가 많다."},{"t":"choice","k":"직접 만든다면","cat":"design","q":"작은 언어의 컴파일러를 만들면서 SSA 를 넣을지 고민한다. 언제 값어치가 있는가?","code":"// 후보: 인터프리터만 만든다 / 최적화 없이 코드 생성만 한다 / 여러 최적화를 넣는다","o":["언어에 루프가 있으면 넣을 수 없다","인터프리터에도 반드시 필요하다","언제나 넣어야 한다","최적화를 두 개 이상 넣을 계획이면 값어치가 있다 — 하나뿐이면 변환 비용과 phi 처리가 이득보다 크다"],"a":3,"ex":"SSA 는 목적이 아니라 <b>여러 패스를 싸게 만드는 투자</b>다.\n개념: 상수 접기 하나만 할 거라면 트리 위에서 바로 하는 편이 짧고 빠르다. phi 삽입과 해체를 정확히 구현하는 것은 생각보다 까다롭다.\n실무: 앞 단계에서 만든 작은 언어처럼 트리에서 바로 코드로 내리는 구조라면 SSA 없이 시작하고, 최적화가 늘어나기 시작할 때 도입하는 순서가 자연스럽다."}],"th":{"sum":"이름 하나에 대입을 한 번만 하도록 고쳐 쓰면 '이 값이 어디서 왔나' 가 이름만으로 정해진다. 최적화 대부분이 그 위에서 쉬워진다.","body":[{"t":"같은 이름에 여러 번 대입하면 <code>w = x + y</code> 의 <code>x</code> 가 <b>어느 대입에서 온 것인지</b> 알려면 앞으로 거슬러 올라가며 흐름을 따져야 한다. 분기가 섞이면 이 추적이 금방 복잡해진다."},{"t":"SSA(정적 단일 배정)는 대입할 때마다 이름에 번호를 새로 붙인다. <code>x_1</code>, <code>x_2</code> 처럼. 그러면 정의가 이름당 정확히 하나라서 <b>정의 찾기가 지도 조회 한 번</b>이 된다."},{"t":"분기가 합류하는 지점에서는 어느 쪽에서 왔는지에 따라 값이 다르다. 그래서 <code>x_3 = phi(x_1, x_2)</code> 라는 가짜 명령을 넣어 '어느 쪽에서 왔든 그 값' 을 하나의 이름으로 가리킨다. phi 는 실제 기계 명령이 아니라 <b>코드 생성 직전에 이동 명령으로 풀린다</b>."},{"t":"SSA 위에서는 상수 전파·죽은 코드 제거·공통 부분식 제거가 단순해진다. 특히 '한 번도 안 쓰인 이름' 을 세는 것만으로 죽은 코드를 찾을 수 있는데, 지우고 나면 또 안 쓰이는 것이 생기므로 <b>변화가 없을 때까지 되풀이</b>한다."}],"code":{"c":"원본                SSA\n= x 1               = x_1 1\n= y 2               = y_1 2\n+ z x y             + z_1 x_1 y_1\n= x 10              = x_2 10        ← 새 이름\n+ w x y             + w_1 x_2 y_1   ← 어느 x 인지 이름에 적혀 있다"},"key":["SSA 는 이름마다 정의가 하나뿐이라 정의 추적이 조회 한 번이 된다","합류점에는 phi 를 넣고, 코드 생성 직전에 이동 명령으로 푼다","죽은 코드 제거는 지우고 나면 또 생기므로 변화가 없을 때까지 되풀이한다","phi 는 실제 명령이 아니라 분석을 위한 표기다"]}}],"ord":8},{"t":"단답으로 확인하기 — 단계 이름과 표현 형식","l":[{"t":"앞단의 단계와 이름","xp":60,"th":{"sum":"컴파일러 앞단은 **글자 → 토큰 → 트리 → 이름**의 네 걸음이다. 각 걸음의 이름을 알면 오류 메시지가 어디서 왔는지 바로 짚인다.","body":[{"h":"나누고 세우기","t":"<b>어휘 분석</b>은 글자를 토큰으로 나누며 <b>최장 일치</b>가 원칙이고, 공백·주석을 버리는 대신 <b>줄·칸 정보</b>를 붙인다 — 오류 밑줄이 엉뚱한 자리에 그이면 여기가 범인이다. <b>구문 분석</b>은 토큰을 문법에 따라 트리로 세우며 우선순위와 결합 방향을 정한다. 결과물인 <b>AST</b> 는 군더더기를 뺀 트리라, 이후의 모든 단계와 린터·포매터가 이 위에서 돈다."},{"h":"이름과 문법을 적어 두기","t":"<b>심볼 테이블</b>은 이름이 가리키는 것을 모아 둔 표이고, 렉시컬 스코프를 구현하려면 <b>스택으로 쌓아야</b> 한다 — 표 하나로 두면 안쪽 선언이 바깥 이름을 영구히 덮는다. 문법은 <b>BNF</b> 로 적는데, 규칙 맨 앞에 자기 자신이 나오는 <b>좌재귀</b>는 재귀 하강 파서를 무한 재귀에 빠뜨리므로 반복 형태로 고쳐 쓴다 — 그러면 좌결합도 함께 얻는다."}],"code":{"c":"expr := term (('+' | '-') term)*   // 좌재귀를 반복으로\nscope.push(new Map())              // 블록마다 얹고 벗긴다\n토큰마다 {line, col} 을 함께 들고 다닌다","cap":"각 걸음의 이름이 곧 지도다"},"key":["어휘 분석은 최장 일치","AST 위에서 모든 단계가 돈다","심볼 테이블은 스택으로","좌재귀는 반복으로 고친다"]},"q":[{"t":"input","cat":"internals","k":"글자를 토큰으로 나누는 단계","q":"소스 코드를 의미 있는 최소 단위인 토큰으로 나누는 단계를 무엇이라 부를까요? (네 글자)","a":["어휘분석","렉싱","lexing","토큰화"],"ex":"이 단계의 원칙은 <b>최장 일치</b>입니다 — <code>==</code> 를 <code>=</code> 둘로 쪼개지 않도록 긴 것부터 맞춰 봅니다.\n개념: 공백과 주석은 대개 여기서 버려지고, 토큰마다 <b>줄·칸 정보</b>를 붙여 둡니다.\n실무: 오류 메시지의 밑줄이 엉뚱한 자리에 그어진다면 이 단계에서 자리 정보를 잘못 붙인 것입니다."},{"t":"input","cat":"internals","k":"토큰을 트리로 세우는 단계","q":"토큰 나열을 문법 규칙에 따라 트리 모양으로 세우는 단계를 무엇이라 부를까요? (네 글자)","a":["구문분석","파싱","parsing","문법분석"],"ex":"연산자 우선순위와 결합 방향이 여기서 정해집니다 — <code>1 - 2 - 3</code> 이 왼쪽부터 묶이는 것도 이 단계의 규칙입니다.\n개념: 문법을 <code>expr := term (('+'|'-') term)*</code> 처럼 <b>반복 형태</b>로 적어 두면 좌결합 코드가 저절로 나옵니다.\n실무: 오류 복구를 넣어야 편집기에서 <b>한 줄이 틀려도 나머지를 계속 분석</b>할 수 있습니다."},{"t":"input","cat":"internals","k":"군더더기를 뺀 나무","q":"구문 분석이 만들어 내는, 괄호나 세미콜론 같은 군더더기를 뺀 트리 구조를 영문 약어 세 글자로 적으세요. (영문 약어)","a":["AST","추상구문트리"],"ex":"Abstract Syntax Tree 입니다. 문법 그대로의 트리(구체 구문 트리)에서 <b>뜻에 필요한 것만</b> 남깁니다.\n개념: 이후의 모든 단계 — 이름 해석·타입 검사·최적화·코드 생성 — 가 이 트리 위에서 돕니다.\n실무: 린터·포매터·코드 변환 도구도 같은 트리를 씁니다. 정규식으로 소스를 고치는 대신 이 트리를 쓰면 문자열 안의 코드까지 잘못 건드리는 일이 없습니다."},{"t":"input","cat":"internals","k":"이름을 모아 두는 표","q":"이름과 그 이름이 가리키는 것(타입·스코프·주소)을 모아 두는 표를 무엇이라 부를까요? (다섯 글자)","a":["심볼테이블","기호표","symbol table","심벌테이블"],"ex":"렉시컬 스코프를 구현하려면 이 표를 <b>스택으로 쌓아야</b> 합니다 — 블록마다 얹고 벗기며, 조회는 안쪽부터 바깥으로 훑습니다.\n개념: 표 하나로 두면 안쪽 선언이 바깥 이름을 영구히 덮어써서 블록을 나가도 지워지지 않습니다.\n실무: 클로저를 지원하려면 블록을 나갈 때 표를 <b>버리지 말고</b> 노드에 매달아 둬야 합니다."},{"t":"input","cat":"internals","k":"문법을 적는 표기법","q":"문맥 자유 문법을 적는 데 널리 쓰이는 표기법을 영문 약어 세 글자로 적으세요. (영문 약어)","a":["BNF","배커스나우어형"],"ex":"Backus–Naur Form 입니다. <code>규칙 ::= 대안 | 대안</code> 꼴로 적고, 반복과 선택을 더한 확장판(EBNF)도 널리 쓰입니다.\n개념: 문법을 이렇게 적어 두면 <b>파서를 자동으로 만들어 내는</b> 도구를 쓸 수 있습니다.\n실무: 언어 명세·설정 파일 형식·프로토콜 문서에서 흔히 만나므로, 읽을 줄만 알아도 규격을 정확히 구현할 수 있습니다."},{"t":"input","cat":"internals","k":"왼쪽부터 묶으려면","q":"재귀 하강 파서에서 좌결합 연산자를 올바르게 처리하려면 재귀 대신 무엇으로 적어야 할까요? (두 글자)","a":["반복","루프","loop","반복문"],"ex":"오른쪽 항을 다시 같은 함수로 읽으면 <code>1-(2-3)</code> 처럼 <b>오른쪽부터</b> 묶입니다. 누적값에 오른쪽 항을 차례로 적용해야 왼쪽부터 묶입니다.\n개념: 반대로 <b>우결합</b> 연산자(<code>**</code>·<code>=</code>)는 재귀로 적는 것이 맞습니다.\n실무: 연산자가 하나뿐인 예제에서는 결합 방향이 결과를 바꾸지 않아, 같은 연산자를 셋 이상 이은 식을 테스트에 꼭 넣어야 합니다."},{"t":"input","cat":"internals","k":"최적화가 지켜야 하는 것","q":"최적화가 바꾸면 안 되는 것은 프로그램의 '___ 가능한 동작' 입니다. 빈칸에 들어갈 말은? (두 글자)","a":["관찰","observable","외부관찰"],"ex":"출력·파일 쓰기·네트워크 호출처럼 <b>밖에서 볼 수 있는</b> 동작만 지키면, 그 외의 순서와 계산은 자유롭게 바꿔도 됩니다.\n개념: 그래서 IR 은 명령마다 <b>부수효과가 있는가</b>를 들고 다녀야 하고, 모르면 보수적으로 '있음' 으로 둡니다.\n실무: 결과를 안 쓰는 함수 호출을 지우는 최적화가 로그와 저장을 함께 지워 버리는 사고가 여기서 납니다."},{"t":"input","cat":"internals","k":"소스와 기계어 사이의 표현","q":"소스 코드와 기계어 사이에 두어 최적화를 적용하는 표현을 영문 약어 두 글자로 적으세요. (영문 약어)","a":["IR","중간표현","intermediate representation"],"ex":"앞단(언어)과 뒷단(기계)을 <b>가운데에서 끊어 주는</b> 층입니다. 언어 m 개와 기계 n 개가 있어도 <code>m + n</code> 개만 만들면 됩니다.\n개념: 이 층이 없으면 <code>m × n</code> 개의 번역기가 필요합니다 — LLVM 이 널리 쓰이는 이유가 이것입니다.\n실무: 최적화 패스는 대부분 이 층에서 돌아, 새 언어를 얹어도 최적화를 그대로 물려받습니다."}]},{"t":"뒷단의 표현과 최적화","xp":60,"th":{"sum":"뒷단은 **가운데 표현(IR)** 을 두고 그 위에서 고친다. 모든 최적화의 전제는 하나 — **관찰 가능한 동작을 바꾸지 않는다**.","body":[{"h":"가운데를 두는 이유","t":"<b>IR</b> 은 앞단(언어)과 뒷단(기계)을 끊어 주는 층이라, 언어 m 개와 기계 n 개가 있어도 <code>m × n</code> 이 아니라 <code>m + n</code> 개만 만들면 된다. <b>SSA</b> 는 변수마다 대입을 한 번만 하도록 이름을 나눠 붙인 형태로, 정의가 하나뿐이라 상수 전파·공통 부분식 제거가 훨씬 간단해진다. <b>JIT</b> 는 실제로 어떤 타입이 오는지 보고 최적화하는 대신 <b>워밍업</b>이 필요하다 — 벤치마크의 첫 몇 초는 버려야 한다."},{"h":"지워도 되는 것과 안 되는 것","t":"<b>DCE</b> 는 결과를 아무도 쓰지 않는 명령을 지우지만, <b>부수효과가 있는 명령</b>은 결과를 안 써도 남겨야 한다 — 로그와 저장이 함께 지워지는 사고가 여기서 난다. <b>TCO</b> 는 마지막 동작이 호출뿐일 때 현재 프레임을 재사용해 재귀를 반복문으로 바꾼다. <b>스택 프레임</b>은 호출마다 쌓이고 반환하면 사라지므로, 지역 변수의 주소를 반환하면 허상 포인터가 된다. 링커의 <b>undefined reference</b> 는 선언은 있고 정의가 없을 때다."}],"code":{"c":"it.eff || used.has(it.dst)      // 부수효과도 살아 있음\nm + n 개의 번역기               // IR 이 있을 때\nφ(x₁, x₂)                       // 갈림길에서 합칠 때","cap":"밖에서 보이는 것만 지키면 된다"},"key":["IR 이 번역기 수를 곱셈에서 덧셈으로","SSA 는 정의가 하나뿐","부수효과 있는 명령은 못 지운다","링크 오류는 정의가 없을 때"]},"q":[{"t":"input","cat":"internals","k":"한 번만 대입하는 형태","q":"모든 변수에 값을 딱 한 번만 대입하도록 이름을 나눠 붙인 중간 표현 형태를 영문 약어 세 글자로 적으세요. (영문 약어)","a":["SSA","정적단일대입"],"ex":"Static Single Assignment 입니다. 값마다 이름이 하나뿐이라 '이 값이 어디서 왔는가' 를 바로 알 수 있습니다.\n개념: 갈림길에서 합쳐질 때는 <code>φ</code>(파이) 노드를 넣어 '어느 쪽에서 왔는지' 를 적어 둡니다.\n실무: 상수 전파·죽은 코드 제거·공통 부분식 제거가 이 형태에서 훨씬 간단해집니다 — 정의가 하나라 따라갈 곳도 하나입니다."},{"t":"input","cat":"internals","k":"호출할 때마다 쌓이는 것","q":"함수를 호출할 때마다 지역 변수와 복귀 주소를 담아 쌓아 올리는 영역을 무엇이라 부를까요? (다섯 글자)","a":["스택프레임","호출프레임","stack frame","활성레코드"],"ex":"호출하면 쌓이고 반환하면 벗겨집니다. 재귀 깊이가 깊으면 이 영역이 넘쳐 <b>스택 오버플로</b>가 납니다.\n개념: 지역 변수의 수명이 함수와 같은 이유가 여기 있습니다 — 반환하면 그 자리가 사라집니다.\n실무: 지역 변수의 주소를 반환하면 이미 사라진 자리를 가리킵니다. 이것이 C 에서 가장 흔한 허상 포인터 사고입니다."},{"t":"input","cat":"internals","k":"정의를 못 찾았을 때","q":"링커가 선언만 있고 정의를 찾지 못한 심볼을 만났을 때 내는 대표적인 오류 메시지는? (영문 두 낱말)","a":["undefined reference","undefinedsymbol","미정의참조","정의되지않은참조"],"ex":"컴파일은 <b>선언만 보고도</b> 되지만, 링크는 <b>정의가 있어야</b> 합니다. 그래서 이 오류는 컴파일이 끝난 뒤에야 나옵니다.\n개념: 심볼 해석은 파일 순서와 무관해야 하므로 '<b>모으고 나서 판정</b>' 하는 두 패스 구조가 필요합니다.\n실무: C++ 에서는 이름 장식(mangling) 때문에 같은 이름이라도 시그니처가 다르면 다른 심볼입니다 — 헤더와 구현의 인자 타입을 먼저 맞춰 보세요."},{"t":"input","cat":"internals","k":"돌면서 번역하기","q":"프로그램이 도는 도중에 자주 쓰이는 부분을 골라 기계어로 번역해 두는 방식을 영문 약어 세 글자로 적으세요. (영문 약어)","a":["JIT","적시컴파일"],"ex":"Just-In-Time 컴파일입니다. <b>실제로 어떤 타입이 오는지</b>를 보고 최적화하므로, 미리 컴파일하는 방식보다 유리한 경우도 있습니다.\n개념: 대신 처음에는 느리게 시작합니다(워밍업). 그래서 짧게 도는 프로그램에는 손해입니다.\n실무: 서버 성능을 잴 때 워밍업 구간을 빼지 않으면 결과가 통째로 왜곡됩니다 — 벤치마크의 첫 몇 초는 버리세요."},{"t":"input","cat":"internals","k":"마지막이 호출뿐이면","q":"함수의 마지막 동작이 다른 함수 호출뿐일 때 스택을 새로 쌓지 않도록 바꾸는 최적화를 영문 약어 세 글자로 적으세요. (영문 약어)","a":["TCO","꼬리호출최적화","tail call optimization"],"ex":"돌아와서 할 일이 없으므로 <b>현재 프레임을 재사용</b>할 수 있습니다. 그러면 재귀가 사실상 반복문이 되어 깊이 제한이 사라집니다.\n개념: 함수형 언어에서는 이 최적화가 <b>명세에 보장</b>돼 있어 반복문 없이도 프로그램을 짤 수 있습니다.\n실무: 자바스크립트 명세에도 들어 있지만 대부분의 엔진이 구현하지 않았습니다 — 깊은 재귀는 직접 반복으로 바꿔야 합니다."},{"t":"input","cat":"internals","k":"아무도 안 쓰는 계산 지우기","q":"결과를 아무도 쓰지 않는 명령을 찾아 지우는 최적화를 영문 약어 세 글자로 적으세요. (영문 약어)","a":["DCE","죽은코드제거","dead code elimination"],"ex":"Dead Code Elimination 입니다. 다만 <b>부수효과가 있는 명령</b>은 결과를 안 써도 남겨야 합니다.\n개념: 상수 전파 뒤에 다시 돌리면 더 많이 지울 수 있습니다 — 최적화 패스는 <b>순서와 반복</b>이 성능을 좌우합니다.\n실무: 번들러의 트리 셰이킹도 같은 아이디어입니다. 부수효과가 있는 모듈을 잘못 지우지 않도록 <code>sideEffects</code> 표시를 두는 이유가 여기 있습니다."},{"t":"input","cat":"internals","k":"자기 자신으로 시작하는 규칙","q":"<code>expr := expr '+' term</code> 처럼 규칙의 맨 앞에 자기 자신이 나와, 재귀 하강 파서가 그대로는 처리하지 못하는 형태를 무엇이라 부를까요? (세 글자)","a":["좌재귀","왼쪽재귀","left recursion","leftrecursive"],"ex":"함수가 아무것도 소비하지 않고 자기를 다시 불러 <b>무한 재귀</b>에 빠집니다.\n개념: 그래서 문법을 <code>expr := term (('+'|'-') term)*</code> 처럼 <b>반복 형태로 고쳐</b> 씁니다 — 좌결합도 함께 얻습니다.\n실무: LR 계열 파서 생성기는 이 형태를 그대로 다룰 수 있습니다. 손으로 짤 것인가 생성기를 쓸 것인가의 갈림길 중 하나입니다."}]}],"ord":9},{"t":"코드 리뷰 — 결함 찾기","l":[{"t":"읽고 묶는 단계","xp":70,"th":{"sum":"렉서와 파서의 결함은 **문법은 통과하는데 뜻이 달라지는** 형태로 나타난다.","body":[{"h":"무엇을 하나로 묶는가","t":"렉서의 임무는 이어진 글자를 하나의 토큰으로 묶는 것이다. 숫자를 한 글자씩 끊거나 이름과 키워드를 다루지 않으면 파서가 볼 입력 자체가 어긋난다. 빈칸 종류를 한데 묶어 건너뛰는 것도 같은 일의 일부다."},{"h":"어느 쪽으로 묶이는가","t":"재귀 하강에서 좌재귀는 토큰을 소비하지 않고 자기를 불러 곧바로 스택이 넘친다. 오른쪽에서 자신을 다시 부르면 <b>우결합</b>이 되므로, 왼쪽 결합 연산자는 <code>while</code> 로 접어야 한다 — 결과가 틀리는데 문법 오류는 나지 않는다."}],"code":{"c":"let node = parseTerm();\nwhile (peek() === '-') { next(); node = { op:'-', left: node, right: parseTerm() }; }","cap":"왼쪽 결합은 반복으로 접는다"},"key":["렉서는 글자를 묶는다","좌재귀는 무한 재귀","재귀는 우결합을 만든다","의미가 틀려도 문법은 통과한다"]},"q":[{"t":"review","k":"숫자를 한 글자만 읽는 렉서","cat":"review","d":2,"q":"이 코드의 결함을 모두 고르세요","code":"function lex(src) {\n  const out = [];\n  for (let i = 0; i < src.length; i++) {\n    const c = src[i];\n    if (c === \" \") continue;\n    if (c >= \"0\" && c <= \"9\") out.push({ t: \"num\", v: Number(c) });\n    else out.push({ t: \"op\", v: c });\n  }\n  return out;\n}","items":[{"txt":"숫자를 <b>한 글자씩</b> 토큰으로 만든다. <code>12</code> 가 <code>1</code> 과 <code>2</code> 두 토큰이 되어 파서는 문법 오류로 보거나 엉뚱한 식을 만들므로, 이어지는 자릿수를 모두 삼키는 반복이 필요하다.","bad":true},{"txt":"식별자와 키워드를 전혀 다루지 않아 <code>a</code> 나 <code>if</code> 같은 입력이 모두 연산자 토큰이 된다. <b>글자로 시작하면 이름을 끝까지 읽고</b>, 예약어 목록과 대조해 키워드인지 판정하는 것이 렉서의 몫이다.","bad":true},{"txt":"공백만 건너뛰고 줄바꿈·탭은 연산자로 만든다 — 빈칸 종류를 한데 묶어 처리해야 하며, 그러지 않으면 줄을 나눈 입력이 통째로 깨진다.","bad":true},{"txt":"토큰에 원본 위치가 없으면 나중에 오류 메시지가 어디를 가리켜야 할지 알 수 없다 — 이 렉서가 약속한 범위에는 들어 있지 않지만, 줄과 열을 토큰마다 함께 담아야 한다.","bad":false},{"txt":"문자열을 코드 유닛 단위로 훑으므로 UTF-16 서러게이트 쌍이 한가운데서 쪼개져 깨진 글자가 토큰에 실릴 수 있다 — 이모지를 식별자로 허용하는 언어가 아니라면 드문 경우이지만, 코드 포인트 단위로 순회하도록 바꿔야 한다.","bad":false}],"ex":"결함 3가지. (1) <b>여러 자리 숫자</b>를 못 읽는다 — 렉서의 기본 임무가 '이어진 글자를 하나의 토큰으로 묶는 것' 이다. (2) <b>이름과 키워드</b>를 다루지 않는다. (3) <b>줄바꿈·탭</b>이 연산자가 된다. 셋 다 '어떤 글자 무리를 어떤 토큰으로 묶을지' 를 정하지 않은 데서 온다.\n디스트랙터: 토큰 위치는 오류 메시지를 위해 필요하지만 이 함수가 약속한 범위 밖이고, 서러게이트 쌍은 이런 언어에서 드문 경우다."},{"t":"review","k":"좌재귀로 쓴 문법","cat":"review","d":3,"q":"이 코드의 결함을 모두 고르세요","code":"// expr := expr '+' term | term\nfunction parseExpr() {\n  const left = parseExpr();\n  if (peek() === \"+\") { next(); return { op: \"+\", left, right: parseTerm() }; }\n  return left;\n}","items":[{"txt":"뺄셈을 다루지 않아 같은 우선순위의 연산자를 놓친다 — 문법 주석에 적힌 범위가 덧셈뿐이므로 이 코드가 약속을 어긴 것은 아니지만, 실전에서는 함께 처리하는 편이 자연스럽다.","bad":false},{"txt":"<b>좌재귀</b>라 <code>parseExpr</code> 이 토큰을 하나도 소비하지 않고 자기 자신을 부른다. 입력과 무관하게 곧바로 스택이 넘치므로, 재귀 하강에서는 좌재귀를 <b>반복문</b>으로 펴서 써야 한다.","bad":true},{"txt":"<code>peek</code> 과 <code>next</code> 가 전역 상태를 쓰므로 파서를 두 개 동시에 굴릴 수 없다 — 학습용 파서에서 흔히 두는 단순화이기는 하지만, 읽기 위치를 객체에 담아 넘겨야 한다.","bad":false},{"txt":"덧셈이 여러 번 나오는 식을 하나만 처리하고 끝낸다 — <code>1 + 2 + 3</code> 을 왼쪽부터 접으려면 <code>while (peek() === \"+\")</code> 로 <b>계속 이어 붙이는</b> 형태여야 한다.","bad":true},{"txt":"오른쪽 피연산자를 <code>parseTerm</code> 으로 읽어 우선순위 계층을 지킨 것은 올바르다 — 곱셈처럼 더 강하게 묶여야 하는 연산을 아래 단계에 맡기고, 이 단계는 자기 우선순위의 연산자만 다루는 재귀 하강의 정석 구조다.","bad":false}],"ex":"결함 2가지. (1) <b>좌재귀</b>는 재귀 하강에서 그대로 무한 재귀가 된다 — 진행을 만드는 토큰 소비가 재귀보다 먼저 와야 한다. (2) 그래서 <b>반복으로 펴야</b> 여러 번의 덧셈을 왼쪽 결합으로 접을 수 있다.\n디스트랙터: 뺄셈은 주석에 적힌 문법의 범위 밖이고, 전역 상태는 학습용 단순화다. 오른쪽을 <code>parseTerm</code> 으로 읽은 것은 우선순위를 지키는 올바른 구조다."},{"t":"review","k":"결합 방향이 뒤집힌 파서","cat":"review","d":3,"q":"이 코드의 결함을 모두 고르세요","code":"// term := factor ('-' term)?\nfunction parseTerm() {\n  const left = parseFactor();\n  if (peek() === \"-\") { next(); return { op: \"-\", left, right: parseTerm() }; }\n  return left;\n}","items":[{"txt":"<code>peek</code> 가 입력 끝에서 무엇을 돌려주는지 코드만으로는 알 수 없어 <code>undefined</code> 비교가 될 수 있다 — 토큰 스트림 계약에 달린 문제이며 이 조각의 초점은 아니다.","bad":false},{"txt":"노드에 위치 정보가 없어 나중에 오류를 가리키기 어렵다 — 파싱 결과의 정확성과는 별개의 이야기이지만, 각 노드에 시작·끝 위치를 실어야 한다.","bad":false},{"txt":"오른쪽에서 <code>parseTerm</code> 을 다시 부르므로 <b>우결합</b>으로 묶인다. <code>10 - 3 - 2</code> 가 <code>10 - (3 - 2)</code> 가 되어 9 를 내놓지만 뺄셈은 왼쪽 결합이므로 5 가 맞고, 문법이 아니라 <b>의미가 틀린다</b>.","bad":true},{"txt":"왼쪽 결합으로 만들려면 <code>while</code> 로 돌면서 <b>지금까지 만든 노드를 왼쪽에 두고</b> 새 항을 오른쪽에 붙여야 한다 — 재귀로 쓰면 자연스럽게 우결합이 되므로, 결합 방향은 반복이냐 재귀냐로 갈린다.","bad":true},{"txt":"문법 주석과 구현이 일치하므로 코드 자체는 주석을 지킨다 — 그러나 <b>주석에 적힌 문법이 이미 우결합</b>이므로, 고쳐야 할 것은 코드가 아니라 문법과 코드 둘 다이다.","bad":true}],"ex":"결함 3가지. (1) <b>우결합으로 묶인다</b> — 문법은 통과하는데 계산 결과가 틀리는, 가장 찾기 어려운 종류의 버그다. (2) 왼쪽 결합은 <b>반복으로 접어야</b> 나온다. (3) 주석의 문법 자체가 우결합이므로 <b>문법과 코드를 함께</b> 고쳐야 한다.\n디스트랙터: <code>peek</code> 가 입력 끝에서 무엇을 돌려주는지는 토큰 스트림의 계약에 달린 문제라 이 조각만으로는 판단할 수 없고, 노드에 위치를 담는 것은 진단 품질을 위한 개선 항목이지 파싱 결과의 정확성과는 무관하다."},{"t":"review","k":"스코프가 하나뿐인 심볼 테이블","cat":"review","d":3,"q":"이 코드의 결함을 모두 고르세요","code":"const symbols = new Map();\n\nfunction declare(name, type) {\n  symbols.set(name, type);\n}\nfunction lookup(name) {\n  return symbols.get(name);\n}","items":[{"txt":"스코프가 하나뿐이라 <b>안쪽 블록의 선언이 바깥 것을 덮어쓴다</b>. 블록을 벗어나도 되돌아오지 않으므로 함수 지역 변수가 전역처럼 살아남고, 서로 다른 함수의 같은 이름이 충돌한다.","bad":true},{"txt":"<code>Map</code> 대신 평범한 객체를 쓰면 <code>__proto__</code> 같은 이름이 프로토타입을 건드릴 수 있다 — <code>Map</code> 을 고른 이 코드는 오히려 그 함정을 피한 셈이다.","bad":false},{"txt":"타입만 저장하고 선언 위치를 담지 않아 '여기서 처음 선언됨' 같은 메시지를 만들 수 없다 — 지금 구조의 결함이라기보다 확장에 가깝지만, 선언 위치를 함께 저장해야 한다.","bad":false},{"txt":"같은 이름을 <b>다시 선언해도 조용히 덮어쓴다</b>. 대부분의 언어에서 같은 스코프의 중복 선언은 오류이므로, 이미 있으면 그 자리에서 진단을 내야 사용자가 실수를 안다.","bad":true},{"txt":"찾지 못했을 때 <code>undefined</code> 를 돌려주므로 호출자가 '선언되지 않음' 과 '타입이 undefined' 를 구별할 수 없다 — 없는 이름은 별도의 결과로 알려 주도록 바꿔야 하며, 그러지 않으면 진단이 엉뚱한 곳에서 난다.","bad":true}],"ex":"결함 3가지. (1) <b>스코프가 없다</b> — 들어가고 나올 수 있는 층이 있어야 지역 변수와 섀도잉이 성립한다. (2) <b>중복 선언을 잡지 않는다</b> — 조용히 덮어쓰면 사용자는 자기 실수를 모른다. (3) <b>없음과 값을 구별할 수 없다</b>. 층을 쌓는 구조(부모를 가리키는 스코프)로 바꾸면 셋이 함께 풀린다.\n디스트랙터: <code>Map</code> 선택은 오히려 잘한 부분이고, 선언 위치 저장은 다음 단계의 확장이다."}]},{"t":"이름·의미·산출물","xp":70,"th":{"sum":"뒤 단계의 결함은 **조용하다** — 스코프, 평가 순서, 최적화, 링크가 그렇다.","body":[{"h":"이름과 순서","t":"스코프가 하나뿐이면 지역 변수가 전역처럼 살아남고 중복 선언이 조용히 덮인다. 평가기에서 단축 평가를 빠뜨리면 <code>p != null &amp;&amp; p.x</code> 가 터지는데, 이것은 최적화가 아니라 <b>언어 규칙</b>이다."},{"h":"접는 것과 잇는 것","t":"상수 폴딩은 의미를 바꾸지 않는 변환이어야 한다 — 0 으로 나누기를 접으면 실행 시점 오류가 값으로 박히고, 호스트 산술로 계산하면 대상 언어의 수 체계와 갈린다. 헤더에 정의를 두면 포함한 곳마다 심볼이 생겨 링크가 깨진다."}],"code":{"c":"if (b === 0) return n;            // 접지 않는다\nscope = { parent: scope, vars: new Map() };\n// util.h: extern int counter;   (정의는 .c 에)","cap":"확신이 없으면 접지 않는다"},"key":["스코프는 층으로 쌓는다","단축 평가는 언어 규칙","최적화는 의미를 보존한다","헤더에는 선언만"]},"q":[{"t":"review","k":"단축 평가를 하지 않는 평가기","cat":"review","d":2,"q":"이 코드의 결함을 모두 고르세요","code":"function evalNode(n, env) {\n  if (n.op === \"&&\") {\n    const l = evalNode(n.left, env);\n    const r = evalNode(n.right, env);\n    return l && r;\n  }\n  ...\n}","items":[{"txt":"오른쪽을 <b>먼저 평가하고 나서</b> 논리곱을 계산한다. 왼쪽이 거짓이면 오른쪽은 실행되지 않아야 하는데, <code>p != null &amp;&amp; p.name</code> 같은 흔한 관용구가 그대로 터진다.","bad":true},{"txt":"부수효과가 있는 오른쪽 식이 <b>언제나 실행된다</b>. 함수 호출이나 대입이 들어 있으면 프로그램의 의미가 달라지므로, 단축 평가는 최적화가 아니라 <b>언어 규칙</b>으로 지켜야 한다.","bad":true},{"txt":"재귀로 트리를 훑으므로 깊은 식에서 스택이 넘칠 수 있다 — 사람이 쓰는 식의 깊이에서는 거의 문제가 되지 않지만, 명시적 스택으로 바꿔야 한다.","bad":false},{"txt":"노드 종류를 <code>op</code> 문자열로 분기하므로 오타를 컴파일 시점에 잡을 수 없다 — 열거형이나 태그 유니온으로 바꾸면 좋겠지만, 동작의 정확성과는 다른 층위다.","bad":false},{"txt":"자바스크립트의 <code>&amp;&amp;</code> 로 결과를 만들면 대상 언어의 진리값 규칙이 아니라 호스트 언어의 규칙이 적용된다 — 두 언어의 규칙이 다르면 결과가 갈리므로 명시적으로 변환해야 한다.","bad":true}],"ex":"결함 3가지. (1) <b>단축 평가가 없다</b> — 왼쪽이 거짓이면 오른쪽은 아예 실행되지 않아야 한다. (2) 그래서 <b>부수효과의 실행 여부</b>가 달라져 프로그램의 의미가 바뀐다. (3) <b>호스트 언어의 진리값 규칙</b>이 새어 든다 — 대상 언어의 규칙으로 명시해 변환해야 한다.\n디스트랙터: 재귀로 트리를 훑는 깊이는 사람이 쓰는 식의 규모에서는 문제가 되지 않고, 노드 종류를 문자열로 분기하는 것은 타입 안전성의 아쉬움일 뿐 지금 코드가 잘못된 값을 내놓는 이유가 아니다."},{"t":"review","k":"어디가 틀렸는지 말하지 않는 진단","cat":"review","d":2,"q":"이 코드의 결함을 모두 고르세요","code":"function expect(kind) {\n  if (peek().t !== kind) {\n    throw new Error(\"syntax error\");\n  }\n  return next();\n}","items":[{"txt":"메시지에 <b>위치도 기대한 것도 실제로 본 것도</b> 없다. 사용자는 파일 어디를 고쳐야 할지 알 수 없으므로, 최소한 줄·열과 '무엇을 기대했는데 무엇이 왔다' 를 담아야 한다.","bad":true},{"txt":"첫 오류에서 <b>예외로 즉시 중단</b>하므로 한 번에 하나씩만 고칠 수 있다. 실용적인 컴파일러는 그 자리에서 회복해 계속 훑으면서 <b>여러 진단을 모아</b> 한꺼번에 보여 준다.","bad":true},{"txt":"입력 끝에서 <code>peek()</code> 가 무엇을 돌려주는지에 따라 <code>.t</code> 읽기가 터질 수 있다 — 끝을 나타내는 토큰을 두어 <b>흐름 안에서</b> 다루는 편이 안전하다.","bad":true},{"txt":"일반 <code>Error</code> 는 잡는 쪽에서 다른 오류와 구분되지 않는다 — 메시지에 정보가 없다는 문제와 견주면 부차적이지만, 전용 오류 타입을 만들어야 한다.","bad":false},{"txt":"성공했을 때 소비한 토큰을 그대로 돌려주므로 호출자가 <code>const id = expect(&quot;ident&quot;)</code> 처럼 값을 바로 받아 쓸 수 있다 — 검사와 소비를 한 함수에 묶은 이 형태는 재귀 하강 파서에서 널리 쓰이는 관용구다.","bad":false}],"ex":"결함 3가지. (1) <b>메시지에 정보가 없다</b> — 위치와 기대·실제가 없으면 진단이 아니라 통보다. (2) <b>회복이 없다</b> — 첫 오류에서 멈추면 사용자는 고치고 다시 돌리기를 반복해야 한다. (3) <b>입력 끝</b>을 흐름 안에서 다루지 않아 파서가 터질 수 있다.\n디스트랙터: 전용 오류 타입을 만들면 잡는 쪽에서 구분하기 좋지만 메시지에 정보가 없다는 문제에 견주면 부차적이고, 검사와 소비를 한 함수에 묶은 <code>expect</code> 형태는 재귀 하강 파서의 널리 쓰이는 관용구다."},{"t":"review","k":"너무 일찍 접는 상수 폴딩","cat":"review","d":4,"q":"이 코드의 결함을 모두 고르세요","code":"function fold(n) {\n  if (n.left.k === \"num\" && n.right.k === \"num\") {\n    const a = n.left.v, b = n.right.v;\n    if (n.op === \"+\") return { k: \"num\", v: a + b };\n    if (n.op === \"/\") return { k: \"num\", v: a / b };\n  }\n  return n;\n}","items":[{"txt":"덧셈과 나눗셈만 접으므로 곱셈이나 뺄셈은 그대로 남는다 — 최적화를 덜 하는 것 자체는 정확성 문제가 아니지만, 접을 수 있는 연산자를 모두 다뤄야 한다.","bad":false},{"txt":"<code>b</code> 가 0 인 나눗셈을 <b>컴파일 시점에 접는다</b>. 대상 언어가 실행 시점 오류로 정한 동작이라면 그 오류가 사라지고 엉뚱한 값이 박히므로, 접을 수 없는 경우는 그대로 두어야 한다.","bad":true},{"txt":"호스트 언어의 산술로 계산하므로 <b>대상 언어의 수 체계와 어긋날 수 있다</b>. 정수 나눗셈·넘침·부동소수 반올림 규칙이 다르면 컴파일한 결과와 직접 실행한 결과가 갈린다.","bad":true},{"txt":"<code>n.left</code> 나 <code>n.right</code> 가 없는 단항 노드에서 그대로 터진다 — 노드 종류를 먼저 확인해야 하며, 트리를 훑는 함수는 <b>모든 모양</b>을 다룰 수 있어야 한다.","bad":true},{"txt":"접은 결과를 새 노드로 만들어 돌려주므로 원본 트리를 바꾸지 않는다 — 여러 번 훑는 최적화 단계에서 안전한 방식이며 결함이 아니다.","bad":false}],"ex":"결함 3가지. (1) <b>0 으로 나누기를 접는다</b> — 실행 시점 오류가 되어야 할 것이 컴파일 결과에 값으로 박힌다. (2) <b>호스트 산술</b>로 계산해 대상 언어의 규칙과 갈릴 수 있다. (3) <b>단항 노드</b>에서 터진다. 최적화는 '의미를 바꾸지 않는 변환' 이어야 하고, 확신이 없으면 접지 않는 편이 언제나 옳다.\n디스트랙터: 접는 연산자가 적은 것은 최적화의 범위 문제이고, 새 노드를 만드는 방식은 오히려 안전하다."},{"t":"review","k":"헤더에 정의를 담았다","cat":"review","d":3,"q":"이 코드의 결함을 모두 고르세요","code":"// util.h\nint counter = 0;\n\nint bump(void) {\n    return ++counter;\n}","items":[{"txt":"전역 카운터를 여러 스레드가 동시에 증가시키면 값이 어긋난다 — 이 코드가 단일 스레드용이라면 결함이라 하기 어렵지만, 원자적 연산으로 바꿔야 한다.","bad":false},{"txt":"<code>bump</code> 가 인자를 받지 않음을 <code>void</code> 로 명시한 것은 C 에서 의미가 있다 — 비워 두면 '인자 정보 없음' 이 되어 검사를 받지 못하므로, 이 부분은 잘 쓴 편이다.","bad":false},{"txt":"헤더에 <b>정의</b>를 두면 그것을 포함한 모든 번역 단위가 같은 심볼을 만든다. 링크 시점에 중복 정의로 실패하고, 컴파일러 확장으로 통과하더라도 <b>번역 단위마다 다른 변수</b>가 생겨 값이 갈린다.","bad":true},{"txt":"함수 본문도 헤더에 있으므로 같은 이름의 함수가 여러 번 정의된다 — 헤더에는 선언만 두고 정의는 하나의 소스 파일에 두거나, 인라인으로 만들 것이라면 그 뜻을 명시해야 한다.","bad":true},{"txt":"포함 가드나 <code>#pragma once</code> 가 없어 같은 헤더를 두 번 포함하면 한 번역 단위 안에서도 중복 정의가 난다 — 헤더에는 언제나 가드를 두어야 한다.","bad":true}],"ex":"결함 3가지. (1) <b>헤더의 변수 정의</b>는 포함한 곳마다 심볼을 만든다 — 선언(<code>extern</code>)과 정의를 나눠야 한다. (2) <b>함수 정의</b>도 마찬가지다. (3) <b>포함 가드가 없다</b>. 헤더는 '무엇이 있다고 약속하는 곳' 이고 정의는 한 곳에만 있어야 한다는 규칙이 이 셋을 함께 설명한다.\n디스트랙터: 스레드 안전성은 사용 맥락에 달렸고, <code>void</code> 매개변수 목록은 C 에서 오히려 올바른 표기다."}]}],"ord":10},{"t":"시뮬레이션 · 눈으로 보는 코드","l":[{"t":"시뮬레이션 I","q":[{"t":"sim","k":"알고리즘 시각화","lv":2,"q":"토크나이저를 만드세요. 숫자·연산자·괄호를 토큰으로 쪼갭니다. <b>토큰을 하나 낼 때마다</b> <code>snap(\"토큰 \"+t, {지금까지:[...out], 위치:i})</code> 를 부르세요. 반환값은 토큰 배열입니다.","src":"function tokenize(src) {\n  const out = [];\n  let i = 0;\n  // 여기에 구현하세요 — 공백은 건너뛰고, 숫자는 여러 자리를 한 토큰으로\n  return out;\n}\n\nRESULT = tokenize('12 + 3*(45-6)');","tests":[{"d":"토큰이 맞게 쪼개진다","js":"JSON.stringify(RESULT)==='[\"12\",\"+\",\"3\",\"*\",\"(\",\"45\",\"-\",\"6\",\")\"]'"},{"d":"여러 자리 숫자가 한 토큰이다","js":"RESULT.indexOf('12')>=0 && RESULT.indexOf('45')>=0"},{"d":"토큰마다 장면이 남았다","js":"FRAMES.length===9"},{"d":"위치는 계속 앞으로만 간다","js":"(function(){for(var i=1;i<FRAMES.length;i++) if(FRAMES[i].value['위치']<=FRAMES[i-1].value['위치']) return false; return true;})()"},{"d":"토큰 목록이 한 개씩 자란다","js":"(function(){for(var i=0;i<FRAMES.length;i++) if(FRAMES[i].value['지금까지'].length!==i+1) return false; return true;})()"}],"ex":"렉서의 핵심은 '<b>최대한 길게 먹는다</b>'(maximal munch) 입니다. <code>12</code> 를 <code>1</code>·<code>2</code> 로 쪼개지 않고 숫자가 이어지는 동안 계속 먹습니다. 이 규칙이 있어야 <code>&gt;=</code> 가 <code>&gt;</code> 와 <code>=</code> 로 갈라지지 않습니다. 공백을 그냥 건너뛰는 것도 여기서 정해지고, 그래서 대부분의 언어에서 공백이 의미를 갖지 않습니다."},{"t":"sim","k":"자료구조 시각화","lv":3,"q":"연산자 우선순위를 스택으로 처리해 <b>후위 표기</b>로 바꾸세요(shunting-yard). <b>스택이 바뀔 때마다</b> <code>snap(라벨, {출력:[...out], 스택:[...ops]})</code> 을 부르세요. 반환값은 후위 표기 배열입니다.","src":"const PREC = { '+': 1, '-': 1, '*': 2, '/': 2 };\n\nfunction toPostfix(tokens) {\n  const out = [], ops = [];\n  // 여기에 구현하세요 — 우선순위가 높거나 같은 연산자는 먼저 꺼냅니다\n  return out;\n}\n\nRESULT = toPostfix(['1','+','2','*','3','-','4']);","tests":[{"d":"후위 표기가 맞다","js":"JSON.stringify(RESULT)==='[\"1\",\"2\",\"3\",\"*\",\"+\",\"4\",\"-\"]'"},{"d":"곱셈이 덧셈보다 먼저 나온다","js":"RESULT.indexOf('*')<RESULT.indexOf('+')"},{"d":"장면이 8개 기록됐다","js":"FRAMES.length===8"},{"d":"마지막에 스택이 비어 있다","js":"FRAMES[FRAMES.length-1].value['스택'].length===0"},{"d":"스택에는 연산자만 쌓인다","js":"FRAMES.every(f=>f.value['스택'].every(x=>['+','-','*','/'].indexOf(x)>=0))"}],"ex":"우선순위는 문법이 아니라 <b>스택을 언제 비우는가</b>로 표현됩니다. 새 연산자가 올 때 스택 위의 것이 <b>더 세거나 같으면</b> 먼저 꺼내 출력합니다 — 이 한 줄이 곱셈을 덧셈보다 먼저 계산되게 만듭니다. 같은 우선순위에서 꺼내는 것이 <b>왼쪽 결합</b>이고, 거듭제곱처럼 오른쪽 결합인 연산자는 부등호를 <code>&gt;</code> 로 바꿔야 합니다."},{"t":"sim","k":"상태 시각화","lv":3,"q":"심볼 테이블의 <b>스코프</b>를 만드세요. 블록에 들어가면 새 스코프를 쌓고 나오면 걷습니다. 이름을 찾을 때는 <b>안쪽부터</b> 봅니다. <b>연산마다</b> <code>snap(라벨, {스코프:scopes.map(s=&gt;Object.keys(s)), 찾은값:v})</code> 를 부르세요. 반환값은 조회 결과 배열입니다.","src":"function scopes(ops) {\n  const stack = [{}], found = [];\n  // 여기에 구현하세요 — ['push'], ['pop'], ['def', 이름, 값], ['get', 이름]\n  return found;\n}\n\nRESULT = scopes([['def','x',1],['push'],['def','x',2],['get','x'],['pop'],['get','x'],['get','y']]);","tests":[{"d":"안쪽 스코프가 바깥을 가린다","js":"RESULT[0]===2"},{"d":"블록을 나오면 바깥 값이 다시 보인다","js":"RESULT[1]===1"},{"d":"없는 이름은 null 이다","js":"RESULT[2]===null"},{"d":"연산마다 장면이 남았다","js":"FRAMES.length===7"},{"d":"스코프 깊이가 1 아래로 내려가지 않는다","js":"FRAMES.every(f=>f.value['스코프'].length>=1)"}],"ex":"이름 해석(name resolution)은 <b>안쪽 스코프부터 바깥으로</b> 올라가며 찾는 것뿐입니다. 안쪽에 같은 이름이 있으면 바깥이 <b>가려집니다</b>(shadowing) — 버그가 아니라 규칙입니다. 블록을 나오면 그 스코프가 통째로 사라지므로 안에서 선언한 이름은 밖에서 보이지 않습니다. 클로저는 이 '사라져야 할 스코프' 를 함수가 붙잡고 있는 것이라, 컴파일러는 그런 변수를 힙에 올립니다."},{"t":"sim","k":"알고리즘 시각화","lv":3,"q":"후위 표기식을 <b>스택으로 계산</b>하세요. <b>스택이 바뀔 때마다</b> <code>snap(라벨, [...stack])</code> 을 부르세요. 반환값은 계산 결과입니다.","src":"function evalPostfix(tokens) {\n  const stack = [];\n  // 여기에 구현하세요 — 숫자는 쌓고, 연산자는 둘을 꺼내 계산해 다시 쌓습니다\n  return stack[0];\n}\n\nRESULT = evalPostfix(['1','2','3','*','+','4','-']);","tests":[{"d":"계산 결과가 3 이다","js":"RESULT===3"},{"d":"토큰마다 장면이 남았다","js":"FRAMES.length===7"},{"d":"마지막에 값이 하나만 남는다","js":"FRAMES[FRAMES.length-1].value.length===1"},{"d":"연산할 때마다 스택이 하나 줄어든다","js":"(function(){var f=FRAMES.filter(x=>/계산/.test(x.label));return f.length===3;})()"},{"d":"뺄셈의 피연산자 순서가 맞다 (a - b)","js":"(function(){var f=FRAMES.filter(x=>/계산/.test(x.label));return /7-4/.test(f[2].label);})()"}],"ex":"후위 표기에는 괄호가 없습니다 — 순서가 이미 <b>토큰 배치에 들어 있기</b> 때문입니다. 그래서 계산기는 스택 하나로 끝납니다. 주의할 곳은 꺼내는 순서입니다: 먼저 꺼낸 것이 <b>오른쪽</b> 피연산자라 <code>a - b</code> 로 써야 합니다. 뒤집으면 덧셈·곱셈은 맞고 뺄셈·나눗셈만 틀리는, 찾기 어려운 버그가 됩니다."}],"th":{"sum":"코드를 쓰고 무슨 일이 일어나는지 눈으로 확인하는 훈련입니다. snap(라벨, 값) 을 부르면 그 순간이 한 장면으로 남고, 슬라이더로 되감아 볼 수 있습니다.","body":[{"h":"설명 대신 장면으로 이해한다","t":"'버블 정렬은 O(n²)' 이라는 문장보다, 교환 장면이 <b>몇 개나 쌓이는지</b> 보는 편이 빠릅니다. 이진 탐색에서 흐릿해지는 칸이 절반씩 늘어나는 것도 마찬가지입니다."},{"h":"기록은 사본으로 남긴다","t":"<code>snap(\"단계\", arr)</code> 는 그 순간의 값을 복사해 둡니다. 배열을 그대로 넘겨도 되지만, 스택처럼 계속 바뀌는 것은 <code>[...stack]</code> 으로 넘겨야 나중에 뒤섞이지 않습니다."},{"h":"강조로 '지금 보는 곳' 을 표시한다","t":"세 번째 인자로 <code>{hi:[i,j]}</code> 를 주면 그 칸이 빨갛게, <code>{dim:[...]}</code> 를 주면 흐리게 그려집니다. 알고리즘이 <b>어디를 보고 있는지</b>가 드러납니다."},{"h":"채점은 결과 + 흐름","t":"반환값만 맞추면 되는 게 아니라 <b>장면의 흐름</b>도 봅니다 — 창이 한 칸씩 움직였는가, 메모 표가 한 칸씩 커졌는가. 우연히 맞은 답과 제대로 만든 답이 갈립니다."}],"code":{"t":"한 줄이면 장면이 남는다","c":"if (a[j] > a[j+1]) {\n  [a[j], a[j+1]] = [a[j+1], a[j]];\n  snap(\"교환\", a, { hi: [j, j+1] });   // ← 이 순간이 기록된다\n}"},"key":["snap(라벨, 값, 옵션) 으로 순간을 남긴다","계속 바뀌는 값은 사본으로 넘긴다","hi·dim 으로 보고 있는 위치를 표시한다","채점은 결과값과 장면의 흐름을 함께 본다"]}},{"t":"시뮬레이션 II","q":[{"t":"sim","k":"메모리 시각화","lv":2,"q":"상수 접기(constant folding)를 하세요. 트리에서 <b>양쪽이 모두 숫자인 노드</b>를 계산해 하나로 접습니다. <b>접을 때마다</b> <code>snap(\"접기 \"+식, {남은노드:n})</code> 을 부르세요. 반환값은 접힌 결과입니다.","src":"const TREE = { op:'+', l:{ op:'*', l:{n:2}, r:{n:3} }, r:{ op:'-', l:{n:10}, r:{n:4} } };\n\nfunction fold(node) {\n  // 여기에 구현하세요 — 재귀로 내려가며 숫자끼리 만나면 계산합니다\n  return node;\n}\n\nRESULT = fold(TREE).n;","tests":[{"d":"전부 접혀 12 가 된다","js":"RESULT===12"},{"d":"접기가 3번 일어난다","js":"FRAMES.length===3"},{"d":"안쪽부터 접힌다 (곱셈이 먼저)","js":"/2\\*3/.test(FRAMES[0].label)"},{"d":"남은 노드 수가 계속 줄어든다","js":"(function(){for(var i=1;i<FRAMES.length;i++) if(FRAMES[i].value['남은노드']>=FRAMES[i-1].value['남은노드']) return false; return true;})()"},{"d":"마지막 접기가 덧셈이다","js":"/\\+/.test(FRAMES[2].label)"}],"ex":"상수 접기는 컴파일러 최적화의 가장 기본입니다. <code>2 * 3</code> 을 실행 시점에 계산할 이유가 없으므로 <b>컴파일 때 6으로 바꿔</b>버립니다. 반드시 <b>잎에서부터</b> 접어야 안쪽 결과가 바깥 계산에 쓰입니다 — 위에서부터 보면 양쪽이 아직 숫자가 아니라 아무것도 못 접습니다. 부동소수에서는 이 최적화가 결과를 미세하게 바꿀 수 있어, 엄격한 모드에서는 끄기도 합니다."}],"th":{"sum":"코드를 쓰고 무슨 일이 일어나는지 눈으로 확인하는 훈련입니다. snap(라벨, 값) 을 부르면 그 순간이 한 장면으로 남고, 슬라이더로 되감아 볼 수 있습니다.","body":[{"h":"설명 대신 장면으로 이해한다","t":"'버블 정렬은 O(n²)' 이라는 문장보다, 교환 장면이 <b>몇 개나 쌓이는지</b> 보는 편이 빠릅니다. 이진 탐색에서 흐릿해지는 칸이 절반씩 늘어나는 것도 마찬가지입니다."},{"h":"기록은 사본으로 남긴다","t":"<code>snap(\"단계\", arr)</code> 는 그 순간의 값을 복사해 둡니다. 배열을 그대로 넘겨도 되지만, 스택처럼 계속 바뀌는 것은 <code>[...stack]</code> 으로 넘겨야 나중에 뒤섞이지 않습니다."},{"h":"강조로 '지금 보는 곳' 을 표시한다","t":"세 번째 인자로 <code>{hi:[i,j]}</code> 를 주면 그 칸이 빨갛게, <code>{dim:[...]}</code> 를 주면 흐리게 그려집니다. 알고리즘이 <b>어디를 보고 있는지</b>가 드러납니다."},{"h":"채점은 결과 + 흐름","t":"반환값만 맞추면 되는 게 아니라 <b>장면의 흐름</b>도 봅니다 — 창이 한 칸씩 움직였는가, 메모 표가 한 칸씩 커졌는가. 우연히 맞은 답과 제대로 만든 답이 갈립니다."}],"code":{"t":"한 줄이면 장면이 남는다","c":"if (a[j] > a[j+1]) {\n  [a[j], a[j+1]] = [a[j+1], a[j]];\n  snap(\"교환\", a, { hi: [j, j+1] });   // ← 이 순간이 기록된다\n}"},"key":["snap(라벨, 값, 옵션) 으로 순간을 남긴다","계속 바뀌는 값은 사본으로 넘긴다","hi·dim 으로 보고 있는 위치를 표시한다","채점은 결과값과 장면의 흐름을 함께 본다"]}},{"t":"시뮬레이션 III","q":[{"t":"sim","k":"컴파일러 시뮬레이션","lv":2,"q":"<b>토큰화</b>를 구현하세요. 산술식을 숫자·연산자·괄호로 나누고 토큰마다 <code>snap</code> 으로 기록한 뒤 <b>토큰 수</b>를 돌려주세요.","src":"const SRC = '12 + 3*(45 - 6)';\n\nfunction tokenize() {\n  const tokens = [];\n  // 여기에 구현하세요\n  return tokens.length;\n}\n\nRESULT = tokenize();","tests":[{"d":"토큰은 9개다","js":"RESULT===9"},{"d":"토큰마다 장면이 기록된다","js":"FRAMES.length===9"},{"d":"숫자 토큰이 4개다","js":"FRAMES.filter(f=>f.opt.kind==='num').length===4"},{"d":"여러 자리 숫자가 한 토큰이다","js":"FRAMES.some(f=>/num 12/.test(f.label)) && FRAMES.some(f=>/num 45/.test(f.label))"},{"d":"토큰 수가 1씩 증가한다","js":"FRAMES.every((f,i)=>f.value[0]===i+1)"}],"ex":"토큰화의 핵심은 <b>최대 길이 우선</b>입니다 — <code>12</code> 를 <code>1</code>·<code>2</code> 두 토큰으로 자르면 안 되므로, 숫자가 시작되면 <b>더 이상 숫자가 아닐 때까지</b> 읽습니다. 같은 원리가 <code>&gt;=</code> 를 <code>&gt;</code>·<code>=</code> 로 자르지 않게 하고, 공백은 <b>토큰을 나누는 역할만</b> 하고 사라집니다. 이 단계에서 이미 '이 문자는 여기 올 수 없다' 는 오류가 잡힙니다."},{"t":"sim","k":"컴파일러 시뮬레이션","lv":3,"q":"<b>연산자 우선순위</b>를 지키는 후위 표기(RPN) 변환을 구현하세요. 출력에 토큰이 추가될 때마다 <code>snap</code> 으로 기록하고 <b>최종 후위식 문자열</b>을 돌려주세요.","src":"const TOKENS = ['2', '+', '3', '*', '4'];\nconst PREC = { '+': 1, '-': 1, '*': 2, '/': 2 };\n\nfunction toRpn() {\n  const out = [], ops = [];\n  // 여기에 구현하세요 — 우선순위가 높거나 같은 연산자는 먼저 꺼냅니다\n  return out.join(' ');\n}\n\nRESULT = toRpn();","tests":[{"d":"후위식이 2 3 4 * + 다","js":"RESULT==='2 3 4 * +'"},{"d":"출력 길이가 5다","js":"RESULT.split(' ').length===5"},{"d":"곱셈이 덧셈보다 먼저 나온다","js":"RESULT.indexOf('*')<RESULT.indexOf('+')"},{"d":"스택 깊이가 음수가 되지 않는다","js":"FRAMES.every(f=>f.opt.stack>=0)"},{"d":"마지막에 스택이 비어 있다","js":"FRAMES[FRAMES.length-1].opt.stack===0"}],"ex":"후위 표기는 <b>괄호가 필요 없습니다</b> — 순서가 이미 표현에 담겨 있기 때문입니다. 변환 규칙 한 줄이 우선순위를 만듭니다: 새 연산자보다 <b>우선순위가 높거나 같은</b> 것을 먼저 꺼내면 <code>2+3*4</code> 에서 <code>*</code> 가 <code>+</code> 보다 먼저 출력됩니다. 결합 방향(오른쪽 결합인 <code>^</code>)은 '같을 때' 조건만 바꾸면 됩니다. 실제 컴파일러의 파서도 같은 원리를 씁니다."},{"t":"sim","k":"컴파일러 시뮬레이션","lv":3,"q":"<b>재귀 하강 파서</b>로 괄호 깊이를 검사하세요. 각 문자의 깊이를 <code>snap</code> 으로 기록하고, 균형이 맞으면 <b>최대 깊이</b>를, 아니면 -1 을 돌려주세요.","src":"const SRC = '((a+b)*(c-(d/e)))';\n\nfunction depth() {\n  let d = 0, max = 0;\n  // 여기에 구현하세요\n  return max;\n}\n\nRESULT = depth();","tests":[{"d":"최대 깊이는 3이다","js":"RESULT===3"},{"d":"괄호마다 장면이 기록된다","js":"FRAMES.length===8"},{"d":"깊이가 음수가 되지 않는다","js":"FRAMES.every(f=>f.value[0]>=0)"},{"d":"마지막 깊이가 0이다","js":"FRAMES[FRAMES.length-1].value[0]===0"},{"d":"최대 깊이가 줄어들지 않는다","js":"FRAMES.every((f,i)=>i===0||f.opt.max>=FRAMES[i-1].opt.max)"}],"ex":"재귀 하강 파서의 <b>재귀 깊이</b>가 곧 이 괄호 깊이입니다 — 그래서 입력이 깊이를 정하는 파서는 <b>스택 오버플로 위험</b>을 안습니다. JSON·표현식 파서에 <b>최대 깊이 제한</b>이 있는 이유이고, 없으면 40KB 짜리 입력 하나로 프로세스를 죽일 수 있습니다(실제 취약점 사례가 많습니다). 깊이 추적은 오류 메시지에 '어느 괄호가 안 닫혔는지' 를 알려 주는 데도 쓰입니다."},{"t":"sim","k":"컴파일러 시뮬레이션","lv":3,"q":"<b>상수 접기(constant folding)</b>를 구현하세요. 후위식에서 숫자끼리의 연산을 미리 계산해 접고, 접을 때마다 <code>snap</code> 으로 기록한 뒤 <b>남은 토큰 수</b>를 돌려주세요.","src":"const RPN = ['2', '3', '*', 'x', '+', '4', '5', '+', '-'];\n\nfunction fold() {\n  const st = [];\n  // 여기에 구현하세요 — 두 피연산자가 모두 숫자면 계산해서 하나로 접습니다\n  return st.length;\n}\n\nRESULT = fold();","tests":[{"d":"최종 스택에 하나만 남는다","js":"RESULT===1"},{"d":"접기가 2번 일어난다","js":"FRAMES.filter(f=>f.opt.folded).length===2"},{"d":"변수가 낀 연산은 접히지 않는다","js":"FRAMES.filter(f=>f.opt.folded===false).length===2"},{"d":"2*3 이 6으로 접힌다","js":"FRAMES.some(f=>/2\\*3=6/.test(f.label))"},{"d":"스택 크기가 음수가 되지 않는다","js":"FRAMES.every(f=>f.value[0]>=0)"}],"ex":"상수 접기는 가장 기본적인 최적화입니다 — <code>2*3</code> 은 실행 시점에 계산할 이유가 없으므로 <b>컴파일 때 6으로</b> 바꿉니다. 변수가 끼면 접을 수 없다는 점이 중요합니다(값을 모르니까). 이 최적화가 <b>다른 최적화를 열어 주기도</b> 합니다: 접은 결과가 0이면 곱셈 전체가 사라지고, 조건이 상수면 <b>죽은 코드 제거</b>로 이어집니다. 그래서 컴파일러는 최적화를 여러 번 반복합니다."}],"th":{"sum":"코드를 쓰고 무슨 일이 일어나는지 눈으로 확인하는 훈련입니다. snap(라벨, 값) 을 부르면 그 순간이 한 장면으로 남고, 슬라이더로 되감아 볼 수 있습니다.","body":[{"h":"설명 대신 장면으로 이해한다","t":"'버블 정렬은 O(n²)' 이라는 문장보다, 교환 장면이 <b>몇 개나 쌓이는지</b> 보는 편이 빠릅니다. 이진 탐색에서 흐릿해지는 칸이 절반씩 늘어나는 것도 마찬가지입니다."},{"h":"기록은 사본으로 남긴다","t":"<code>snap(\"단계\", arr)</code> 는 그 순간의 값을 복사해 둡니다. 배열을 그대로 넘겨도 되지만, 스택처럼 계속 바뀌는 것은 <code>[...stack]</code> 으로 넘겨야 나중에 뒤섞이지 않습니다."},{"h":"강조로 '지금 보는 곳' 을 표시한다","t":"세 번째 인자로 <code>{hi:[i,j]}</code> 를 주면 그 칸이 빨갛게, <code>{dim:[...]}</code> 를 주면 흐리게 그려집니다. 알고리즘이 <b>어디를 보고 있는지</b>가 드러납니다."},{"h":"채점은 결과 + 흐름","t":"반환값만 맞추면 되는 게 아니라 <b>장면의 흐름</b>도 봅니다 — 창이 한 칸씩 움직였는가, 메모 표가 한 칸씩 커졌는가. 우연히 맞은 답과 제대로 만든 답이 갈립니다."}],"code":{"t":"한 줄이면 장면이 남는다","c":"if (a[j] > a[j+1]) {\n  [a[j], a[j+1]] = [a[j+1], a[j]];\n  snap(\"교환\", a, { hi: [j, j+1] });   // ← 이 순간이 기록된다\n}"},"key":["snap(라벨, 값, 옵션) 으로 순간을 남긴다","계속 바뀌는 값은 사본으로 넘긴다","hi·dim 으로 보고 있는 위치를 표시한다","채점은 결과값과 장면의 흐름을 함께 본다"]}},{"t":"시뮬레이션 IV","q":[{"t":"sim","k":"컴파일러 시뮬레이션","lv":4,"q":"<b>죽은 코드 제거</b>를 구현하세요. 각 문장이 결과에 영향을 주는지 역방향으로 판정하고, 제거되는 문장 수를 돌려주세요.","src":"const STMTS = [\n  {id:0, def:'a', uses:[]},\n  {id:1, def:'b', uses:['a']},\n  {id:2, def:'c', uses:['a']},\n  {id:3, def:'d', uses:['c']},\n  {id:4, def:'ret', uses:['b']}\n];\nconst LIVE_OUT = ['ret'];\n\nfunction dce() {\n  return 0;\n}\n\nRESULT = dce();","tests":[{"d":"제거되는 문장은 2개다","js":"RESULT===2"},{"d":"문장마다 장면이 기록된다","js":"FRAMES.length===5"},{"d":"역방향으로 훑는다 (첫 장면이 마지막 문장)","js":"/ret/.test(FRAMES[0].label)"},{"d":"살아 있는 변수 집합이 줄어들지 않는다","js":"FRAMES.every((f,i)=>i===0||f.opt.live.length>=FRAMES[i-1].opt.live.length)"},{"d":"유지된 문장 수가 줄어들지 않는다","js":"FRAMES.every((f,i)=>i===0||f.value[0]>=FRAMES[i-1].value[0])"}],"ex":"죽은 코드 제거는 <b>뒤에서 앞으로</b> 훑습니다 — 무엇이 필요한지는 <b>나중에 쓰이는지</b>로 정해지기 때문입니다. 반환값에서 시작해 '이 값을 만들려면 무엇이 필요한가' 를 거슬러 올라가면, 아무도 안 쓰는 <code>c</code>·<code>d</code> 가 자연스럽게 떨어져 나갑니다. 같은 <b>역방향 데이터 흐름 분석</b>이 레지스터 할당과 미사용 변수 경고에도 쓰입니다."},{"t":"sim","k":"컴파일러 시뮬레이션","lv":2,"q":"<b>심볼 테이블과 스코프</b>를 모델링하세요. 블록이 열리고 닫힐 때마다 스코프를 쌓고, 각 참조가 <b>어느 스코프에서 해결되는지</b> 기록한 뒤 <b>해결 실패 수</b>를 돌려주세요.","src":"const EVENTS = [\n  {op:'declare', name:'x'},\n  {op:'open'},\n  {op:'declare', name:'y'},\n  {op:'ref', name:'x'},\n  {op:'ref', name:'y'},\n  {op:'close'},\n  {op:'ref', name:'y'}\n];\n\nfunction scopes() {\n  let unresolved = 0;\n  // 여기에 구현하세요 — 안쪽 스코프부터 바깥으로 찾습니다\n  return unresolved;\n}\n\nRESULT = scopes();","tests":[{"d":"해결 실패는 1건이다","js":"RESULT===1"},{"d":"이벤트마다 장면이 기록된다","js":"FRAMES.length===7"},{"d":"바깥 변수 x 는 안쪽에서 보인다","js":"FRAMES.some(f=>/참조 x → 깊이 0/.test(f.label))"},{"d":"블록이 닫히면 안쪽 변수는 사라진다","js":"FRAMES[6].opt.found===-1"},{"d":"스코프 깊이가 1 아래로 내려가지 않는다","js":"FRAMES.every(f=>f.opt.depth>=1)"}],"ex":"이름 해결은 <b>안쪽에서 바깥으로</b> 찾습니다 — 그래서 안쪽에 같은 이름이 있으면 바깥 것을 가립니다(섀도잉). 블록이 닫히면 그 스코프의 이름은 사라지므로, 밖에서 참조하면 <b>컴파일 오류</b>가 납니다. 자바스크립트의 <code>var</code> 가 헷갈리는 이유가 여기에 있습니다 — 블록 스코프가 아니라 함수 스코프라 이 모델과 다르게 동작합니다."},{"t":"sim","k":"컴파일러 시뮬레이션","lv":3,"q":"<b>타입 검사</b>를 구현하세요. 각 연산의 피연산자 타입을 확인해 결과 타입을 정하고, 불일치를 <code>snap</code> 으로 기록한 뒤 <b>타입 오류 수</b>를 돌려주세요.","src":"const OPS = [\n  {op:'+', l:'int', r:'int'},\n  {op:'+', l:'int', r:'string'},\n  {op:'<', l:'int', r:'int'},\n  {op:'&&', l:'bool', r:'bool'},\n  {op:'&&', l:'int', r:'bool'}\n];\n\nfunction typecheck() {\n  let errors = 0;\n  // 여기에 구현하세요 — 산술은 int+int, 비교는 int→bool, 논리는 bool+bool\n  return errors;\n}\n\nRESULT = typecheck();","tests":[{"d":"타입 오류는 2건이다","js":"RESULT===2"},{"d":"연산마다 장면이 기록된다","js":"FRAMES.length===5"},{"d":"비교 연산의 결과 타입은 bool 이다","js":"FRAMES[2].opt.result==='bool'"},{"d":"정수 덧셈의 결과 타입은 int 다","js":"FRAMES[0].opt.result==='int'"},{"d":"오류 수가 줄어들지 않는다","js":"FRAMES.every((f,i)=>i===0||f.value[0]>=FRAMES[i-1].value[0])"}],"ex":"타입 검사는 <b>연산마다 규칙을 적용해 결과 타입을 계산</b>하는 과정입니다. 비교 연산이 <code>bool</code> 을 돌려준다는 점이 중요합니다 — 그래야 <code>a &lt; b &amp;&amp; c</code> 같은 식을 검사할 수 있습니다. 오류가 나면 그 자리에 <b>error 타입</b>을 넣고 계속 진행하는 것이 요령입니다: 그래야 <b>한 번에 여러 오류</b>를 보고할 수 있습니다(첫 오류에서 멈추면 고치고 다시 컴파일하기를 반복해야 합니다)."},{"t":"sim","k":"컴파일러 시뮬레이션","lv":4,"q":"<b>레지스터 할당</b>을 모델링하세요. 변수의 생존 구간이 주어질 때 겹치는 구간에는 다른 레지스터를 배정하고, 레지스터가 2개뿐일 때 <b>메모리로 밀려나는(spill) 변수 수</b>를 돌려주세요.","src":"const LIVE = [\n  {v:'a', from:0, to:5},\n  {v:'b', from:1, to:3},\n  {v:'c', from:2, to:7},\n  {v:'d', from:4, to:6},\n  {v:'e', from:6, to:9}\n];\nconst REGS = 2;\n\nfunction alloc() {\n  let spills = 0;\n  return spills;\n}\n\nRESULT = alloc();","tests":[{"d":"메모리로 밀려나는 변수는 1개다","js":"RESULT===1"},{"d":"변수마다 장면이 기록된다","js":"FRAMES.length===5"},{"d":"동시에 레지스터를 쓰는 변수가 2를 넘지 않는다","js":"FRAMES.every(f=>f.opt.active<=2)"},{"d":"spill 수가 줄어들지 않는다","js":"FRAMES.every((f,i)=>i===0||f.value[0]>=FRAMES[i-1].value[0])"},{"d":"레지스터 배정이 4번 일어난다","js":"FRAMES.filter(f=>/^reg/.test(f.label)).length===4"}],"ex":"레지스터 할당은 <b>그래프 색칠 문제</b>와 같습니다 — 생존 구간이 겹치는 변수는 같은 레지스터를 쓸 수 없으므로 '인접한 정점은 다른 색' 과 정확히 같은 구조입니다. 레지스터가 모자라면 일부를 <b>메모리로 밀어내는데</b>(spill), 메모리 접근은 레지스터보다 수십 배 느리므로 <b>무엇을 밀어낼지</b>가 성능을 좌우합니다. 그래서 루프 안에서 자주 쓰이는 변수는 마지막까지 레지스터에 남깁니다."}],"th":{"sum":"코드를 쓰고 무슨 일이 일어나는지 눈으로 확인하는 훈련입니다. snap(라벨, 값) 을 부르면 그 순간이 한 장면으로 남고, 슬라이더로 되감아 볼 수 있습니다.","body":[{"h":"설명 대신 장면으로 이해한다","t":"'버블 정렬은 O(n²)' 이라는 문장보다, 교환 장면이 <b>몇 개나 쌓이는지</b> 보는 편이 빠릅니다. 이진 탐색에서 흐릿해지는 칸이 절반씩 늘어나는 것도 마찬가지입니다."},{"h":"기록은 사본으로 남긴다","t":"<code>snap(\"단계\", arr)</code> 는 그 순간의 값을 복사해 둡니다. 배열을 그대로 넘겨도 되지만, 스택처럼 계속 바뀌는 것은 <code>[...stack]</code> 으로 넘겨야 나중에 뒤섞이지 않습니다."},{"h":"강조로 '지금 보는 곳' 을 표시한다","t":"세 번째 인자로 <code>{hi:[i,j]}</code> 를 주면 그 칸이 빨갛게, <code>{dim:[...]}</code> 를 주면 흐리게 그려집니다. 알고리즘이 <b>어디를 보고 있는지</b>가 드러납니다."},{"h":"채점은 결과 + 흐름","t":"반환값만 맞추면 되는 게 아니라 <b>장면의 흐름</b>도 봅니다 — 창이 한 칸씩 움직였는가, 메모 표가 한 칸씩 커졌는가. 우연히 맞은 답과 제대로 만든 답이 갈립니다."}],"code":{"t":"한 줄이면 장면이 남는다","c":"if (a[j] > a[j+1]) {\n  [a[j], a[j+1]] = [a[j+1], a[j]];\n  snap(\"교환\", a, { hi: [j, j+1] });   // ← 이 순간이 기록된다\n}"},"key":["snap(라벨, 값, 옵션) 으로 순간을 남긴다","계속 바뀌는 값은 사본으로 넘긴다","hi·dim 으로 보고 있는 위치를 표시한다","채점은 결과값과 장면의 흐름을 함께 본다"]}}],"ord":11},{"t":"실행형 실전 — 미니 컴파일러를 만든다","l":[{"t":"렉서·재귀 하강·션팅 야드","xp":80,"th":{"sum":"컴파일러 앞단은 세 가지 작은 결정의 연속이다 — **가장 길게 자르고**(렉서), **계층으로 우선순위를 만들고**(파서), **스택으로 순서를 뒤집는다**(코드 생성).","body":[{"h":"자르기와 묶기","t":"렉서의 제1규칙은 최장 일치다 — == 는 = 두 개가 아니라 한 토큰이므로 **긴 것부터 검사**한다. 파서는 expr→term→factor 계층으로 우선순위를 표현하고, 좌결합은 재귀가 아니라 **반복문**으로 만든다. 10−2−3 이 5인지 11인지가 여기서 갈린다."},{"h":"후위 표기는 기계의 순서","t":"션팅 야드는 '스택 위 연산자가 나보다 세거나 **같으면** 먼저 내보낸다' 로 중위를 후위로 바꾼다. 후위 계산의 단골 버그는 pop 순서 — 먼저 pop 한 값이 **오른쪽** 피연산자다. 덧셈·곱셈은 교환법칙이 버그를 숨기고 뺄셈에서야 드러난다."}],"code":{"c":"// 먼저 pop = 오른쪽 피연산자\nconst b = st.pop(), a = st.pop();\nst.push(a - b);  // b - a 가 아니다","cap":"교환법칙 없는 연산으로 테스트해야 잡힌다"},"key":["최장 일치 — 긴 토큰을 먼저 검사","우선순위는 문법 계층, 좌결합은 반복문","'세거나 같으면 내보내기' 의 같음이 좌결합","후위 계산: 먼저 pop 이 오른쪽"]},"q":[{"t":"code","run":"js","k":"어휘 분석 — 최장 일치","cat":"internals","q":"<b>어휘 분석기(lexer)</b>를 구현하세요. <code>lex(srcText)</code> 는 소문자 식별자(<code>a-z</code> 시작, 이후 숫자 허용)·정수·연산자(<code>+ - * / = ==</code>)를 토큰으로 자릅니다. 공백은 건너뛰고, <b><code>==</code> 는 <code>=</code> 두 개가 아니라 한 토큰</b>(최장 일치)이며, 모르는 문자를 만나면 <code>null</code> 입니다.","src":"function lex(srcText) {\n  // TODO: 최장 일치로 토큰 자르기\n  return srcText.split(' ').map((w) => ({ t: 'id', v: w }));\n}","sol":"function lex(srcText) {\n  const out = [];\n  let i = 0;\n  while (i < srcText.length) {\n    const ch = srcText[i];\n    if (ch === ' ') { i++; continue; }\n    if (/[0-9]/.test(ch)) {\n      let j = i; while (j < srcText.length && /[0-9]/.test(srcText[j])) j++;\n      out.push({ t: 'num', v: Number(srcText.slice(i, j)) }); i = j; continue;\n    }\n    if (/[a-z]/.test(ch)) {\n      let j = i; while (j < srcText.length && /[a-z0-9]/.test(srcText[j])) j++;\n      out.push({ t: 'id', v: srcText.slice(i, j) }); i = j; continue;\n    }\n    if (srcText.slice(i, i + 2) === '==') { out.push({ t: 'op', v: '==' }); i += 2; continue; }\n    if ('+-*/='.includes(ch)) { out.push({ t: 'op', v: ch }); i++; continue; }\n    return null;\n  }\n  return out;\n}","tests":[{"in":"lex('ab1 = 10')","out":"[{t:'id',v:'ab1'},{t:'op',v:'='},{t:'num',v:10}]"},{"in":"lex('a==b')","out":"[{t:'id',v:'a'},{t:'op',v:'=='},{t:'id',v:'b'}]"},{"in":"lex('12+345')","out":"[{t:'num',v:12},{t:'op',v:'+'},{t:'num',v:345}]"},{"in":"lex('a $ b')","out":"null"}],"edge":[{"in":"lex('')","out":"[]"},{"in":"lex('x=1==2')","out":"[{t:'id',v:'x'},{t:'op',v:'='},{t:'num',v:1},{t:'op',v:'=='},{t:'num',v:2}]"}],"ex":"렉서의 제1규칙은 <b>최장 일치(maximal munch)</b>입니다. <code>==</code> 를 보면 <code>=</code> 두 개가 아니라 가장 긴 토큰 하나로 자릅니다 — 그래서 <b><code>==</code> 검사를 <code>=</code> 보다 먼저</b> 해야 합니다. 순서를 바꾸면 render 는 되는데 파서가 엉뚱한 곳에서 죽습니다.\n숫자·식별자도 같은 원리입니다. <code>345</code> 는 '3, 4, 5' 가 아니라 한 덩어리를 <b>끝까지 읽고</b> 하나의 토큰으로 만듭니다. 렉서는 '문자를 상태에 따라 묶는' 유한 상태 기계입니다.\n모르는 문자를 조용히 건너뛰면 <b>오류 위치가 파서로 밀려나</b> 진단이 어려워집니다. 렉서 단계에서 즉시 실패해야 '몇 번째 글자가 문제' 라고 말할 수 있습니다.\n자바스크립트의 유명한 함정 <code>a+++b</code> 가 <code>(a++)+b</code> 로 읽히는 것도 최장 일치 때문입니다. 문법 설계는 렉서 규칙까지 고려해야 합니다."},{"t":"code","run":"js","k":"재귀 하강 파서","cat":"internals","q":"<b>재귀 하강</b>으로 수식을 계산하세요. <code>evalExpr(s)</code> 는 <code>+ - * / ( )</code> 와 정수로 된 식(공백 없음)을 계산합니다. 문법은 <code>expr → term (±term)*</code>, <code>term → factor (×÷factor)*</code>, <code>factor → 숫자 | (expr)</code> 이고, <b>같은 우선순위는 왼쪽부터</b>(<code>10-2-3 = 5</code>) 계산합니다.","src":"function evalExpr(s) {\n  // TODO: expr → term → factor\n  let acc = 0;\n  s.split(/[+]/).forEach((part) => { acc += Number(part) || 0; });\n  return acc;\n}","sol":"function evalExpr(s) {\n  let pos = 0;\n  const factor = () => {\n    if (s[pos] === '(') { pos++; const v = expr(); pos++; return v; }\n    let j = pos; while (j < s.length && /[0-9]/.test(s[j])) j++;\n    const v = Number(s.slice(pos, j)); pos = j; return v;\n  };\n  const term = () => {\n    let v = factor();\n    while (s[pos] === '*' || s[pos] === '/') { const op = s[pos++]; const w = factor(); v = op === '*' ? v * w : v / w; }\n    return v;\n  };\n  const expr = () => {\n    let v = term();\n    while (s[pos] === '+' || s[pos] === '-') { const op = s[pos++]; const w = term(); v = op === '+' ? v + w : v - w; }\n    return v;\n  };\n  return expr();\n}","tests":[{"in":"evalExpr('2+3*4')","out":"14"},{"in":"evalExpr('(2+3)*4')","out":"20"},{"in":"evalExpr('10-2-3')","out":"5"},{"in":"evalExpr('20/2/5')","out":"2"}],"edge":[{"in":"evalExpr('7')","out":"7"},{"in":"evalExpr('2*(3+4)-5')","out":"9"}],"ex":"우선순위는 <b>문법 계층</b>으로 표현됩니다. <code>expr</code> 가 <code>term</code> 을 부르고 <code>term</code> 이 <code>factor</code> 를 부르는 구조에서, <b>아래층일수록 먼저 묶입니다</b> — 그래서 <code>*</code> 가 <code>+</code> 보다 세게 결합합니다.\n좌결합은 <b>재귀가 아니라 반복문</b>으로 만듭니다. <code>10-2-3</code> 을 <code>while</code> 로 왼쪽부터 누적하면 <code>(10−2)−3 = 5</code>. 오른쪽 재귀로 쓰면 <code>10−(2−3) = 11</code> 이 됩니다 — 뺄셈·나눗셈에서만 드러나는 함정이라 덧셈으로만 테스트하면 못 잡습니다.\n괄호는 <code>factor</code> 안에서 <code>expr</code> 를 다시 부르는 <b>상호 재귀</b>로 처리됩니다. 이 되부름이 중첩 괄호를 공짜로 처리해 줍니다.\n진짜 컴파일러의 파서도 구조는 같습니다 — 값을 바로 계산하는 대신 <b>AST 노드를 만들어</b> 돌려줄 뿐입니다. 이 계산기에서 <code>return v</code> 를 <code>return {op, left, right}</code> 로 바꾸면 파서가 됩니다."},{"t":"code","run":"js","k":"션팅 야드와 후위 계산","cat":"internals","q":"<b>션팅 야드</b> 알고리즘을 구현하세요. <code>toPostfix(s)</code> 는 공백으로 구분된 중위 표기식을 후위 표기로 바꿉니다(<code>* /</code> 가 <code>+ -</code> 보다 우선, 같은 우선순위는 좌결합, 괄호 지원). <code>evalPostfix(s)</code> 는 후위 표기를 스택으로 계산합니다 — <b>pop 순서에 주의</b>: 먼저 pop 한 것이 <b>오른쪽</b> 피연산자입니다.","src":"function toPostfix(s) {\n  // TODO: 연산자 스택으로 변환\n  return s;\n}\n\nfunction evalPostfix(s) {\n  // TODO: 스택 계산 — pop 순서 주의\n  return 0;\n}","sol":"function toPostfix(s) {\n  const prec = { '+': 1, '-': 1, '*': 2, '/': 2 };\n  const out = [], ops = [];\n  s.split(' ').forEach((t) => {\n    if (t === '(') ops.push(t);\n    else if (t === ')') { while (ops[ops.length - 1] !== '(') out.push(ops.pop()); ops.pop(); }\n    else if (prec[t]) {\n      while (ops.length && prec[ops[ops.length - 1]] >= prec[t]) out.push(ops.pop());\n      ops.push(t);\n    } else out.push(t);\n  });\n  return out.concat(ops.reverse()).join(' ');\n}\n\nfunction evalPostfix(s) {\n  const st = [];\n  s.split(' ').forEach((t) => {\n    if (t.length === 1 && '+-*/'.includes(t)) {\n      const b = st.pop(), a = st.pop();\n      st.push(t === '+' ? a + b : t === '-' ? a - b : t === '*' ? a * b : a / b);\n    } else st.push(Number(t));\n  });\n  return st[0];\n}","tests":[{"in":"toPostfix('3 + 4 * 2')","out":"'3 4 2 * +'"},{"in":"toPostfix('( 1 + 2 ) * 3')","out":"'1 2 + 3 *'"},{"in":"evalPostfix('10 2 -')","out":"8"},{"in":"evalPostfix('5 1 2 + 4 * + 3 -')","out":"14"}],"edge":[{"in":"toPostfix('1 - 2 - 3')","out":"'1 2 - 3 -'"},{"in":"evalPostfix('6 2 /')","out":"3"}],"ex":"후위 표기의 매력은 <b>괄호와 우선순위가 사라진다</b>는 것입니다. 변환할 때 이미 순서가 결정되어, 계산기는 스택 하나로 왼쪽에서 오른쪽으로 읽기만 하면 됩니다.\n변환 규칙의 핵심은 '<b>스택 위의 연산자가 나보다 세거나 같으면 먼저 내보낸다</b>' 입니다. '같으면' 이 좌결합을 만듭니다 — <code>1 - 2 - 3</code> 이 <code>1 2 - 3 -</code> 이 되는 이유입니다. <code>&gt;=</code> 를 <code>&gt;</code> 로 바꾸면 우결합이 되어 답이 달라집니다.\n계산에서 가장 흔한 버그는 <b>pop 순서</b>입니다. 먼저 pop 한 값이 <b>오른쪽</b> 피연산자라 <code>a - b</code> 의 a 는 <b>두 번째</b> pop 입니다. 덧셈·곱셈은 교환법칙 때문에 버그가 숨고, 뺄셈에서야 드러납니다.\nJVM·파이썬 바이트코드가 정확히 이 구조의 스택 머신입니다. 컴파일 = 중위(사람의 표기) → 후위(기계의 순서) 변환이라는 감각을 이 문제로 얻을 수 있습니다."}]}],"ord":12},{"t":"실행형 실전 — 작은 예제만 통과하는 컴파일러 코드 고치기","l":[{"t":"앞단 — 읽고 나누고 세는 곳","xp":80,"th":{"sum":"렉서·파서 버그는 **문법의 규칙을 코드가 반만 옮겼을 때** 난다 — 최장 일치, 상태, 결합 방향, 마무리 단계.","body":[{"h":"가장 긴 것부터, 낱말이 끝난 뒤에","t":"렉서의 원칙은 <b>최장 일치</b>다. 기호를 한 글자씩 집으면 <code>==</code> 가 둘로 쪼개지므로 연산자 표는 <b>긴 것부터</b> 맞춰 본다. 반대로 키워드는 <b>식별자를 끝까지 읽은 다음</b> 목록에 있는지 본다 — 먼저 맞춰 보면 <code>iffy</code> 가 <code>if</code>+<code>fy</code> 로 쪼개지고 <code>int</code> 가 <code>in</code> 으로 읽힌다. 그리고 문자열·주석 안인지는 <b>지금까지 읽은 것</b>에 달린 상태라, 정규식 하나로는 절대 셀 수 없다."},{"h":"결합 방향과 마무리 단계","t":"<code>-</code> 와 <code>+</code> 는 <b>좌결합</b>이다 — 재귀 하강에서 오른쪽 항을 다시 <code>expr()</code> 로 읽으면 <code>1-(2-3)</code> 이 된다. 좌결합은 <b>반복</b>으로, 우결합은 재귀로 적는다. 션팅 야드는 본문 반복이 끝난 뒤 <b>스택을 비우는 드레인</b> 단계가 명세의 마지막 줄이다. 진단의 줄 번호는 <code>split('\\n').length</code> 가 곧 1 기반 줄 수이고, 매크로 치환은 <b>낱말 단위</b>로 한 번만 훑어야 순서 의존성이 사라진다."}],"code":{"c":"if (TWO.includes(s.slice(i, i + 2))) { … }   // 긴 것부터\nwhile (t[i] === '-' || t[i] === '+') { … }   // 좌결합은 반복으로\nwhile (ops.length) out.push(ops.pop());      // 마무리 드레인","cap":"문법의 규칙을 빠짐없이 옮긴다"},"key":["연산자 표는 긴 것부터 시도한다","키워드는 낱말을 다 읽고 판정한다","상태가 필요하면 렉서를 거친다","좌결합은 반복, 우결합은 재귀"]},"q":[{"t":"code","run":"js","k":"두 글자 연산자가 한 글자씩 쪼개진다","cat":"debug","q":"아주 작은 렉서입니다. 소문자 식별자와 기호를 토큰으로 나누고 공백은 버립니다. <code>==</code>·<code>!=</code>·<code>&lt;=</code>·<code>&gt;=</code> 는 <b>한 토큰</b>이어야 하는데, 파서가 <code>=</code> 를 두 개 받았다며 오류를 냅니다.","src":"function tokenize(s) {\n  const out = [];\n  let i = 0;\n  while (i < s.length) {\n    if (s[i] === ' ') { i += 1; continue; }\n    if (/[a-z]/.test(s[i])) {\n      let j = i;\n      while (j < s.length && /[a-z]/.test(s[j])) j += 1;\n      out.push(s.slice(i, j));\n      i = j;\n      continue;\n    }\n    out.push(s[i]);\n    i += 1;\n  }\n  return out;\n}","sol":"const TWO = ['==', '!=', '<=', '>='];\nfunction tokenize(s) {\n  const out = [];\n  let i = 0;\n  while (i < s.length) {\n    if (s[i] === ' ') { i += 1; continue; }\n    if (TWO.includes(s.slice(i, i + 2))) { out.push(s.slice(i, i + 2)); i += 2; continue; }\n    if (/[a-z]/.test(s[i])) {\n      let j = i;\n      while (j < s.length && /[a-z]/.test(s[j])) j += 1;\n      out.push(s.slice(i, j));\n      i = j;\n      continue;\n    }\n    out.push(s[i]);\n    i += 1;\n  }\n  return out;\n}","tests":[{"in":"tokenize('a==b')","out":"['a','==','b']"},{"in":"tokenize('a<=b')","out":"['a','<=','b']"},{"in":"tokenize('a+b')","out":"['a','+','b']"},{"in":"tokenize('x = y')","out":"['x','=','y']"}],"edge":[{"in":"tokenize('')","out":"[]"},{"in":"tokenize('a!=b')","out":"['a','!=','b']"}],"ex":"원인: 기호를 <b>한 글자씩</b> 집어 내보내고 있습니다. 렉서는 '<b>가장 긴 것부터 맞춰 본다</b>'(최장 일치)가 원칙인데, 그 규칙이 없으니 <code>==</code> 가 <code>=</code> 둘로 쪼개집니다. 단일 문자 연산자만 쓴 예제에서는 전부 통과합니다.\n해결: 기호를 집기 전에 <b>두 글자짜리 목록</b>을 먼저 맞춰 봅니다. 맞으면 두 칸을 함께 소비합니다.\n재발 방지: 연산자 표는 <b>긴 것부터 짧은 것 순서</b>로 정렬해 두고 그 순서대로 시도하세요. 세 글자짜리(<code>===</code>·<code>&lt;&lt;=</code>)가 늘어나도 규칙이 그대로 통합니다. 그리고 테스트에는 <b>접두사가 겹치는 연산자 쌍</b>(<code>=</code> 와 <code>==</code>, <code>&lt;</code> 와 <code>&lt;=</code>)을 반드시 함께 넣으세요."},{"t":"code","run":"js","k":"키워드가 식별자의 앞부분을 잘라먹는다","cat":"debug","q":"토큰에 <code>KW:</code>(키워드)와 <code>ID:</code>(식별자) 딱지를 붙입니다. 키워드는 <code>if</code>·<code>in</code>·<code>int</code> 셋입니다. 그런데 <code>iffy</code> 같은 변수 이름이 <b>키워드와 식별자로 쪼개지고</b>, <code>int</code> 는 <code>in</code> 으로 읽힙니다.","src":"const KW = ['if', 'in', 'int'];\nfunction classify(s) {\n  const out = [];\n  let i = 0;\n  while (i < s.length) {\n    const kw = KW.find(k => s.startsWith(k, i));\n    if (kw) { out.push('KW:' + kw); i += kw.length; continue; }\n    let j = i;\n    while (j < s.length && /[a-z]/.test(s[j])) j += 1;\n    if (j === i) { i += 1; continue; }\n    out.push('ID:' + s.slice(i, j));\n    i = j;\n  }\n  return out;\n}","sol":"const KW = ['if', 'in', 'int'];\nfunction classify(s) {\n  const out = [];\n  let i = 0;\n  while (i < s.length) {\n    let j = i;\n    while (j < s.length && /[a-z]/.test(s[j])) j += 1;\n    if (j === i) { i += 1; continue; }\n    const w = s.slice(i, j);\n    out.push((KW.includes(w) ? 'KW:' : 'ID:') + w);\n    i = j;\n  }\n  return out;\n}","tests":[{"in":"classify('iffy')","out":"['ID:iffy']"},{"in":"classify('int')","out":"['KW:int']"},{"in":"classify('int x')","out":"['KW:int','ID:x']"},{"in":"classify('if')","out":"['KW:if']"}],"edge":[{"in":"classify('')","out":"[]"},{"in":"classify('foo')","out":"['ID:foo']"}],"ex":"원인: <b>키워드를 먼저 맞춰 본</b> 것이 잘못입니다. 키워드는 식별자의 <b>앞부분</b>일 수 있으므로, <code>iffy</code> 를 만나면 <code>if</code> 가 먼저 걸립니다. <code>KW.find</code> 는 목록의 앞에서부터 찾으므로 <code>int</code> 도 <code>in</code> 으로 읽힙니다 — 목록 순서에 답이 딸려 가는 것 자체가 위험 신호입니다.\n해결: <b>식별자를 끝까지 읽은 다음</b> 그 낱말이 키워드 목록에 있는지 봅니다. 렉서의 표준 방식이며 목록 순서와 무관해집니다.\n재발 방지: '키워드는 <b>예약된 식별자</b>' 라는 정의를 코드 구조가 그대로 담아야 합니다. 테스트에는 <b>키워드로 시작하는 식별자</b>(<code>iffy</code>·<code>inner</code>)와 <b>다른 키워드의 접두사인 키워드</b>(<code>in</code> 과 <code>int</code>)를 반드시 넣으세요."},{"t":"code","run":"js","k":"문자열과 주석 안의 기호까지 센다","cat":"debug","q":"소스에서 <b>문장 구분자 <code>;</code> 의 개수</b>를 셉니다. 작은따옴표 문자열 안이나 <code>//</code> 주석 뒤의 <code>;</code> 는 <b>세지 않아야</b> 합니다. 그런데 문자열이나 주석이 들어간 파일에서 개수가 부풀려집니다.","src":"function countSemis(src) {\n  return (src.match(/;/g) || []).length;\n}","sol":"function countSemis(src) {\n  let n = 0, i = 0, inStr = false;\n  while (i < src.length) {\n    const c = src[i];\n    if (inStr) {\n      if (c === '\\\\') i += 1;\n      else if (c === \"'\") inStr = false;\n    } else if (c === \"'\") inStr = true;\n    else if (c === '/' && src[i + 1] === '/') {\n      while (i < src.length && src[i] !== '\\n') i += 1;\n      continue;\n    } else if (c === ';') n += 1;\n    i += 1;\n  }\n  return n;\n}","tests":[{"in":"countSemis(\"x = ';';\")","out":"1"},{"in":"countSemis('a; // b;')","out":"1"},{"in":"countSemis(\"a;\\n// c;\\nb;\")","out":"2"},{"in":"countSemis('a; b;')","out":"2"}],"edge":[{"in":"countSemis('')","out":"0"},{"in":"countSemis(\"';;;'\")","out":"0"}],"ex":"원인: 정규식은 소스를 <b>글자의 나열</b>로만 봅니다. 문자열 리터럴 안인지 주석 안인지는 <b>지금까지 읽은 것</b>에 따라 달라지는 <b>상태</b>인데, 정규식 하나에는 그 상태가 없습니다. 주석도 문자열도 없는 예제 파일에서는 언제나 통과합니다.\n해결: 앞에서부터 한 글자씩 읽으며 <b>'지금 문자열 안인가'</b> 를 들고 다닙니다. 이스케이프(<code>\\\\</code>)는 다음 글자를 통째로 건너뛰고, 줄 주석은 줄 끝까지 건너뜁니다. 이것이 곧 <b>렉서를 상태 기계로 쓰는</b> 이유입니다.\n재발 방지: '소스 코드를 정규식으로 훑는다' 는 아이디어는 <b>중첩과 상태가 없는 문법</b>에서만 통합니다. 세거나 바꿔야 할 대상이 문자열·주석·정규식 리터럴 안에 나타날 수 있다면 반드시 <b>렉서를 거치세요</b> — 테스트에는 그 셋을 각각 하나씩 넣습니다."},{"t":"code","run":"js","k":"뺄셈이 오른쪽부터 묶인다","cat":"debug","q":"한 자리 숫자와 <code>+</code>·<code>-</code> 만 있는 식을 계산하는 재귀 하강 파서입니다. 연산자가 하나면 맞는데, <code>1-2-3</code> 처럼 <b>두 개 이상 이어지면</b> 답이 다릅니다.","src":"function evalExpr(s) {\n  const t = s.split('').filter(c => c !== ' ');\n  let i = 0;\n  const expr = () => {\n    const left = Number(t[i]);\n    i += 1;\n    if (t[i] === '-' || t[i] === '+') {\n      const op = t[i];\n      i += 1;\n      const right = expr();\n      return op === '-' ? left - right : left + right;\n    }\n    return left;\n  };\n  return expr();\n}","sol":"function evalExpr(s) {\n  const t = s.split('').filter(c => c !== ' ');\n  let i = 0;\n  let acc = Number(t[i]);\n  i += 1;\n  while (t[i] === '-' || t[i] === '+') {\n    const op = t[i];\n    i += 1;\n    const right = Number(t[i]);\n    i += 1;\n    acc = op === '-' ? acc - right : acc + right;\n  }\n  return acc;\n}","tests":[{"in":"evalExpr('1-2-3')","out":"-4"},{"in":"evalExpr('9-1-1-1')","out":"6"},{"in":"evalExpr('1-2')","out":"-1"},{"in":"evalExpr('5')","out":"5"}],"edge":[{"in":"evalExpr('8-3+2')","out":"7"},{"in":"evalExpr('0')","out":"0"}],"ex":"원인: 오른쪽 항을 <b>다시 <code>expr()</code> 로</b> 읽으면 <code>1-(2-3)</code> 처럼 <b>오른쪽부터 묶입니다</b>(우결합). 그런데 <code>-</code> 와 <code>+</code> 는 <b>왼쪽부터 묶이는</b>(좌결합) 연산자입니다. 연산자가 하나뿐이면 결합 방향이 결과를 바꾸지 않아 통과합니다.\n해결: 재귀 대신 <b>반복</b>으로 왼쪽부터 접습니다. 누적값에 오른쪽 항을 차례로 적용하면 그것이 곧 좌결합입니다.\n재발 방지: 재귀 하강에서 <b>좌결합은 반복으로, 우결합은 재귀로</b> 적습니다(<code>**</code>·<code>=</code> 가 우결합입니다). 문법을 적을 때부터 <code>expr := term (('+'|'-') term)*</code> 처럼 <b>반복 형태</b>로 쓰면 코드가 저절로 맞고, 테스트에는 <b>같은 연산자를 세 개 이상</b> 이은 식을 두세요."},{"t":"code","run":"js","k":"스택에 남은 연산자를 안 비운다","cat":"debug","q":"션팅 야드 알고리즘으로 중위식을 <b>후위식(RPN)</b>으로 바꿉니다. 피연산자와 연산자는 한 글자이고 괄호는 없습니다. 그런데 결과에 <b>연산자가 통째로 빠져</b> 있습니다.","src":"function toRpn(s) {\n  const prec = { '+': 1, '-': 1, '*': 2 };\n  const out = [], ops = [];\n  for (const c of s.split('').filter(x => x !== ' ')) {\n    if (prec[c]) {\n      while (ops.length && prec[ops[ops.length - 1]] >= prec[c]) out.push(ops.pop());\n      ops.push(c);\n    } else out.push(c);\n  }\n  return out;\n}","sol":"function toRpn(s) {\n  const prec = { '+': 1, '-': 1, '*': 2 };\n  const out = [], ops = [];\n  for (const c of s.split('').filter(x => x !== ' ')) {\n    if (prec[c]) {\n      while (ops.length && prec[ops[ops.length - 1]] >= prec[c]) out.push(ops.pop());\n      ops.push(c);\n    } else out.push(c);\n  }\n  while (ops.length) out.push(ops.pop());\n  return out;\n}","tests":[{"in":"toRpn('1+2')","out":"['1','2','+']"},{"in":"toRpn('1+2*3')","out":"['1','2','3','*','+']"},{"in":"toRpn('1*2+3')","out":"['1','2','*','3','+']"},{"in":"toRpn('5')","out":"['5']"}],"edge":[{"in":"toRpn('')","out":"[]"},{"in":"toRpn('1-2-3')","out":"['1','2','-','3','-']"}],"ex":"원인: 연산자는 <b>더 낮거나 같은 우선순위를 만날 때</b>만 스택에서 나옵니다. 입력이 끝나면 그런 기회가 더 없으므로, 스택에 남아 있던 연산자들이 <b>결과에 실리지 않습니다</b>. 피연산자만 있는 입력(<code>'5'</code>)에서는 스택이 비어 있어 통과합니다.\n해결: 입력을 다 읽은 뒤 <b>스택을 위에서부터 전부 비워</b> 출력에 붙입니다. 알고리즘 명세의 마지막 줄이 바로 이 '드레인' 단계입니다.\n재발 방지: 스택을 쓰는 변환은 대부분 <b>본문 반복 + 마무리 드레인</b> 두 부분입니다. 어느 한쪽만 적으면 짧은 입력에서만 맞습니다. 결과 길이를 세는 성질 테스트(<b>토큰 수는 보존된다</b>)를 두면 이 누락이 즉시 드러납니다."},{"t":"code","run":"js","k":"오류 줄 번호가 하나씩 앞선다","cat":"debug","q":"오프셋을 <b>줄·칸 번호</b>로 바꿉니다. 둘 다 <b>1 부터</b> 셉니다. 칸은 맞는데 <b>줄 번호가 언제나 하나씩 작아</b>, 편집기가 엉뚱한 줄에 밑줄을 긋습니다.","src":"function posOf(src, pos) {\n  const before = src.slice(0, pos);\n  const line = before.split('\\n').length - 1;\n  const col = pos - before.lastIndexOf('\\n');\n  return [line, col];\n}","sol":"function posOf(src, pos) {\n  const before = src.slice(0, pos);\n  const line = before.split('\\n').length;\n  const col = pos - before.lastIndexOf('\\n');\n  return [line, col];\n}","tests":[{"in":"posOf('a\\nb', 0)","out":"[1,1]"},{"in":"posOf('a\\nb', 2)","out":"[2,1]"},{"in":"posOf('abc', 3)","out":"[1,4]"},{"in":"posOf('a\\n\\nb', 3)","out":"[3,1]"}],"edge":[{"in":"posOf('', 0)","out":"[1,1]"},{"in":"posOf('a\\nbcd', 4)","out":"[2,3]"}],"ex":"원인: <code>split('\\n')</code> 이 돌려주는 조각 수가 곧 <b>줄 수</b>입니다 — 줄바꿈이 하나도 없으면 조각 하나, 즉 1 번째 줄입니다. 거기서 1 을 더 빼면 <b>0 부터 세는 번호</b>가 되어 편집기가 쓰는 1 기반 번호와 어긋납니다. 칸 번호는 <code>lastIndexOf</code> 가 없을 때 <code>-1</code> 을 주는 덕에 우연히 1 기반으로 맞았습니다.\n해결: 빼기를 없앱니다. '조각 수 = 줄 번호' 라는 관계를 그대로 씁니다.\n재발 방지: 진단 메시지의 자리 정보는 <b>0 기반과 1 기반이 만나는 대표적인 자리</b>입니다. 내부는 0 기반 오프셋으로만 다루고 <b>사람에게 보여 줄 때 한 번만</b> 1 을 더하도록 층을 나누세요. 테스트에는 <b>첫 글자</b>·<b>줄바꿈 직후</b>·<b>빈 줄</b> 세 가지를 넣습니다."},{"t":"code","run":"js","k":"매크로 인자가 낱말 안까지 치환된다","cat":"debug","q":"아주 단순한 매크로 확장기입니다. 인자 이름이 <b>낱말 하나로 나올 때만</b> 값으로 바꿔야 합니다. 그런데 <code>x</code> 를 바꾸면 <code>xy</code> 의 앞글자까지 바뀌고, 이름이 서로의 앞부분이면 순서에 따라 결과가 달라집니다.","src":"function expand(tmpl, args) {\n  let out = tmpl;\n  for (const k of Object.keys(args)) out = out.split(k).join(String(args[k]));\n  return out;\n}","sol":"function expand(tmpl, args) {\n  return tmpl.replace(/[A-Za-z_][A-Za-z0-9_]*/g,\n    w => (Object.prototype.hasOwnProperty.call(args, w) ? String(args[w]) : w));\n}","tests":[{"in":"expand('x + xy', { x: 1 })","out":"'1 + xy'"},{"in":"expand('ab + a', { a: 1, ab: 2 })","out":"'2 + 1'"},{"in":"expand('aa', { a: 1 })","out":"'aa'"},{"in":"expand('a', { a: 2 })","out":"'2'"}],"edge":[{"in":"expand('', { a: 1 })","out":"''"},{"in":"expand('z', { a: 1 })","out":"'z'"}],"ex":"원인: <code>split</code>/<code>join</code> 은 <b>글자 나열</b>을 바꿉니다. 매크로 인자는 <b>낱말(토큰)</b> 단위인데 그 경계를 모르니 <code>xy</code> 의 앞글자까지 먹습니다. 게다가 이름을 <b>하나씩 차례로</b> 바꾸므로, 짧은 이름을 먼저 바꾸면 긴 이름이 이미 사라져 결과가 <code>Object.keys</code> 순서에 딸려 갑니다.\n해결: 소스를 <b>낱말 단위로 훑으면서</b> 그 낱말이 인자 목록에 있을 때만 바꿉니다. 한 번의 훑기로 끝나므로 순서 의존성도 함께 사라집니다.\n재발 방지: 치환은 <b>파싱한 단위</b> 위에서 해야 합니다. 낱말·경로 조각·SQL 자리표 모두 같습니다. 그리고 '<b>여러 번 치환</b>' 은 앞선 치환의 결과를 다시 치환할 위험이 있으므로 <b>한 번의 훑기</b>로 끝내세요 — 테스트에는 <b>이름이 서로의 앞부분인 경우</b>를 반드시 넣습니다."}]},{"t":"뒷단 — 이름·순서·부수효과","xp":80,"th":{"sum":"뒷단의 버그는 **방문 순서와 수명**에서 온다 — 어디서 이름을 찾는가, 언제 판정하는가, 무엇을 지워도 되는가.","body":[{"h":"이름의 수명과 바인딩의 개수","t":"렉시컬 스코프는 <b>맵의 스택</b>이다 — 블록마다 얹고 벗기며, 조회는 안쪽부터 바깥으로 훑는다. 맵 하나로 두면 안쪽 선언이 바깥 이름을 영구히 덮는다. 같은 문제가 클로저에도 나타난다 — <code>var</code> 는 함수 하나를 스코프로 삼아 <b>모든 클로저가 변수 하나</b>를 잡고, <code>let</code> 은 반복마다 <b>새 바인딩</b>을 만든다. 요는 '바인딩을 언제 새로 만드는가' 다."},{"h":"방문 순서와 지워도 되는 것","t":"트리 패스는 방문 순서가 곧 알고리즘이다 — 상수 접기·타입 추론은 <b>아래에서 위로</b>(후위), 스코프 주입은 위에서 아래로(전위). 링커의 심볼 해석처럼 <b>전방 참조</b>가 있는 판정은 '모으고 나서 판정' 두 패스로 해야 파일 순서에 안 흔들린다. 최적화는 '<b>관찰 가능한 동작을 바꾸지 않는다</b>' 는 약속 위에서만 정당하므로, 부수효과 여부를 모르면 <b>보수적으로 있음</b>으로 둔다. 그리고 스택은 <b>나중 것이 먼저 나온다</b> — 첫 pop 이 오른쪽 피연산자다."}],"code":{"c":"for (let i = stack.length - 1; i >= 0; i -= 1) …   // 안쪽부터 바깥으로\nconst l = fold(n.l), r = fold(n.r);                // 자식을 먼저\nit.eff || used.has(it.dst)                         // 부수효과도 살아 있음","cap":"순서가 정당성의 근거다"},"key":["스코프는 맵의 스택으로","클로저는 바인딩 개수를 세어 본다","전방 참조가 있으면 두 패스로","교환법칙 없는 연산으로 테스트한다"]},"q":[{"t":"code","run":"js","k":"블록을 빠져나가도 이름이 살아 있다","cat":"debug","q":"아주 작은 이름 해석기입니다. <code>push</code>·<code>pop</code> 은 블록의 시작과 끝, <code>let</code> 은 선언, <code>use</code> 는 조회이며 없으면 <code>null</code> 입니다. 그런데 <b>블록 안에서 선언한 이름이 블록 밖에서도</b> 보이고, 바깥 이름은 <b>안쪽 값으로 덮인 채</b> 돌아옵니다.","src":"function resolve(prog) {\n  const scope = new Map();\n  const out = [];\n  for (const st of prog) {\n    if (st[0] === 'let') scope.set(st[1], st[2]);\n    if (st[0] === 'use') out.push(scope.has(st[1]) ? scope.get(st[1]) : null);\n  }\n  return out;\n}","sol":"function resolve(prog) {\n  const stack = [new Map()];\n  const out = [];\n  for (const st of prog) {\n    if (st[0] === 'push') stack.push(new Map());\n    else if (st[0] === 'pop') stack.pop();\n    else if (st[0] === 'let') stack[stack.length - 1].set(st[1], st[2]);\n    else if (st[0] === 'use') {\n      let v = null;\n      for (let i = stack.length - 1; i >= 0; i -= 1) {\n        if (stack[i].has(st[1])) { v = stack[i].get(st[1]); break; }\n      }\n      out.push(v);\n    }\n  }\n  return out;\n}","tests":[{"in":"resolve([['let','x',1],['push'],['let','x',2],['use','x'],['pop'],['use','x']])","out":"[2,1]"},{"in":"resolve([['push'],['let','y',5],['pop'],['use','y']])","out":"[null]"},{"in":"resolve([['let','x',1],['use','x']])","out":"[1]"},{"in":"resolve([['use','z']])","out":"[null]"}],"edge":[{"in":"resolve([])","out":"[]"},{"in":"resolve([['push'],['use','q'],['pop']])","out":"[null]"}],"ex":"원인: 심볼 테이블이 <b>맵 하나</b>뿐이라 블록 개념이 없습니다. 안쪽 선언이 바깥 이름을 <b>영구히 덮어쓰고</b>, 블록을 나가도 지워지지 않습니다. 블록이 없거나 이름이 겹치지 않는 예제에서는 완벽히 동작합니다.\n해결: 맵을 <b>스택</b>으로 쌓습니다. <code>push</code> 는 새 맵을 얹고 <code>pop</code> 은 벗기며, 조회는 <b>안쪽부터 바깥으로</b> 훑습니다. 이것이 렉시컬 스코프의 정의 그대로입니다.\n재발 방지: 이름 해석 테스트의 핵심은 <b>가림(shadowing)</b>과 <b>수명</b>입니다 — 안쪽에서 같은 이름을 선언하고 나간 뒤 바깥 값이 <b>원래대로</b>인지, 안쪽 이름이 밖에서 <b>안 보이는지</b> 두 가지를 항상 확인하세요. 나중에 클로저를 붙이려면 <code>pop</code> 대신 <b>스코프를 노드에 매다는</b> 설계로 바꿔야 합니다."},{"t":"code","run":"js","k":"클로저가 반복 변수를 함께 쓴다","cat":"debug","q":"목록의 각 원소를 돌려주는 <b>함수들</b>을 만들고, 만든 순서대로 불러 결과를 모읍니다. 원소가 없으면 빈 배열입니다. 그런데 결과가 전부 <code>null</code> 로 나옵니다.","src":"function makeGetters(ns) {\n  const out = [];\n  for (var i = 0; i < ns.length; i += 1) out.push(() => ns[i]);\n  return out.map(f => f());\n}","sol":"function makeGetters(ns) {\n  const out = [];\n  for (let i = 0; i < ns.length; i += 1) out.push(() => ns[i]);\n  return out.map(f => f());\n}","tests":[{"in":"makeGetters([1,2,3])","out":"[1,2,3]"},{"in":"makeGetters([9])","out":"[9]"},{"in":"makeGetters([1,2])","out":"[1,2]"},{"in":"makeGetters([])","out":"[]"}],"edge":[{"in":"makeGetters([0])","out":"[0]"},{"in":"makeGetters([5,6,7])","out":"[5,6,7]"}],"ex":"원인: <code>var</code> 는 <b>함수 하나를 통째로</b> 스코프로 삼습니다. 그래서 반복문이 만든 모든 화살표 함수가 <b>같은 변수 <code>i</code> 하나</b>를 붙듭니다. 반복이 끝나면 <code>i</code> 는 <code>ns.length</code> 이므로 전부 범위 밖을 읽어 <code>undefined</code> 가 나옵니다.\n해결: <code>let</code> 은 <b>반복마다 새 바인딩</b>을 만듭니다. 각 함수가 자기 몫의 <code>i</code> 를 잡으므로 만든 시점의 값이 그대로 남습니다.\n재발 방지: 컴파일러 눈으로 보면 이것은 '<b>바인딩을 언제 새로 만드는가</b>' 의 문제입니다. 클로저를 만드는 반복문에서는 잡히는 변수의 <b>수명과 개수</b>를 먼저 세어 보세요. 함수를 만들어 모아 두었다가 <b>나중에 부르는</b> 코드(콜백 등록·지연 평가·태스크 큐)가 이 버그의 단골 자리입니다."},{"t":"code","run":"js","k":"상수 접기가 한 겹만 내려간다","cat":"debug","q":"덧셈 트리에서 <b>상수끼리의 덧셈</b>을 미리 계산해 접습니다. 노드는 <code>num</code>·<code>var</code>·<code>add</code> 셋입니다. 한 겹짜리 식은 접히는데, <b>중첩된 식</b>은 그대로 남습니다.","src":"function fold(n) {\n  if (n.k === 'num') return n;\n  if (n.l.k === 'num' && n.r.k === 'num') return { k: 'num', v: n.l.v + n.r.v };\n  return n;\n}","sol":"function fold(n) {\n  if (n.k === 'num' || n.k === 'var') return n;\n  const l = fold(n.l), r = fold(n.r);\n  if (l.k === 'num' && r.k === 'num') return { k: 'num', v: l.v + r.v };\n  return { k: n.k, l, r };\n}","tests":[{"in":"fold({k:'add', l:{k:'add', l:{k:'num',v:1}, r:{k:'num',v:2}}, r:{k:'num',v:3}})","out":"{k:'num', v:6}"},{"in":"fold({k:'add', l:{k:'num',v:1}, r:{k:'add', l:{k:'num',v:2}, r:{k:'num',v:3}}})","out":"{k:'num', v:6}"},{"in":"fold({k:'add', l:{k:'num',v:1}, r:{k:'num',v:2}})","out":"{k:'num', v:3}"},{"in":"fold({k:'add', l:{k:'var',n:'x'}, r:{k:'num',v:2}})","out":"{k:'add', l:{k:'var',n:'x'}, r:{k:'num',v:2}}"}],"edge":[{"in":"fold({k:'num', v:0})","out":"{k:'num', v:0}"},{"in":"fold({k:'add', l:{k:'add', l:{k:'var',n:'x'}, r:{k:'num',v:1}}, r:{k:'num',v:2}})","out":"{k:'add', l:{k:'add', l:{k:'var',n:'x'}, r:{k:'num',v:1}}, r:{k:'num',v:2}}"}],"ex":"원인: 자식을 <b>먼저 접지 않고</b> 지금 노드만 봅니다. <code>(1+2)+3</code> 의 왼쪽 자식은 아직 <code>add</code> 이므로 '상수 둘' 조건에 걸리지 않아 통째로 남습니다. 깊이 1 짜리 예제에서는 완벽히 동작합니다.\n해결: <b>후위 순회</b>로 만듭니다 — 자식을 먼저 접고, 그 결과가 둘 다 상수일 때 지금 노드를 접습니다. 접히지 않으면 <b>접힌 자식으로 새 노드</b>를 만들어 돌려줍니다.\n재발 방지: 트리를 바꾸는 패스는 '<b>어느 순서로 방문하는가</b>' 가 곧 알고리즘입니다. 상수 접기·타입 추론·크기 계산은 <b>아래에서 위로</b>(후위), 스코프 주입·상수 전파는 <b>위에서 아래로</b>(전위)입니다. 테스트에는 <b>깊이 2 이상</b>의 트리와 <b>일부만 접히는</b> 트리를 넣으세요."},{"t":"code","run":"js","k":"부수효과가 있는 명령까지 지운다","cat":"debug","q":"결과를 <b>아무도 쓰지 않는</b> 명령을 한 번의 훑기로 지웁니다. 다만 <code>eff:true</code> 인 명령은 <b>부수효과</b>가 있으므로 남겨야 합니다. 그런데 반환값을 안 쓰는 함수 호출이 통째로 사라져 <b>로그도 저장도 안 됩니다</b>.","src":"function dce(instrs) {\n  const used = new Set();\n  for (const it of instrs) (it.args || []).forEach(a => used.add(a));\n  return instrs.filter(it => used.has(it.dst)).map(it => it.id);\n}","sol":"function dce(instrs) {\n  const used = new Set();\n  for (const it of instrs) (it.args || []).forEach(a => used.add(a));\n  return instrs.filter(it => it.eff || used.has(it.dst)).map(it => it.id);\n}","tests":[{"in":"dce([{id:1,dst:'r',args:[],eff:true}])","out":"[1]"},{"in":"dce([{id:1,dst:'x',args:[]},{id:2,dst:'y',args:['x'],eff:true}])","out":"[1,2]"},{"in":"dce([{id:1,dst:'a',args:[]},{id:2,dst:'b',args:['a']}])","out":"[1]"},{"in":"dce([])","out":"[]"}],"edge":[{"in":"dce([{id:1,dst:'a',args:['a']}])","out":"[1]"},{"in":"dce([{id:1,dst:'a',args:[]}])","out":"[]"}],"ex":"원인: '쓰이지 않는 값' 과 '<b>하는 일이 없는 명령</b>' 을 같은 것으로 봤습니다. 파일 쓰기·네트워크 호출·전역 변경은 <b>결과를 안 써도 반드시 실행돼야</b> 합니다. 모든 명령이 순수한 예제에서는 최적화가 완벽해 보입니다.\n해결: 부수효과 표시를 살아 있음의 <b>또 다른 근거</b>로 넣습니다 — <code>it.eff || used.has(it.dst)</code>.\n재발 방지: 최적화 패스는 '<b>관찰 가능한 동작을 바꾸지 않는다</b>' 는 약속 위에서만 정당합니다. 그래서 IR 은 명령마다 <b>순수한가</b>를 들고 다녀야 하고, 모르면 <b>보수적으로 부수효과 있음</b>으로 둬야 합니다. 최적화 테스트에는 언제나 <b>부수효과가 있는 명령</b>을 하나 섞어 두세요."},{"t":"code","run":"js","k":"나중에 정의된 심볼을 미정의로 본다","cat":"debug","q":"오브젝트 파일들을 링크해 <b>정의를 못 찾은 심볼</b>을 사전순으로 모읍니다. 정의가 <b>먼저</b> 나오면 맞는데, 쓰는 쪽이 앞에 있고 정의가 <b>뒤 파일</b>에 있으면 미정의로 잘못 보고합니다.","src":"function link(objs) {\n  const def = new Set();\n  const missing = [];\n  for (const o of objs) {\n    (o.use || []).forEach(s => { if (!def.has(s)) missing.push(s); });\n    (o.def || []).forEach(s => def.add(s));\n  }\n  return [...new Set(missing)].sort();\n}","sol":"function link(objs) {\n  const def = new Set(), need = new Set();\n  for (const o of objs) {\n    (o.def || []).forEach(s => def.add(s));\n    (o.use || []).forEach(s => need.add(s));\n  }\n  return [...need].filter(s => !def.has(s)).sort();\n}","tests":[{"in":"link([{use:['f']},{def:['f']}])","out":"[]"},{"in":"link([{use:['z']},{use:['z']},{def:['z']}])","out":"[]"},{"in":"link([{def:['f']},{use:['f']}])","out":"[]"},{"in":"link([{use:['g']}])","out":"['g']"}],"edge":[{"in":"link([])","out":"[]"},{"in":"link([{def:['a']},{use:['a','b']}])","out":"['b']"}],"ex":"원인: 정의 집합을 <b>훑는 도중에 채우면서</b> 그때그때 판정했습니다. 그래서 판정 시점에 아직 안 읽은 파일의 정의는 없는 것으로 보입니다. 컴파일 순서를 바꾸면 결과가 달라지는데, 링커의 심볼 해석은 <b>파일 순서와 무관</b>해야 합니다.\n해결: <b>두 번 훑습니다</b> — 먼저 모든 정의와 모든 참조를 모으고, 그다음 차집합을 냅니다. 판정이 <b>전체를 다 본 뒤</b>에 일어나므로 순서에 흔들리지 않습니다.\n재발 방지: '모으고 나서 판정한다' 는 이름 해석·의존성 검사·미사용 탐지에 공통으로 필요한 구조입니다. 한 번의 훑기로 답하려면 <b>전방 참조가 없다</b>는 근거가 있어야 합니다. 테스트에는 같은 입력을 <b>순서만 바꿔</b> 두 벌 넣으면 이 부류가 전부 잡힙니다."},{"t":"code","run":"js","k":"스택에서 꺼낸 두 값의 순서가 뒤집혔다","cat":"debug","q":"아주 작은 스택 머신입니다. <code>push</code> 로 값을 얹고 <code>sub</code>·<code>div</code> 는 <b>먼저 얹은 값에서 나중 값을</b> 빼거나 나눕니다. 마지막에 스택 맨 위를 돌려줍니다. 그런데 뺄셈의 부호가 뒤집히고 나눗셈이 역수로 나옵니다.","src":"function run(code) {\n  const st = [];\n  for (const ins of code) {\n    if (ins[0] === 'push') st.push(ins[1]);\n    else {\n      const a = st.pop(), b = st.pop();\n      st.push(ins[0] === 'sub' ? a - b : a / b);\n    }\n  }\n  return st[st.length - 1];\n}","sol":"function run(code) {\n  const st = [];\n  for (const ins of code) {\n    if (ins[0] === 'push') st.push(ins[1]);\n    else {\n      const a = st.pop(), b = st.pop();\n      st.push(ins[0] === 'sub' ? b - a : b / a);\n    }\n  }\n  return st[st.length - 1];\n}","tests":[{"in":"run([['push',10],['push',3],['sub']])","out":"7"},{"in":"run([['push',12],['push',4],['div']])","out":"3"},{"in":"run([['push',1],['push',1],['sub']])","out":"0"},{"in":"run([['push',5]])","out":"5"}],"edge":[{"in":"run([['push',8],['push',2],['div'],['push',1],['sub']])","out":"3"},{"in":"run([['push',0],['push',5],['sub']])","out":"-5"}],"ex":"원인: 스택은 <b>나중에 넣은 것이 먼저 나옵니다</b>. 그래서 첫 <code>pop</code> 이 <b>오른쪽 피연산자</b>이고 두 번째 <code>pop</code> 이 왼쪽입니다. 이름을 <code>a</code>·<code>b</code> 로 붙이고 <code>a - b</code> 라고 적는 순간 순서가 뒤집힙니다. 덧셈·곱셈만으로 시험하면 <b>교환법칙 덕분에</b> 전부 통과합니다.\n해결: 꺼낸 순서를 그대로 뜻으로 옮깁니다 — 나중에 꺼낸 것이 왼쪽이므로 <code>b - a</code>·<code>b / a</code> 입니다. 이름을 <code>rhs</code>·<code>lhs</code> 로 두면 실수가 줄어듭니다.\n재발 방지: 스택 머신·RPN·후위 순회 코드 생성은 전부 이 함정을 공유합니다. 테스트를 <b>교환법칙이 없는 연산</b>(<code>-</code>·<code>/</code>·<code>%</code>·비교)으로 만들고, 같은 값 두 개(<code>1-1</code>)로만 시험하지 마세요 — 그런 입력은 뒤집혀도 통과합니다."}]}],"ord":13}]);
